VALUES
('curated-chunxiao','春晓','Spring Morning','孟浩然','Mèng Hàorán','唐','精选',TRUE,'["春眠不觉晓，处处闻啼鸟。", "夜来风雨声，花落知多少。"]'::jsonb,'["chūn mián bù jué xiǎo, chù chù wén tí niǎo.", "yè lái fēng yǔ shēng, huā luò zhī duō shǎo."]'::jsonb,FALSE,'["Sleeping in spring, I missed the dawn; birds are singing everywhere.", "Last night I heard wind and rain — how many flowers fell?"]'::jsonb,'["春天", "小鸟", "花", "下雨", "睡觉", "spring", "bird", "flower", "rain", "sleep"]'::jsonb,'春','春分','春天睡得香，醒来听见小鸟叫，想起昨晚的风雨，不知吹落了多少花瓣。','A cozy spring sleep, birdsong at dawn, and a gentle wonder about the flowers after rain.','["清晨", "啼鸟", "落花", "春雨初歇", "窗前"]'::jsonb,NULL),
('curated-yongliu','咏柳','Ode to the Willow','贺知章','Hè Zhīzhāng','唐','精选',TRUE,'["碧玉妆成一树高，万条垂下绿丝绦。", "不知细叶谁裁出，二月春风似剪刀。"]'::jsonb,'["bì yù zhuāng chéng yī shù gāo, wàn tiáo chuí xià lǜ sī tāo.", "bù zhī xì yè shuí cái chū, èr yuè chūn fēng sì jiǎn dāo."]'::jsonb,FALSE,'["The tall willow looks dressed in green jade, with thousands of silky ribbons hanging down.", "Who cut out these fine leaves? The spring wind of February — sharp as scissors!"]'::jsonb,'["柳树", "春风", "春天", "willow", "spring wind", "spring"]'::jsonb,'春','立春','柳树像碧玉打扮的姑娘，春风像剪刀，裁出了细细的柳叶。','The willow is dressed like a lady in jade, and the spring wind is the scissors that cut her leaves.','["垂柳", "嫩绿柳条", "春风", "河岸"]'::jsonb,NULL),
('curated-cunju','村居','Village Life','高鼎','Gāo Dǐng','清','精选',TRUE,'["草长莺飞二月天，拂堤杨柳醉春烟。", "儿童散学归来早，忙趁东风放纸鸢。"]'::jsonb,'["cǎo zhǎng yīng fēi èr yuè tiān, fú dī yáng liǔ zuì chūn yān.", "ér tóng sàn xué guī lái zǎo, máng chèn dōng fēng fàng zhǐ yuān."]'::jsonb,FALSE,'["Grass grows and orioles fly in the second month; willows by the bank sway in the spring mist.", "Children come home early from school, hurrying to fly kites on the east wind."]'::jsonb,'["风筝", "春天", "儿童", "柳树", "kite", "spring", "children", "willow"]'::jsonb,'春','雨水','小草长高了，黄莺飞来了，小朋友放学早，赶紧趁着东风放风筝！','Spring is here — grass, birds, and kids rushing out after school to fly kites in the wind!','["放风筝的孩子", "杨柳", "春烟", "田野"]'::jsonb,NULL),
('curated-qingming','清明','Qingming Festival','杜牧','Dù Mù','唐','精选',TRUE,'["清明时节雨纷纷，路上行人欲断魂。", "借问酒家何处有，牧童遥指杏花村。"]'::jsonb,'["qīng míng shí jié yǔ fēn fēn, lù shàng xíng rén yù duàn hún.", "jiè wèn jiǔ jiā hé chù yǒu, mù tóng yáo zhǐ xìng huā cūn."]'::jsonb,FALSE,'["Around Qingming, a soft drizzle keeps falling; travelers on the road feel heavy-hearted.", "Asking where an inn might be, a little cowherd points far away — to Apricot Blossom Village."]'::jsonb,'["清明", "下雨", "牧童", "杏花", "qingming", "rain", "cowherd", "apricot blossom"]'::jsonb,'春','清明','清明前后总爱下小雨，牧童指着远处开满杏花的小村庄。','It often drizzles around Qingming; a cowherd points to a village full of apricot blossoms.','["细雨", "牧童骑牛", "杏花村", "田间小路", "斜风细雨"]'::jsonb,NULL),
('curated-xiaochi','小池','The Little Pond','杨万里','Yáng Wànlǐ','宋','精选',TRUE,'["泉眼无声惜细流，树阴照水爱晴柔。", "小荷才露尖尖角，早有蜻蜓立上头。"]'::jsonb,'["quán yǎn wú shēng xī xì liú, shù yīn zhào shuǐ ài qíng róu.", "xiǎo hé cái lù jiān jiān jiǎo, zǎo yǒu qīng tíng lì shàng tóu."]'::jsonb,FALSE,'["A quiet spring lets water trickle gently; tree shadows love the soft sunny pond.", "A little lotus bud just shows its pointy tip — and a dragonfly is already standing on it!"]'::jsonb,'["荷花", "蜻蜓", "夏天", "池塘", "lotus", "dragonfly", "summer", "pond"]'::jsonb,'夏','小满','小荷叶刚刚露出尖尖角，蜻蜓就飞来站在上面啦！','The baby lotus just poked out its tip, and a dragonfly already landed on it!','["小荷尖角", "蜻蜓", "池塘", "树荫", "晴日柔光"]'::jsonb,NULL),
('curated-xiaochu-jingci','晓出净慈寺送林子方','West Lake in June','杨万里','Yáng Wànlǐ','宋','精选',TRUE,'["毕竟西湖六月中，风光不与四时同。", "接天莲叶无穷碧，映日荷花别样红。"]'::jsonb,'["bì jìng xī hú liù yuè zhōng, fēng guāng bù yǔ sì shí tóng.", "jiē tiān lián yè wú qióng bì, yìng rì hé huā bié yàng hóng."]'::jsonb,FALSE,'["West Lake in June is truly special — its scenery is like no other season.", "Lotus leaves reach the sky in endless green; lotus flowers glow extra red in the sun."]'::jsonb,'["荷花", "西湖", "夏天", "莲叶", "lotus", "west lake", "summer", "lotus leaves"]'::jsonb,'夏','小暑','六月的西湖，莲叶绿到天边，荷花被太阳照得特别红。','In June at West Lake, green lotus leaves stretch to the sky and the flowers shine red in the sun.','["接天莲叶", "映日荷花", "西湖", "盛夏晨光"]'::jsonb,NULL),
('curated-suojian','所见','What I Saw','袁枚','Yuán Méi','清','精选',TRUE,'["牧童骑黄牛，歌声振林樾。", "意欲捕鸣蝉，忽然闭口立。"]'::jsonb,'["mù tóng qí huáng niú, gē shēng zhèn lín yuè.", "yì yù bǔ míng chán, hū rán bì kǒu lì."]'::jsonb,FALSE,'["A cowherd rides his ox, his song ringing through the woods.", "Wanting to catch a singing cicada, he suddenly shuts his mouth and stands still."]'::jsonb,'["牧童", "蝉", "夏天", "黄牛", "cowherd", "cicada", "summer", "ox"]'::jsonb,'夏','大暑','牧童唱着歌骑黄牛，想抓树上的蝉，马上闭紧嘴巴站住了。','A singing cowherd spots a cicada — and instantly goes quiet to sneak up on it.','["牧童骑牛", "树林", "鸣蝉", "夏日午后"]'::jsonb,NULL),
('curated-xiaoer-chuidiao','小儿垂钓','The Little Angler','胡令能','Hú Lìngnéng','唐','精选',TRUE,'["蓬头稚子学垂纶，侧坐莓苔草映身。", "路人借问遥招手，怕得鱼惊不应人。"]'::jsonb,'["péng tóu zhì zǐ xué chuí lún, cè zuò méi tái cǎo yìng shēn.", "lù rén jiè wèn yáo zhāo shǒu, pà dé yú jīng bù yìng rén."]'::jsonb,FALSE,'["A messy-haired child learns to fish, sitting side-on in the moss, half-hidden by grass.", "When a passerby asks the way, he only waves — afraid to scare the fish, he says nothing."]'::jsonb,'["钓鱼", "儿童", "夏天", "fishing", "children", "summer"]'::jsonb,'夏','夏至','小娃娃学钓鱼，怕吓跑小鱼，连话都不敢回答呢。','The little angler is so careful not to scare the fish that he won’t even talk!','["垂钓孩童", "河边青苔", "草丛", "安静的水面"]'::jsonb,NULL),
('curated-shanxing','山行','A Mountain Walk','杜牧','Dù Mù','唐','精选',TRUE,'["远上寒山石径斜，白云生处有人家。", "停车坐爱枫林晚，霜叶红于二月花。"]'::jsonb,'["yuǎn shàng hán shān shí jìng xié, bái yún shēng chù yǒu rén jiā.", "tíng chē zuò ài fēng lín wǎn, shuāng yè hóng yú èr yuè huā."]'::jsonb,FALSE,'["A stone path winds up the cool mountain; homes appear where white clouds rise.", "I stop my carriage to admire the maple woods at dusk — frosted leaves redder than spring flowers."]'::jsonb,'["枫叶", "秋天", "霜", "山", "maple", "autumn", "frost", "mountain"]'::jsonb,'秋','霜降','秋天的枫叶被霜一打，比春天的花还要红！','After the frost, autumn maple leaves turn even redder than spring flowers!','["红枫林", "山间石径", "白云", "山中人家", "夕照"]'::jsonb,NULL),
('curated-jiuyuejiuri','九月九日忆山东兄弟','Missing My Brothers on Double Ninth Day','王维','Wáng Wéi','唐','精选',TRUE,'["独在异乡为异客，每逢佳节倍思亲。", "遥知兄弟登高处，遍插茱萸少一人。"]'::jsonb,'["dú zài yì xiāng wéi yì kè, měi féng jiā jié bèi sī qīn.", "yáo zhī xiōng dì dēng gāo chù, biàn chā zhū yú shǎo yī rén."]'::jsonb,FALSE,'["Alone in a faraway land, I miss my family even more on festival days.", "I know my brothers are climbing the hills, wearing dogwood — with one person missing: me."]'::jsonb,'["重阳", "思念", "登高", "茱萸", "秋天", "double ninth", "missing family", "hiking", "autumn"]'::jsonb,'秋','重阳节','重阳节要登高、插茱萸，诗人在远方想念家里的亲人。','On Double Ninth Day people climb hills together; the poet, far from home, misses his family.','["登高远眺", "茱萸", "秋日山峰", "思乡"]'::jsonb,NULL),
('curated-fengqiao-yebo','枫桥夜泊','Night Mooring by Maple Bridge','张继','Zhāng Jì','唐','精选',TRUE,'["月落乌啼霜满天，江枫渔火对愁眠。", "姑苏城外寒山寺，夜半钟声到客船。"]'::jsonb,'["yuè luò wū tí shuāng mǎn tiān, jiāng fēng yú huǒ duì chóu mián.", "gū sū chéng wài hán shān sì, yè bàn zhōng shēng dào kè chuán."]'::jsonb,FALSE,'["The moon sets, crows caw, frost fills the sky; by riverside maples and fishing lights, I lie sleepless.", "From Hanshan Temple outside Suzhou, the midnight bell reaches my boat."]'::jsonb,'["秋天", "霜", "月亮", "枫树", "夜晚", "autumn", "frost", "moon", "maple", "night"]'::jsonb,'秋','霜降','秋夜的江边，月亮落下、霜气满天，远处传来寺庙的钟声。','On a frosty autumn night by the river, a faraway temple bell rings through the dark.','["江枫", "渔火", "客船", "秋夜", "古寺钟声"]'::jsonb,NULL),
('curated-jingyesi','静夜思','Thoughts on a Quiet Night','李白','Lǐ Bái','唐','精选',TRUE,'["床前明月光，疑是地上霜。", "举头望明月，低头思故乡。"]'::jsonb,'["chuáng qián míng yuè guāng, yí shì dì shàng shuāng.", "jǔ tóu wàng míng yuè, dī tóu sī gù xiāng."]'::jsonb,FALSE,'["Bright moonlight before my bed — I thought it was frost on the ground.", "I look up at the bright moon, then lower my head, thinking of home."]'::jsonb,'["月亮", "思念", "中秋", "夜晚", "moon", "homesick", "mid-autumn", "night"]'::jsonb,'秋','中秋节','月光洒在床前像霜一样白，抬头看月亮，就想起了家乡。','The moonlight looks like frost; looking at the moon makes the poet think of home.','["明月", "月光如霜", "窗前", "安静的夜"]'::jsonb,NULL),
('curated-jiangxue','江雪','River Snow','柳宗元','Liǔ Zōngyuán','唐','精选',TRUE,'["千山鸟飞绝，万径人踪灭。", "孤舟蓑笠翁，独钓寒江雪。"]'::jsonb,'["qiān shān niǎo fēi jué, wàn jìng rén zōng miè.", "gū zhōu suō lì wēng, dú diào hán jiāng xuě."]'::jsonb,FALSE,'["No birds fly over the thousand mountains; no footprints on the ten thousand paths.", "One old man in a straw cape, alone in a little boat, fishing in the snowy river."]'::jsonb,'["雪", "冬天", "钓鱼", "江", "snow", "winter", "fishing", "river"]'::jsonb,'冬','大雪','大雪天里，一位老爷爷穿着蓑衣，独自在江上钓鱼。','In the falling snow, one old grandpa fishes all alone on the quiet river.','["孤舟", "蓑笠翁", "寒江", "漫天飞雪", "空寂群山"]'::jsonb,NULL),
('curated-meihua','梅花','Plum Blossoms','王安石','Wáng Ānshí','宋','精选',TRUE,'["墙角数枝梅，凌寒独自开。", "遥知不是雪，为有暗香来。"]'::jsonb,'["qiáng jiǎo shù zhī méi, líng hán dú zì kāi.", "yáo zhī bù shì xuě, wèi yǒu àn xiāng lái."]'::jsonb,FALSE,'["A few plum branches by the wall bloom all alone in the cold.", "From far away I know they are not snow — a secret sweet scent drifts over."]'::jsonb,'["梅花", "冬天", "雪", "香", "plum blossom", "winter", "snow", "fragrance"]'::jsonb,'冬','小寒','墙角的梅花不怕冷，远远就能闻到淡淡的香味，所以知道那不是雪。','Brave plum flowers bloom in the cold — you can tell they’re not snow by their sweet smell.','["墙角梅枝", "白梅", "残雪", "寒冬清晨"]'::jsonb,NULL),
('curated-yuanri','元日','New Year’s Day','王安石','Wáng Ānshí','宋','精选',TRUE,'["爆竹声中一岁除，春风送暖入屠苏。", "千门万户曈曈日，总把新桃换旧符。"]'::jsonb,'["bào zhú shēng zhōng yī suì chú, chūn fēng sòng nuǎn rù tú sū.", "qiān mén wàn hù tóng tóng rì, zǒng bǎ xīn táo huàn jiù fú."]'::jsonb,FALSE,'["Firecrackers crackle as the old year ends; spring wind brings warmth to the New Year wine.", "The rising sun shines on every home, and everyone hangs new lucky charms for old."]'::jsonb,'["春节", "过年", "爆竹", "春联", "spring festival", "chinese new year", "firecracker", "couplets"]'::jsonb,'冬','春节','过年啦！放爆竹、喝屠苏酒、换上新的春联，家家户户亮堂堂。','It’s Chinese New Year! Firecrackers, festive wine, and brand-new red couplets on every door.','["红灯笼", "春联", "爆竹", "朝阳", "家家户户"]'::jsonb,NULL),
('curated-minnong','悯农（其二）','Pity the Farmers','李绅','Lǐ Shēn','唐','精选',TRUE,'["锄禾日当午，汗滴禾下土。", "谁知盘中餐，粒粒皆辛苦。"]'::jsonb,'["chú hé rì dāng wǔ, hàn dī hé xià tǔ.", "shuí zhī pán zhōng cān, lì lì jiē xīn kǔ."]'::jsonb,FALSE,'["Hoeing under the noon sun, sweat drips onto the soil below the seedlings.", "Do you know? Every grain of rice on your plate comes from hard, hard work."]'::jsonb,'["农事", "粮食", "珍惜", "夏天", "farming", "food", "gratitude", "summer"]'::jsonb,'夏','芒种','农民伯伯顶着大太阳种地，每一粒粮食都来得不容易，要珍惜哦。','Farmers work under the hot sun — every grain of rice is precious, so don’t waste food!','["农田", "烈日", "锄地的农人", "禾苗"]'::jsonb,NULL),
('curated-denguanquelou','登鹳雀楼','Climbing Stork Tower','王之涣','Wáng Zhīhuàn','唐','精选',TRUE,'["白日依山尽，黄河入海流。", "欲穷千里目，更上一层楼。"]'::jsonb,'["bái rì yī shān jìn, huáng hé rù hǎi liú.", "yù qióng qiān lǐ mù, gèng shàng yī céng lóu."]'::jsonb,FALSE,'["The white sun sets behind the mountains; the Yellow River flows to the sea.", "To see a thousand miles farther, climb one more floor!"]'::jsonb,'["黄河", "登高", "励志", "太阳", "yellow river", "climbing", "inspiration", "sun"]'::jsonb,NULL,NULL,'想看得更远，就要再登上一层楼——学习也是这样呀。','To see farther, climb higher — learning works the same way!','["落日群山", "黄河奔流", "高楼远眺"]'::jsonb,NULL),
('curated-wanglushan','望庐山瀑布','Watching the Lushan Waterfall','李白','Lǐ Bái','唐','精选',TRUE,'["日照香炉生紫烟，遥看瀑布挂前川。", "飞流直下三千尺，疑是银河落九天。"]'::jsonb,'["rì zhào xiāng lú shēng zǐ yān, yáo kàn pù bù guà qián chuān.", "fēi liú zhí xià sān qiān chǐ, yí shì yín hé luò jiǔ tiān."]'::jsonb,FALSE,'["Sunlight on Incense Burner Peak makes purple mist; far off, a waterfall hangs like a ribbon.", "It plunges three thousand feet — like the Milky Way falling from the sky!"]'::jsonb,'["瀑布", "山", "夏天", "银河", "waterfall", "mountain", "summer", "milky way"]'::jsonb,'夏',NULL,'瀑布从高高的山上冲下来，像银河从天上掉下来一样壮观！','The waterfall rushes down the mountain like the Milky Way pouring from the sky!','["飞瀑", "紫烟缭绕", "青山", "水雾"]'::jsonb,NULL),
('curated-jueju-huangli','绝句','A Quatrain','杜甫','Dù Fǔ','唐','精选',TRUE,'["两个黄鹂鸣翠柳，一行白鹭上青天。", "窗含西岭千秋雪，门泊东吴万里船。"]'::jsonb,'["liǎng gè huáng lí míng cuì liǔ, yī háng bái lù shàng qīng tiān.", "chuāng hán xī lǐng qiān qiū xuě, mén bó dōng wú wàn lǐ chuán."]'::jsonb,FALSE,'["Two orioles sing in the green willow; a line of white egrets rises into the blue sky.", "My window frames the western peaks’ ancient snow; by my door moor boats from ten thousand miles away."]'::jsonb,'["黄鹂", "白鹭", "春天", "雪山", "柳树", "oriole", "egret", "spring", "snow mountain", "willow"]'::jsonb,'春','春分','窗外有唱歌的黄鹂、飞上蓝天的白鹭，还能看见远处的雪山。','Singing orioles, flying egrets, and faraway snowy mountains — all from one window!','["黄鹂翠柳", "白鹭青天", "远山积雪", "江边船只"]'::jsonb,NULL),
('curated-jiangnan','江南','Jiangnan (South of the River)','汉乐府','Hàn Yuèfǔ (Han folk song)','汉','精选',TRUE,'["江南可采莲，莲叶何田田。", "鱼戏莲叶间。", "鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"]'::jsonb,'["jiāng nán kě cǎi lián, lián yè hé tián tián.", "yú xì lián yè jiān.", "yú xì lián yè dōng, yú xì lián yè xī, yú xì lián yè nán, yú xì lián yè běi."]'::jsonb,FALSE,'["In Jiangnan we pick lotus; how lush and full the lotus leaves are!", "Fish play among the lotus leaves.", "Fish play east of the leaves, west of the leaves, south of the leaves, north of the leaves."]'::jsonb,'["采莲", "莲叶", "鱼", "夏天", "江南", "lotus picking", "lotus leaves", "fish", "summer", "jiangnan"]'::jsonb,'夏','大暑','江南的莲叶挨挨挤挤，小鱼在莲叶间游来游去，多快活！','Among the crowded lotus leaves of Jiangnan, happy little fish dart east, west, south, and north!','["采莲小船", "田田莲叶", "游鱼", "江南水乡"]'::jsonb,NULL),
('base-1','行宫',NULL,'元稹',NULL,'唐','唐诗',FALSE,'["寥落古行宫，宫花寂寞红。", "白头宫女在，闲坐说玄宗。"]'::jsonb,'["liáo luò gǔ xíng gōng,gōng huā jì mò hóng.", "bái tóu gōng nǚ zài,xián zuò shuō xuán zōng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-2','登鹳雀楼',NULL,'王之涣',NULL,'唐','唐诗',FALSE,'["白日依山尽，黄河入海流。", "欲穷千里目，更上一层楼。"]'::jsonb,'["bái rì yī shān jǐn,huáng hé rù hǎi liú.", "yù qióng qiān lǐ mù,gèng shàng yī céng lóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-3','新嫁娘词',NULL,'王建',NULL,'唐','唐诗',FALSE,'["三日入厨下，洗手作羹汤。", "未谙姑食性，先遣小姑尝。"]'::jsonb,'["sān rì rù chú xià,xǐ shǒu zuò gēng tāng.", "wèi ān gū shí xìng,xiān qiǎn xiǎo gū cháng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-4','相思',NULL,'王维',NULL,'唐','唐诗',FALSE,'["红豆生南国，春来发几枝。", "愿君多采撷，此物最相思。"]'::jsonb,'["hóng dòu shēng nán guó,chūn lái fā jǐ zhī.", "yuàn jūn duō cǎi xié,cǐ wù zuì xiāng sī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-5','杂诗',NULL,'王维',NULL,'唐','唐诗',FALSE,'["君自故乡来，应知故乡事。", "来日绮窗前，寒梅著花未？"]'::jsonb,'["jūn zì gù xiāng lái,yīng zhī gù xiāng shì.", "lái rì qǐ chuāng qián,hán méi zhù huā wèi?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-6','鹿柴',NULL,'王维',NULL,'唐','唐诗',FALSE,'["空山不见人，但闻人语响。", "返景入深林，复照青苔上。"]'::jsonb,'["kōng shān bú jiàn rén,dàn wén rén yǔ xiǎng.", "fǎn jǐng rù shēn lín,fù zhào qīng tái shàng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-7','竹里馆',NULL,'王维',NULL,'唐','唐诗',FALSE,'["独坐幽篁里，弹琴复长啸。", "深林人不知，明月来相照。"]'::jsonb,'["dú zuò yōu huáng lǐ,tán qín fù cháng xiào.", "shēn lín rén bù zhī,míng yuè lái xiāng zhào."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-8','山中送别',NULL,'王维',NULL,'唐','唐诗',FALSE,'["山中相送罢，日暮掩柴扉。", "春草明年绿，王孙归不归？"]'::jsonb,'["shān zhōng xiāng sòng bà,rì mù yǎn chái fēi.", "chūn cǎo míng nián lǜ,wáng sūn guī bù guī?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-9','问刘十九',NULL,'白居易',NULL,'唐','唐诗',FALSE,'["绿蚁新醅酒，红泥小火炉。", "晚来天欲雪，能饮一杯无？"]'::jsonb,'["lǜ yǐ xīn pēi jiǔ,hóng ní xiǎo huǒ lú.", "wǎn lái tiān yù xuě,néng yǐn yī bēi wú?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-10','哥舒歌',NULL,'西鄙人',NULL,'唐','唐诗',FALSE,'["北斗七星高，哥舒夜带刀。", "至今窥牧马，不敢过临洮。"]'::jsonb,'["běi dǒu qī xīng gāo,gē shū yè dài dāo.", "zhì jīn kuī mù mǎ,bù gǎn guò lín táo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-11','静夜思',NULL,'李白',NULL,'唐','唐诗',FALSE,'["床前明月光，疑是地上霜，", "举头望明月，低头思故乡。"]'::jsonb,'["chuáng qián míng yuè guāng,yí shì dì shàng shuāng,", "jǔ tóu wàng míng yuè,dī tóu sī gù xiāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-12','怨情',NULL,'李白',NULL,'唐','唐诗',FALSE,'["美人卷珠帘，深坐颦蛾眉。", "但见泪痕湿，不知心恨谁。"]'::jsonb,'["měi rén juǎn zhū lián,shēn zuò pín é méi.", "dàn jiàn lèi hén shī,bù zhī xīn hèn shuí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-13','登乐游原',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["向晚意不适，驱车登古原。", "夕阳无限好，只是近黄昏。"]'::jsonb,'["xiàng wǎn yì bù shì,qū chē dēng gǔ yuán.", "xī yáng wú xiàn hǎo,zhǐ shì jìn huáng hūn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-14','听筝',NULL,'李端',NULL,'唐','唐诗',FALSE,'["鸣筝金粟柱，素手玉房前。", "欲得周郎顾，时时误拂弦。"]'::jsonb,'["míng zhēng jīn sù zhù,sù shǒu yù fáng qián.", "yù dé zhōu láng gù,shí shí wù fú xián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-15','渡汉江',NULL,'宋之问',NULL,'唐','唐诗',FALSE,'["岭外音书断，经冬复历春。", "近乡情更怯，不敢问来人。"]'::jsonb,'["lǐng wài yīn shū duàn,jīng dōng fù lì chūn.", "jìn xiāng qíng gèng qiè,bù gǎn wèn lái rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-16','八阵图',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["功盖三分国，名成八阵图。", "江流石不转，遗恨失吞吴。"]'::jsonb,'["gōng gài sān fēn guó,míng chéng bā zhèn tú.", "jiāng liú shí bù zhuǎn,yí hèn shī tūn wú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-17','宿建德江',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["移舟泊烟渚，日暮客愁新。", "野旷天低树，江清月近人。"]'::jsonb,'["yí zhōu pō yān zhǔ,rì mù kè chóu xīn.", "yě kuàng tiān dī shù,jiāng qīng yuè jìn rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-18','春晓',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["春眠不觉晓，处处闻啼鸟。", "夜来风雨声，花落知多少。"]'::jsonb,'["chūn mián bù jué xiǎo,chù chù wén tí niǎo.", "yè lái fēng yǔ shēng,huā luò zhī duō shǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-19','春怨',NULL,'金昌绪',NULL,'唐','唐诗',FALSE,'["打起黄莺儿，莫教枝上啼。", "啼时惊妾梦，不得到辽西。"]'::jsonb,'["dǎ qǐ huáng yīng ér,mò jiào zhī shàng tí.", "tí shí jīng qiè mèng,bù dé dào liáo xī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-20','江雪',NULL,'柳宗元',NULL,'唐','唐诗',FALSE,'["千山鸟飞绝，万径人踪灭。", "孤舟蓑笠翁，独钓寒江雪。"]'::jsonb,'["qiān shān niǎo fēi jué,wàn jìng rén zōng miè.", "gū zhōu suō lì wēng,dú diào hán jiāng xuě."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-21','秋夜寄邱员外',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["怀君属秋夜，散步咏凉天。", "空山松子落，幽人应未眠。"]'::jsonb,'["huái jūn shǔ qiū yè,sàn bù yǒng liáng tiān.", "kōng shān sōng zi luò,yōu rén yīng wèi mián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-22','终南望余雪',NULL,'祖咏',NULL,'唐','唐诗',FALSE,'["终南阴岭秀，积雪浮云端。", "林表明霁色，城中增暮寒。"]'::jsonb,'["zhōng nán yīn lǐng xiù,jī xuě fú yún duān.", "lín biǎo míng jì sè,chéng zhōng zēng mù hán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-23','宫词',NULL,'张祜',NULL,'唐','唐诗',FALSE,'["故国三千里，深宫二十年。", "一声何满子，双泪落君前。"]'::jsonb,'["gù guó sān qiān lǐ,shēn gōng èr shí nián.", "yī shēng hé mǎn zi,shuāng lèi luò jūn qián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-24','寻隐者不遇',NULL,'贾岛',NULL,'唐','唐诗',FALSE,'["松下问童子，言师采药去。", "只在此山中，云深不知处。"]'::jsonb,'["sōng xià wèn tóng zi,yán shī cǎi yào qù.", "zhǐ zài cǐ shān zhōng,yún shēn bù zhī chù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-25','送崔九',NULL,'裴迪',NULL,'唐','唐诗',FALSE,'["归山深浅去，须尽丘壑美。", "莫学武陵人，暂游桃源里。"]'::jsonb,'["guī shān shēn qiǎn qù,xū jǐn qiū hè měi.", "mò xué wǔ líng rén,zàn yóu táo yuán lǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-26','送灵澈上人',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["苍苍竹林寺，杳杳钟声晚。", "荷笠带斜阳，青山独归远。"]'::jsonb,'["cāng cāng zhú lín sì,yǎo yǎo zhōng shēng wǎn.", "hé lì dài xié yáng,qīng shān dú guī yuǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-27','听弹琴',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["泠泠七弦上，静听松风寒。", "古调虽自爱，今人多不弹。"]'::jsonb,'["líng líng qī xián shàng,jìng tīng sōng fēng hán.", "gǔ diào suī zì ài,jīn rén duō bù dàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-28','送上人',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["孤云将野鹤，岂向人间住。", "莫买沃洲山，时人已知处。"]'::jsonb,'["gū yún jiāng yě hè,qǐ xiàng rén jiān zhù.", "mò mǎi wò zhōu shān,shí rén yǐ zhī chù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-29','玉台体',NULL,'权德舆',NULL,'唐','唐诗',FALSE,'["昨夜裙带解，今朝蟢子飞。", "铅华不可弃，莫是藁砧归。"]'::jsonb,'["zuó yè qún dài jiě,jīn zhāo xǐ zi fēi.", "qiān huá bù kě qì,mò shì gǎo zhēn guī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言绝句'),
('base-30','芙蓉楼送辛渐',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["寒雨连江夜入吴，平明送客楚山孤。", "洛阳亲友如相问，一片冰心在玉壶。"]'::jsonb,'["hán yǔ lián jiāng yè rù wú,píng míng sòng kè chǔ shān gū.", "luò yáng qīn yǒu rú xiāng wèn,yī piàn bīng xīn zài yù hú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-31','闺怨',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["闺中少妇不知愁，春日凝妆上翠楼。", "忽见陌头杨柳色，悔教夫婿觅封侯。"]'::jsonb,'["guī zhōng shào fù bù zhī chóu,chūn rì níng zhuāng shàng cuì lóu.", "hū jiàn mò tóu yáng liǔ sè,huǐ jiào fū xù mì fēng hóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-32','春宫曲',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["昨夜风开露井桃，未央前殿月轮高。", "平阳歌舞新承宠，帘外春寒赐锦袍。"]'::jsonb,'["zuó yè fēng kāi lù jǐng táo,wèi yāng qián diàn yuè lún gāo.", "píng yáng gē wǔ xīn chéng chǒng,lián wài chūn hán cì jǐn páo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-33','九月九日忆山东兄弟',NULL,'王维',NULL,'唐','唐诗',FALSE,'["独在异乡为异客，每逢佳节倍思亲。", "遥知兄弟登高处，遍插茱萸少一人。"]'::jsonb,'["dú zài yì xiāng wèi yì kè,měi féng jiā jié bèi sī qīn.", "yáo zhī xiōng dì dēng gāo chù,biàn chā zhū yú shǎo yī rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-34','凉州词',NULL,'王翰',NULL,'唐','唐诗',FALSE,'["葡萄美酒夜光杯，欲饮琵琶马上催。", "醉卧沙场君莫笑，古来征战几人回？"]'::jsonb,'["pú táo měi jiǔ yè guāng bēi,yù yǐn pí pá mǎ shàng cuī.", "zuì wò shā chǎng jūn mò xiào,gǔ lái zhēng zhàn jǐ rén huí?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-35','后宫词',NULL,'白居易',NULL,'唐','唐诗',FALSE,'["泪湿罗巾梦不成，夜深前殿按歌声。", "红颜未老恩先断，斜倚薰笼坐到明。"]'::jsonb,'["lèi shī luó jīn mèng bù chéng,yè shēn qián diàn àn gē shēng.", "hóng yán wèi lǎo ēn xiān duàn,xié yǐ xūn lóng zuò dào míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-36','宫中词',NULL,'朱庆余',NULL,'唐','唐诗',FALSE,'["寂寂花时闭院门，美人相并立琼轩。", "含情欲说宫中事，鹦鹉前头不敢言。"]'::jsonb,'["jì jì huā shí bì yuàn mén,měi rén xiāng bìng lì qióng xuān.", "hán qíng yù shuō gōng zhōng shì,yīng wǔ qián tou bù gǎn yán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-37','近试上张水部',NULL,'朱庆余',NULL,'唐','唐诗',FALSE,'["洞房昨夜停红烛，待晓堂前拜舅姑。", "妆罢低声问夫婿，画眉深浅入时无。"]'::jsonb,'["dòng fáng zuó yè tíng hóng zhú,dài xiǎo táng qián bài jiù gū.", "zhuāng bà dī shēng wèn fū xù,huà méi shēn qiǎn rù shí wú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-38','逢入京使',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["故园东望路漫漫，双袖龙钟泪不干。", "马上相逢无纸笔，凭君传语报平安。"]'::jsonb,'["gù yuán dōng wàng lù màn màn,shuāng xiù lóng zhōng lèi bù gàn.", "mǎ shàng xiāng féng wú zhǐ bǐ,píng jūn chuán yǔ bào píng ān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-39','黄鹤楼送孟浩然之广陵',NULL,'李白',NULL,'唐','唐诗',FALSE,'["故人西辞黄鹤楼，烟花三月下扬州。", "孤帆远影碧空尽，唯见长江天际流。 "]'::jsonb,'["gù rén xī cí huáng hè lóu,yān huā sān yuè xià yáng zhōu.", "gū fān yuǎn yǐng bì kōng jǐn,wéi jiàn zhǎng jiāng tiān jì liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-40','早发白帝城',NULL,'李白',NULL,'唐','唐诗',FALSE,'["朝辞白帝彩云间，千里江陵一日还。", "两岸猿声啼不住，轻舟已过万重山。"]'::jsonb,'["cháo cí bái dì cǎi yún jiān,qiān lǐ jiāng líng yī rì hái.", "liǎng àn yuán shēng tí bú zhù,qīng zhōu yǐ guò wàn zhòng shān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-41','夜上受降城闻笛',NULL,'李益',NULL,'唐','唐诗',FALSE,'["回乐烽前沙似雪，受降城外月如霜。(回乐", "一作：回乐", "）", "不知何处吹芦管，一夜征人尽望乡。"]'::jsonb,'["huí lè fēng qián shā shì xuě,shòu xiáng chéng wài yuè rú shuāng.( huí lè", "yī zuò:huí lè", "）", "bù zhī hé chù chuī lú guǎn,yī yè zhēng rén jǐn wàng xiāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-42','贾生',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["宣室求贤访逐臣，贾生才调更无伦。", "可怜夜半虚前席，不问苍生问鬼神。"]'::jsonb,'["xuān shì qiú xián fǎng zhú chén,jiǎ shēng cái diào gèng wú lún.", "kě lián yè bàn xū qián xí,bù wèn cāng shēng wèn guǐ shén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-43','隋宫',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["乘兴南游不戒严，九重谁省谏书函。", "春风举国裁宫锦，半作障泥半作帆。"]'::jsonb,'["chéng xìng nán yóu bù jiè yán,jiǔ chóng shuí shěng jiàn shū hán.", "chūn fēng jǔ guó cái gōng jǐn,bàn zuò zhàng ní bàn zuò fān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-44','瑶池',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["瑶池阿母绮窗开，黄竹歌声动地哀。", "八骏日行三万里，穆王何事不重来。"]'::jsonb,'["yáo chí ā mǔ qǐ chuāng kāi,huáng zhú gē shēng dòng dì āi.", "bā jùn rì xíng sān wàn lǐ,mù wáng hé shì bù zhòng lái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-45','嫦娥',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["云母屏风烛影深，长河渐落晓星沉。", "嫦娥应悔偷灵药，碧海青天夜夜心。"]'::jsonb,'["yún mǔ píng fēng zhú yǐng shēn,cháng hé jiàn luò xiǎo xīng chén.", "cháng é yīng huǐ tōu líng yào,bì hǎi qīng tiān yè yè xīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-46','夜雨寄北',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["君问归期未有期，巴山夜雨涨秋池。", "何当共剪西窗烛，却话巴山夜雨时。"]'::jsonb,'["jūn wèn guī qī wèi yǒu qī,bā shān yè yǔ zhǎng qiū chí.", "hé dāng gòng jiǎn xī chuāng zhú,què huà bā shān yè yǔ shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-47','寄令狐郎中',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["嵩云秦树久离居，双鲤迢迢一纸书。", "休问梁园旧宾客，茂陵秋雨病相如。"]'::jsonb,'["sōng yún qín shù jiǔ lí jū,shuāng lǐ tiáo tiáo yī zhǐ shū.", "xiū wèn liáng yuán jiù bīn kè,mào líng qiū yǔ bìng xiāng rú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-48','为有',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["为有云屏无限娇，凤城寒尽怕春宵。", "无端嫁得金龟婿，辜负香衾事早朝。"]'::jsonb,'["wèi yǒu yún píng wú xiàn jiāo,fèng chéng hán jǐn pà chūn xiāo.", "wú duān jià dé jīn guī xù,gū fù xiāng qīn shì zǎo cháo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-49','江南逢李龟年',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["岐王宅里寻常见，崔九堂前几度闻。", "正是江南好风景，落花时节又逢君。"]'::jsonb,'["qí wáng zhái lǐ xún cháng jiàn,cuī jiǔ táng qián jǐ dù wén.", "zhèng shì jiāng nán hǎo fēng jǐng,luò huā shí jié yòu féng jūn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-50','赠别·其一',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["娉娉袅袅十三余，豆蔻梢头二月初。", "春风十里扬州路，卷上珠帘总不如。"]'::jsonb,'["pīng pīng niǎo niǎo shí sān yú,dòu kòu shāo tóu èr yuè chū.", "chūn fēng shí lǐ yáng zhōu lù,juǎn shàng zhū lián zǒng bù rú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-51','赠别·其二',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["多情却似总无情，唯觉樽前笑不成。", "蜡烛有心还惜别，替人垂泪到天明。"]'::jsonb,'["duō qíng què shì zǒng wú qíng,wéi jué zūn qián xiào bù chéng.", "là zhú yǒu xīn hái xī bié,tì rén chuí lèi dào tiān míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-52','金谷园',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["繁华事散逐香尘，流水无情草自春。", "日暮东风怨啼鸟，落花犹似坠楼人。"]'::jsonb,'["fán huá shì sàn zhú xiāng chén,liú shuǐ wú qíng cǎo zì chūn.", "rì mù dōng fēng yuàn tí niǎo,luò huā yóu shì zhuì lóu rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-53','寄扬州韩绰判官',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["青山隐隐水迢迢，秋尽江南草未凋。", "二十四桥明月夜，玉人何处教吹箫？"]'::jsonb,'["qīng shān yǐn yǐn shuǐ tiáo tiáo,qiū jǐn jiāng nán cǎo wèi diāo.", "èr shí sì qiáo míng yuè yè,yù rén hé chù jiào chuī xiāo?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-54','遣怀',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["落魄江南载酒行，楚腰纤细掌中轻。", "十年一觉扬州梦，赢得青楼薄幸名。"]'::jsonb,'["luò pò jiāng nán zài jiǔ xíng,chǔ yāo xiān xì zhǎng zhōng qīng.", "shí nián yī jiào yáng zhōu mèng,yíng dé qīng lóu bó xìng míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-55','秋夕',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["银烛秋光冷画屏，轻罗小扇扑流萤。", "天阶夜色凉如水，卧看牵牛织女星。"]'::jsonb,'["yín zhú qiū guāng lěng huà píng,qīng luó xiǎo shàn pū liú yíng.", "tiān jiē yè sè liáng rú shuǐ,wò kàn qiān niú zhī nǚ xīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-56','将赴吴兴登乐游原一绝',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["清时有味是无能，闲爱孤云静爱僧。", "欲把一麾江海去，乐游原上望昭陵。"]'::jsonb,'["qīng shí yǒu wèi shì wú néng,xián ài gū yún jìng ài sēng.", "yù bǎ yī huī jiāng hǎi qù,lè yóu yuán shàng wàng zhāo líng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-57','赤壁',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["折戟沉沙铁未销，自将磨洗认前朝。", "东风不与周郎便，铜雀春深锁二乔。"]'::jsonb,'["zhé jǐ chén shā tiě wèi xiāo,zì jiāng mó xǐ rèn qián cháo.", "dōng fēng bù yǔ zhōu láng biàn,tóng què chūn shēn suǒ èr qiáo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-58','泊秦淮',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["烟笼寒水月笼沙，夜泊秦淮近酒家。", "商女不知亡国恨，隔江犹唱后庭花。"]'::jsonb,'["yān lóng hán shuǐ yuè lóng shā,yè pō qín huái jìn jiǔ jiā.", "shāng nǚ bù zhī wáng guó hèn,gé jiāng yóu chàng hòu tíng huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-59','征人怨',NULL,'柳中庸',NULL,'唐','唐诗',FALSE,'["岁岁金河复玉关，朝朝马策与刀环。", "三春白雪归青冢，万里黄河绕黑山。"]'::jsonb,'["suì suì jīn hé fù yù guān,cháo cháo mǎ cè yǔ dāo huán.", "sān chūn bái xuě guī qīng zhǒng,wàn lǐ huáng hé rào hēi shān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-60','金陵图',NULL,'韦庄',NULL,'唐','唐诗',FALSE,'["谁谓伤心画不成，画人心逐世人情。", "君看六幅南朝事，老木寒云满故城。"]'::jsonb,'["shuí wèi shāng xīn huà bù chéng,huà rén xīn zhú shì rén qíng.", "jūn kàn liù fú nán cháo shì,lǎo mù hán yún mǎn gù chéng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-61','滁州西涧',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["独怜幽草涧边生，上有黄鹂深树鸣。", "春潮带雨晚来急，野渡无人舟自横。"]'::jsonb,'["dú lián yōu cǎo jiàn biān shēng,shàng yǒu huáng lí shēn shù míng.", "chūn cháo dài yǔ wǎn lái jí,yě dù wú rén zhōu zì héng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-62','桃花溪',NULL,'张旭',NULL,'唐','唐诗',FALSE,'["隐隐飞桥隔野烟，石矶西畔问渔船。", "桃花尽日随流水，洞在清溪何处边。"]'::jsonb,'["yǐn yǐn fēi qiáo gé yě yān,shí jī xī pàn wèn yú chuán.", "táo huā jǐn rì suí liú shuǐ,dòng zài qīng xī hé chù biān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-63','寄人',NULL,'张泌',NULL,'唐','唐诗',FALSE,'["别梦依依到谢家，小廊回合曲阑斜。", "多情只有春庭月，犹为离人照落花。"]'::jsonb,'["bié mèng yī yī dào xiè jiā,xiǎo láng huí hé qū lán xié.", "duō qíng zhǐ yǒu chūn tíng yuè,yóu wèi lí rén zhào luò huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-64','题金陵渡',NULL,'张祜',NULL,'唐','唐诗',FALSE,'["金陵津渡小山楼，一宿行人自可愁。", "潮落夜江斜月里，两三星火是瓜州。"]'::jsonb,'["jīn líng jīn dù xiǎo shān lóu,yī xiǔ xíng rén zì kě chóu.", "cháo luò yè jiāng xié yuè lǐ,liǎng sān xīng huǒ shì guā zhōu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-65','赠内人',NULL,'张祜',NULL,'唐','唐诗',FALSE,'["禁门宫树月痕过，媚眼惟看宿鹭窠。", "斜拔玉钗灯影畔，剔开红焰救飞蛾。"]'::jsonb,'["jìn mén gōng shù yuè hén guò,mèi yǎn wéi kàn sù lù kē.", "xié bá yù chāi dēng yǐng pàn,tī kāi hóng yàn jiù fēi é."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-66','集灵台·其一',NULL,'张祜',NULL,'唐','唐诗',FALSE,'["日光斜照集灵台，红树花迎晓露开。", "昨夜上皇新授箓，太真含笑入帘来。"]'::jsonb,'["rì guāng xié zhào jí líng tái,hóng shù huā yíng xiǎo lù kāi.", "zuó yè shàng huáng xīn shòu lù,tài zhēn hán xiào rù lián lái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-67','集灵台·其二',NULL,'张祜',NULL,'唐','唐诗',FALSE,'["虢国夫人承主恩，平明骑马入宫门。", "却嫌脂粉污颜色，淡扫蛾眉朝至尊。"]'::jsonb,'["guó guó fū rén chéng zhǔ ēn,píng míng qí mǎ rù gōng mén.", "què xián zhī fěn wū yán sè,dàn sǎo é méi cháo zhì zūn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-68','枫桥夜泊',NULL,'张继',NULL,'唐','唐诗',FALSE,'["月落乌啼霜满天，江枫渔火对愁眠。", "姑苏城外寒山寺，夜半钟声到客船。"]'::jsonb,'["yuè luò wū tí shuāng mǎn tiān,jiāng fēng yú huǒ duì chóu mián.", "gū sū chéng wài hán shān sì,yè bàn zhōng shēng dào kè chuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-69','陇西行',NULL,'陈陶',NULL,'唐','唐诗',FALSE,'["誓扫匈奴不顾身，五千貂锦丧胡尘。", "可怜无定河边骨，犹是春闺梦里人！"]'::jsonb,'["shì sǎo xiōng nú bù gù shēn,wǔ qiān diāo jǐn sàng hú chén.", "kě lián wú dìng hé biān gǔ,yóu shì chūn guī mèng lǐ rén!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-70','杂诗',NULL,'佚名',NULL,'唐','唐诗',FALSE,'["近寒食雨草萋萋，著麦苗风柳映堤。", "等是有家归未得，杜鹃休向耳边啼。"]'::jsonb,'["jìn hán shí yǔ cǎo qī qī,zhù mài miáo fēng liǔ yìng dī.", "děng shì yǒu jiā guī wèi dé,dù juān xiū xiàng ěr biān tí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-71','回乡偶书·其一',NULL,'贺知章',NULL,'唐','唐诗',FALSE,'["少小离家老大回，乡音无改鬓毛衰。", "儿童相见不相识，笑问客从何处来。"]'::jsonb,'["shào xiǎo lí jiā lǎo dà huí,xiāng yīn wú gǎi bìn máo shuāi.", "ér tóng xiāng jiàn bù xiāng shí,xiào wèn kè cóng hé chù lái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-72','瑶瑟怨',NULL,'温庭筠',NULL,'唐','唐诗',FALSE,'["冰簟银床梦不成，碧天如水夜云轻。", "雁声远过潇湘去，十二楼中月自明。"]'::jsonb,'["bīng diàn yín chuáng mèng bù chéng,bì tiān rú shuǐ yè yún qīng.", "yàn shēng yuǎn guò xiāo xiāng qù,shí èr lóu zhōng yuè zì míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-73','月夜',NULL,'刘方平',NULL,'唐','唐诗',FALSE,'["更深月色半人家，北斗阑干南斗斜。", "今夜偏知春气暖，虫声新透绿窗纱。"]'::jsonb,'["gēng shēn yuè sè bàn rén jiā,běi dǒu lán gān nán dòu xié.", "jīn yè piān zhī chūn qì nuǎn,chóng shēng xīn tòu lǜ chuāng shā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-74','春怨',NULL,'刘方平',NULL,'唐','唐诗',FALSE,'["纱窗日落渐黄昏，金屋无人见泪痕。", "寂寞空庭春欲晚，梨花满地不开门。"]'::jsonb,'["shā chuāng rì luò jiàn huáng hūn,jīn wū wú rén jiàn lèi hén.", "jì mò kōng tíng chūn yù wǎn,lí huā mǎn dì bù kāi mén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-75','乌衣巷',NULL,'刘禹锡',NULL,'唐','唐诗',FALSE,'["朱雀桥边野草花，乌衣巷口夕阳斜。", "旧时王谢堂前燕，飞入寻常百姓家。"]'::jsonb,'["zhū què qiáo biān yě cǎo huā,wū yī xiàng kǒu xī yáng xié.", "jiù shí wáng xiè táng qián yàn,fēi rù xún cháng bǎi xìng jiā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-76','春词',NULL,'刘禹锡',NULL,'唐','唐诗',FALSE,'["新妆宜面下朱楼，深锁春光一院愁。", "行到中庭数花朵，蜻蜓飞上玉搔头。"]'::jsonb,'["xīn zhuāng yí miàn xià zhū lóu,shēn suǒ chūn guāng yī yuàn chóu.", "xíng dào zhōng tíng shù huā duǒ,qīng tíng fēi shàng yù sāo tóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-77','马嵬坡',NULL,'郑畋',NULL,'唐','唐诗',FALSE,'["玄宗回马杨妃死，云雨虽亡日月新。", "终是圣明天子事，景阳宫井又何人。"]'::jsonb,'["xuán zōng huí mǎ yáng fēi sǐ,yún yǔ suī wáng rì yuè xīn.", "zhōng shì shèng míng tiān zi shì,jǐng yáng gōng jǐng yòu hé rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-78','寒食',NULL,'韩翃',NULL,'唐','唐诗',FALSE,'["春城无处不飞花，寒食东风御柳斜。", "日暮汉宫传蜡烛，轻烟散入五侯家。"]'::jsonb,'["chūn chéng wú chǔ bù fēi huā,hán shí dōng fēng yù liǔ xié.", "rì mù hàn gōng chuán là zhú,qīng yān sàn rù wǔ hóu jiā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-79','已凉',NULL,'韩偓',NULL,'唐','唐诗',FALSE,'["碧阑干外绣帘垂，猩血屏风画折枝。", "八尺龙须方锦褥，已凉天气未寒时。"]'::jsonb,'["bì lán gān wài xiù lián chuí,xīng xuè píng fēng huà zhé zhī.", "bā chǐ lóng xū fāng jǐn rù,yǐ liáng tiān qì wèi hán shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-80','宫词',NULL,'顾况',NULL,'唐','唐诗',FALSE,'["长乐宫连上苑春，玉楼金殿艳歌新。", "君门一入无由出，唯有宫莺得见人。"]'::jsonb,'["cháng lè gōng lián shàng yuàn chūn,yù lóu jīn diàn yàn gē xīn.", "jūn mén yī rù wú yóu chū,wéi yǒu gōng yīng dé jiàn rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言绝句'),
('base-81','送杜少府之任蜀州',NULL,'王勃',NULL,'唐','唐诗',FALSE,'["城阙辅三秦，风烟望五津。", "与君离别意，同是宦游人。", "海内存知己，天涯若比邻。", "无为在歧路，儿女共沾巾。"]'::jsonb,'["chéng què fǔ sān qín,fēng yān wàng wǔ jīn.", "yǔ jūn lí bié yì,tóng shì huàn yóu rén.", "hǎi nèi cún zhī jǐ,tiān yá ruò bǐ lín.", "wú wéi zài qí lù,ér nǚ gòng zhān jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-82','送梓州李使君',NULL,'王维',NULL,'唐','唐诗',FALSE,'["万壑树参天，千山响杜鹃。", "山中一夜雨，树杪百重泉。", "汉女输橦布，巴人讼芋田。", "文翁翻教授，不敢倚先贤。"]'::jsonb,'["wàn hè shù cān tiān,qiān shān xiǎng dù juān.", "shān zhōng yī yè yǔ,shù miǎo bǎi zhòng quán.", "hàn nǚ shū tóng bù,bā rén sòng yù tián.", "wén wēng fān jiào shòu,bù gǎn yǐ xiān xián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-83','汉江临眺',NULL,'王维',NULL,'唐','唐诗',FALSE,'["楚塞三湘接，荆门九派通。", "江流天地外，山色有无中。", "郡邑浮前浦，波澜动远空。", "襄阳好风日，留醉与山翁。"]'::jsonb,'["chǔ sāi sān xiāng jiē,jīng mén jiǔ pài tōng.", "jiāng liú tiān dì wài,shān sè yǒu wú zhōng.", "jùn yì fú qián pǔ,bō lán dòng yuǎn kōng.", "xiāng yáng hǎo fēng rì,liú zuì yǔ shān wēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-84','终南别业',NULL,'王维',NULL,'唐','唐诗',FALSE,'["中岁颇好道，晚家南山陲。", "兴来每独往，胜事空自知。", "行到水穷处，坐看云起时。", "偶然值林叟，谈笑无还期。"]'::jsonb,'["zhōng suì pǒ hǎo dào,wǎn jiā nán shān chuí.", "xīng lái měi dú wǎng,shèng shì kōng zì zhī.", "xíng dào shuǐ qióng chù,zuò kàn yún qǐ shí.", "ǒu rán zhí lín sǒu,tán xiào wú hái qī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-85','终南山',NULL,'王维',NULL,'唐','唐诗',FALSE,'["太乙近天都，连山接海隅。", "白云回望合，青霭入看无。", "分野中峰变，阴晴众壑殊。", "欲投人处宿，隔水问樵夫。"]'::jsonb,'["tài yǐ jìn tiān dōu,lián shān jiē hǎi yú.", "bái yún huí wàng hé,qīng ǎi rù kàn wú.", "fēn yě zhōng fēng biàn,yīn qíng zhòng hè shū.", "yù tóu rén chù sù,gé shuǐ wèn qiáo fū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-86','酬张少府',NULL,'王维',NULL,'唐','唐诗',FALSE,'["晚年唯好静，万事不关心。自顾无长策，空知返旧林。", "松风吹解带，山月照弹琴。君问穷通理，渔歌入浦深。"]'::jsonb,'["wǎn nián wéi hǎo jìng,wàn shì bù guān xīn.zì gù wú cháng cè,kōng zhī fǎn jiù lín.", "sōng fēng chuī jiě dài,shān yuè zhào tán qín.jūn wèn qióng tōng lǐ,yú gē rù pǔ shēn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-87','过香积寺',NULL,'王维',NULL,'唐','唐诗',FALSE,'["不知香积寺，数里入云峰。", "古木无人径，深山何处钟。", "泉声咽危石，日色冷青松。", "薄暮空潭曲，安禅制毒龙。"]'::jsonb,'["bù zhī xiāng jī sì,shù lǐ rù yún fēng.", "gǔ mù wú rén jìng,shēn shān hé chù zhōng.", "quán shēng yàn wēi shí,rì sè lěng qīng sōng.", "bó mù kōng tán qū,ān chán zhì dú lóng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-88','辋川闲居赠裴秀才迪',NULL,'王维',NULL,'唐','唐诗',FALSE,'["寒山转苍翠，秋水日潺湲。", "倚杖柴门外，临风听暮蝉。", "渡头余落日，墟里上孤烟。", "复值接舆醉，狂歌五柳前。"]'::jsonb,'["hán shān zhuǎn cāng cuì,qiū shuǐ rì chán yuán.", "yǐ zhàng chái mén wài,lín fēng tīng mù chán.", "dù tóu yú luò rì,xū lǐ shàng gū yān.", "fù zhí jiē yú zuì,kuáng gē wǔ liǔ qián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-89','山居秋暝',NULL,'王维',NULL,'唐','唐诗',FALSE,'["空山新雨后，天气晚来秋。", "明月松间照，清泉石上流。", "竹喧归浣女，莲动下渔舟。", "随意春芳歇，王孙自可留。"]'::jsonb,'["kōng shān xīn yǔ hòu,tiān qì wǎn lái qiū.", "míng yuè sōng jiān zhào,qīng quán shí shàng liú.", "zhú xuān guī huàn nǚ,lián dòng xià yú zhōu.", "suí yì chūn fāng xiē,wáng sūn zì kě liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-90','归嵩山作',NULL,'王维',NULL,'唐','唐诗',FALSE,'["清川带长薄，车马去闲闲。", "流水如有意，暮禽相与还。", "荒城临古渡，落日满秋山。", "迢递嵩高下，归来且闭关。"]'::jsonb,'["qīng chuān dài zhǎng báo,chē mǎ qù xián xián.", "liú shuǐ rú yǒu yì,mù qín xiāng yǔ hái.", "huāng chéng lín gǔ dù,luò rì mǎn qiū shān.", "tiáo dì sōng gāo xià,guī lái qiě bì guān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-91','次北固山下',NULL,'王湾',NULL,'唐','唐诗',FALSE,'["客路青山外，行舟绿水前。", "潮平两岸阔，风正一帆悬。", "海日生残夜，江春入旧年。", "乡书何处达？归雁洛阳边。"]'::jsonb,'["kè lù qīng shān wài,xíng zhōu lǜ shuǐ qián.", "cháo píng liǎng àn kuò,fēng zhèng yī fān xuán.", "hǎi rì shēng cán yè,jiāng chūn rù jiù nián.", "xiāng shū hé chù dá?guī yàn luò yáng biān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-92','云阳馆与韩绅宿别',NULL,'司空曙',NULL,'唐','唐诗',FALSE,'["故人江海别，几度隔山川。", "乍见翻疑梦，相悲各问年。", "孤灯寒照雨，深竹暗浮烟。", "更有明朝恨，离杯惜共传。"]'::jsonb,'["gù rén jiāng hǎi bié,jǐ dù gé shān chuān.", "zhà jiàn fān yí mèng,xiāng bēi gè wèn nián.", "gū dēng hán zhào yǔ,shēn zhú àn fú yān.", "gèng yǒu míng cháo hèn,lí bēi xī gòng chuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-93','喜外弟卢纶见宿',NULL,'司空曙',NULL,'唐','唐诗',FALSE,'["静夜四无邻，荒居旧业贫。", "雨中黄叶树，灯下白头人。", "以我独沉久，愧君相见频。", "平生自有分，况是蔡家亲。"]'::jsonb,'["jìng yè sì wú lín,huāng jū jiù yè pín.", "yǔ zhōng huáng yè shù,dēng xià bái tóu rén.", "yǐ wǒ dú chén jiǔ,kuì jūn xiāng jiàn pín.", "píng shēng zì yǒu fēn,kuàng shì cài jiā qīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-94','贼平后送人北归',NULL,'司空曙',NULL,'唐','唐诗',FALSE,'["世乱同南去，时清独北还。", "他乡生白发，旧国见青山。", "晓月过残垒，繁星宿故关。", "寒禽与衰草，处处伴愁颜。"]'::jsonb,'["shì luàn tóng nán qù,shí qīng dú běi hái.", "tā xiāng shēng bái fà,jiù guó jiàn qīng shān.", "xiǎo yuè guò cán lěi,fán xīng sù gù guān.", "hán qín yǔ shuāi cǎo,chù chù bàn chóu yán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-95','赋得古原草送别',NULL,'白居易',NULL,'唐','唐诗',FALSE,'["离离原上草，一岁一枯荣。", "野火烧不尽，春风吹又生。", "远芳侵古道，晴翠接荒城。", "又送王孙去，萋萋满别情。"]'::jsonb,'["lí lí yuán shàng cǎo,yī suì yī kū róng.", "yě huǒ shāo bù jìn,chūn fēng chuī yòu shēng.", "yuǎn fāng qīn gǔ dào,qíng cuì jiē huāng chéng.", "yòu sòng wáng sūn qù,qī qī mǎn bié qíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-96','题大庾岭北驿',NULL,'宋之问',NULL,'唐','唐诗',FALSE,'["阳月南飞雁，传闻至此回。", "我行殊未已，何日复归来。", "江静潮初落，林昏瘴不开。", "明朝望乡处，应见陇头梅。"]'::jsonb,'["yáng yuè nán fēi yàn,chuán wén zhì cǐ huí.", "wǒ xíng shū wèi yǐ,hé rì fù guī lái.", "jiāng jìng cháo chū luò,lín hūn zhàng bù kāi.", "míng cháo wàng xiāng chù,yīng jiàn lǒng tóu méi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-97','寄左省杜拾遗',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["联步趋丹陛，分曹限紫微。", "晓随天仗入，暮惹御香归。", "白发悲花落，青云羡鸟飞。", "圣朝无阙事，自觉谏书稀。"]'::jsonb,'["lián bù qū dān bì,fēn cáo xiàn zǐ wēi.", "xiǎo suí tiān zhàng rù,mù rě yù xiāng guī.", "bái fà bēi huā luò,qīng yún xiàn niǎo fēi.", "shèng cháo wú quē shì,zì jué jiàn shū xī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-98','听蜀僧浚弹琴',NULL,'李白',NULL,'唐','唐诗',FALSE,'["蜀僧抱绿绮，西下峨眉峰。", "为我一挥手，如听万壑松。", "客心洗流水，余响入霜钟。", "不觉碧山暮，秋云暗几重。"]'::jsonb,'["shǔ sēng bào lǜ qǐ,xī xià é méi fēng.", "wèi wǒ yī huī shǒu,rú tīng wàn hè sōng.", "kè xīn xǐ liú shuǐ,yú xiǎng rù shuāng zhōng.", "bù jué bì shān mù,qiū yún àn jǐ zhòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-99','夜泊牛渚怀古',NULL,'李白',NULL,'唐','唐诗',FALSE,'["牛渚西江夜，青天无片云。", "登舟望秋月，空忆谢将军。", "余亦能高咏，斯人不可闻。", "明朝挂帆席，枫叶落纷纷。(挂帆", "一作：去)"]'::jsonb,'["niú zhǔ xī jiāng yè,qīng tiān wú piàn yún.", "dēng zhōu wàng qiū yuè,kōng yì xiè jiāng jūn.", "yú yì néng gāo yǒng,sī rén bù kě wén.", "míng cháo guà fān xí,fēng yè luò fēn fēn.( guà fān", "yī zuò:qù )"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-100','赠孟浩然',NULL,'李白',NULL,'唐','唐诗',FALSE,'["吾爱孟夫子，风流天下闻。", "红颜弃轩冕，白首卧松云。", "醉月频中圣，迷花不事君。", "高山安可仰，徒此揖清芬。"]'::jsonb,'["wú ài mèng fū zǐ,fēng liú tiān xià wén.", "hóng yán qì xuān miǎn,bái shǒu wò sōng yún.", "zuì yuè pín zhōng shèng,mí huā bù shì jūn.", "gāo shān ān kě yǎng,tú cǐ yī qīng fēn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-101','渡荆门送别',NULL,'李白',NULL,'唐','唐诗',FALSE,'["渡远荆门外，来从楚国游。", "山随平野尽，江入大荒流。", "月下飞天镜，云生结海楼。", "仍怜故乡水，万里送行舟。"]'::jsonb,'["dù yuǎn jīng mén wài,lái cóng chǔ guó yóu.", "shān suí píng yě jǐn,jiāng rù dà huāng liú.", "yuè xià fēi tiān jìng,yún shēng jié hǎi lóu.", "réng lián gù xiāng shuǐ,wàn lǐ sòng xíng zhōu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-102','送友人',NULL,'李白',NULL,'唐','唐诗',FALSE,'["青山横北郭，白水绕东城。", "此地一为别，孤蓬万里征。", "浮云游子意，落日故人情。", "挥手自兹去，萧萧班马鸣。"]'::jsonb,'["qīng shān héng běi guō,bái shuǐ rào dōng chéng.", "cǐ dì yī wèi bié,gū péng wàn lǐ zhēng.", "fú yún yóu zi yì,luò rì gù rén qíng.", "huī shǒu zì zī qù,xiāo xiāo bān mǎ míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-103','喜见外弟又言别',NULL,'李益',NULL,'唐','唐诗',FALSE,'["十年离乱后，长大一相逢。", "问姓惊初见，称名忆旧容。", "别来沧海事，语罢暮天钟。", "明日巴陵道，秋山又几重。"]'::jsonb,'["shí nián lí luàn hòu,zhǎng dà yī xiāng féng.", "wèn xìng jīng chū jiàn,chēng míng yì jiù róng.", "bié lái cāng hǎi shì,yǔ bà mù tiān zhōng.", "míng rì bā líng dào,qiū shān yòu jǐ zhòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-104','凉思',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["客去波平槛，蝉休露满枝。永怀当此节，倚立自移时。", "北斗兼春远，南陵寓使迟。天涯占梦数，疑误有新知。"]'::jsonb,'["kè qù bō píng kǎn,chán xiū lù mǎn zhī.yǒng huái dāng cǐ jié,yǐ lì zì yí shí.", "běi dǒu jiān chūn yuǎn,nán líng yù shǐ chí.tiān yá zhān mèng shù,yí wù yǒu xīn zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-105','北青萝',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["残阳西入崦，茅屋访孤僧。落叶人何在，寒云路几层。", "独敲初夜磬，闲倚一枝藤。世界微尘里，吾宁爱与憎。"]'::jsonb,'["cán yáng xī rù yān,máo wū fǎng gū sēng.luò yè rén hé zài,hán yún lù jǐ céng.", "dú qiāo chū yè qìng,xián yǐ yī zhī téng.shì jiè wēi chén lǐ,wú níng ài yǔ zēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-106','蝉',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["本以高难饱，徒劳恨费声。", "五更疏欲断，一树碧无情。", "薄宦梗犹泛，故园芜已平。", "烦君最相警，我亦举家清。"]'::jsonb,'["běn yǐ gāo nán bǎo,tú láo hèn fèi shēng.", "wǔ gēng shū yù duàn,yī shù bì wú qíng.", "báo huàn gěng yóu fàn,gù yuán wú yǐ píng.", "fán jūn zuì xiāng jǐng,wǒ yì jǔ jiā qīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-107','风雨',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["凄凉宝剑篇，羁泊欲穷年。", "黄叶仍风雨，青楼自管弦。", "新知遭薄俗，旧好隔良缘。", "心断新丰酒，销愁斗几千。"]'::jsonb,'["qī liáng bǎo jiàn piān,jī pō yù qióng nián.", "huáng yè réng fēng yǔ,qīng lóu zì guǎn xián.", "xīn zhī zāo báo sú,jiù hǎo gé liáng yuán.", "xīn duàn xīn fēng jiǔ,xiāo chóu dòu jǐ qiān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-108','落花',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["高阁客竟去，小园花乱飞。参差连曲陌，迢递送斜晖。", "肠断未忍扫，眼穿仍欲归。芳心向春尽，所得是沾衣。"]'::jsonb,'["gāo gé kè jìng qù,xiǎo yuán huā luàn fēi.cēn cī lián qū mò,tiáo dì sòng xié huī.", "cháng duàn wèi rěn sǎo,yǎn chuān réng yù guī.fāng xīn xiàng chūn jǐn,suǒ de shì zhān yī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-109','登岳阳楼',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["昔闻洞庭水，今上岳阳楼。", "吴楚东南坼，乾坤日夜浮。", "亲朋无一字，老病有孤舟。", "戎马关山北，凭轩涕泗流。"]'::jsonb,'["xī wén dòng tíng shuǐ,jīn shàng yuè yáng lóu.", "wú chǔ dōng nán chè,qián kūn rì yè fú.", "qīn péng wú yī zì,lǎo bìng yǒu gū zhōu.", "róng mǎ guān shān běi,píng xuān tì sì liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-110','奉济驿重送严公四韵',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["远送从此别，青山空复情。几时杯重把，昨夜月同行。", "列郡讴歌惜，三朝出入荣。江村独归处，寂寞养残生。"]'::jsonb,'["yuǎn sòng cóng cǐ bié,qīng shān kōng fù qíng.jǐ shí bēi zhòng bǎ,zuó yè yuè tóng háng.", "liè jùn ōu gē xī,sān cháo chū rù róng.jiāng cūn dú guī chù,jì mò yǎng cán shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-111','别房太尉墓',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["他乡复行役，驻马别孤坟。", "近泪无干土，低空有断云。", "对棋陪谢傅，把剑觅徐君。", "唯见林花落，莺啼送客闻。"]'::jsonb,'["tā xiāng fù xíng yì,zhù mǎ bié gū fén.", "jìn lèi wú gān tǔ,dī kōng yǒu duàn yún.", "duì qí péi xiè fù,bǎ jiàn mì xú jūn.", "wéi jiàn lín huā luò,yīng tí sòng kè wén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-112','旅夜书怀',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["细草微风岸，危樯独夜舟。", "星垂平野阔，月涌大江流。", "名岂文章著，官应老病休。", "飘飘何所似，天地一沙鸥。"]'::jsonb,'["xì cǎo wēi fēng àn,wēi qiáng dú yè zhōu.", "xīng chuí píng yě kuò,yuè yǒng dà jiāng liú.", "míng qǐ wén zhāng zhù,guān yīng lǎo bìng xiū.", "piāo piāo hé suǒ shì,tiān dì yī shā ōu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-113','至德二载甫自京金光门',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["此道昔归顺，西郊胡正繁。", "至今残破胆，应有未招魂。", "近得归京邑，移官岂至尊。", "无才日衰老，驻马望千门。"]'::jsonb,'["cǐ dào xī guī shùn,xī jiāo hú zhèng fán.", "zhì jīn cán pò dǎn,yīng yǒu wèi zhāo hún.", "jìn dé guī jīng yì,yí guān qǐ zhì zūn.", "wú cái rì shuāi lǎo,zhù mǎ wàng qiān mén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-114','月夜忆舍弟',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["戍鼓断人行，边秋一雁声。", "露从今夜白，月是故乡明。", "有弟皆分散，无家问死生。", "寄书长不达，况乃未休兵。"]'::jsonb,'["shù gǔ duàn rén xíng,biān qiū yī yàn shēng.", "lù cóng jīn yè bái,yuè shì gù xiāng míng.", "yǒu dì jiē fēn sàn,wú jiā wèn sǐ shēng.", "jì shū zhǎng bù dá,kuàng nǎi wèi xiū bīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-115','天末怀李白',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["凉风起天末，君子意如何。", "鸿雁几时到，江湖秋水多。", "文章憎命达，魑魅喜人过。", "应共冤魂语，投诗赠汨罗。"]'::jsonb,'["liáng fēng qǐ tiān mò,jūn zǐ yì rú hé.", "hóng yàn jǐ shí dào,jiāng hú qiū shuǐ duō.", "wén zhāng zēng mìng dá,chī mèi xǐ rén guò.", "yīng gòng yuān hún yǔ,tóu shī zèng mì luó."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-116','月夜',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["今夜鄜州月，闺中只独看。遥怜小儿女，未解忆长安。", "香雾云鬟湿，清辉玉臂寒。何时倚虚幌，双照泪痕干。"]'::jsonb,'["jīn yè fū zhōu yuè,guī zhōng zhǐ dú kàn.yáo lián xiǎo ér nǚ,wèi jiě yì cháng ān.", "xiāng wù yún huán shī,qīng huī yù bì hán.hé shí yǐ xū huǎng,shuāng zhào lèi hén gàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-117','春望',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["国破山河在，城春草木深。", "感时花溅泪，恨别鸟惊心。", "烽火连三月，家书抵万金。", "白头搔更短，浑欲不胜簪。"]'::jsonb,'["guó pò shān hé zài,chéng chūn cǎo mù shēn.", "gǎn shí huā jiàn lèi,hèn bié niǎo jīng xīn.", "fēng huǒ lián sān yuè,jiā shū dǐ wàn jīn.", "bái tóu sāo gèng duǎn,hún yù bù shèng zān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-118','春宿左省',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["花隐掖垣暮，啾啾栖鸟过。", "星临万户动，月傍九霄多。", "不寝听金钥，因风想玉珂。", "明朝有封事，数问夜如何。"]'::jsonb,'["huā yǐn yē yuán mù,jiū jiū qī niǎo guò.", "xīng lín wàn hù dòng,yuè bàng jiǔ xiāo duō.", "bù qǐn tīng jīn yào,yīn fēng xiǎng yù kē.", "míng cháo yǒu fēng shì,shù wèn yè rú hé."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-119','旅宿',NULL,'杜牧',NULL,'唐','唐诗',FALSE,'["旅馆无良伴，凝情自悄然。", "寒灯思旧事，断雁警愁眠。", "远梦归侵晓，家书到隔年。", "沧江好烟月，门系钓鱼船。"]'::jsonb,'["lǚ guǎn wú liáng bàn,níng qíng zì qiǎo rán.", "hán dēng sī jiù shì,duàn yàn jǐng chóu mián.", "yuǎn mèng guī qīn xiǎo,jiā shū dào gé nián.", "cāng jiāng hǎo yān yuè,mén xì diào yú chuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-120','春宫怨',NULL,'杜荀鹤',NULL,'唐','唐诗',FALSE,'["早被婵娟误，欲妆临镜慵。承恩不在貌，教妾若为容。", "风暖鸟声碎，日高花影重。年年越溪女，相忆采芙蓉。"]'::jsonb,'["zǎo bèi chán juān wù,yù zhuāng lín jìng yōng.chéng ēn bù zài mào,jiào qiè ruò wèi róng.", "fēng nuǎn niǎo shēng suì,rì gāo huā yǐng zhòng.nián nián yuè xī nǚ,xiāng yì cǎi fú róng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-121','和晋陵陆丞早春游望',NULL,'杜审言',NULL,'唐','唐诗',FALSE,'["独有宦游人，偏惊物候新。", "云霞出海曙，梅柳渡江春。", "淑气催黄鸟，晴光转绿苹。", "忽闻歌古调，归思欲沾巾。"]'::jsonb,'["dú yǒu huàn yóu rén,piān jīng wù hòu xīn.", "yún xiá chū hǎi shǔ,méi liǔ dù jiāng chūn.", "shū qì cuī huáng niǎo,qíng guāng zhuǎn lǜ píng.", "hū wén gē gǔ diào,guī sī yù zhān jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-122','杂诗三首·其三',NULL,'沈佺期',NULL,'唐','唐诗',FALSE,'["闻道黄龙戍，频年不解兵。", "可怜闺里月，长在汉家营。", "少妇今春意，良人昨夜情。", "谁能将旗鼓，一为取龙城。"]'::jsonb,'["wén dào huáng lóng shù,pín nián bù jiě bīng.", "kě lián guī lǐ yuè,zhǎng zài hàn jiā yíng.", "shào fù jīn chūn yì,liáng rén zuó yè qíng.", "shuí néng jiāng qí gǔ,yī wèi qǔ lóng chéng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-123','宿桐庐江寄广陵旧游',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["山暝闻猿愁，沧江急夜流。", "风鸣两岸叶，月照一孤舟。", "建德非吾土，维扬忆旧游。", "还将两行泪，遥寄海西头。"]'::jsonb,'["shān míng wén yuán chóu,cāng jiāng jí yè liú.", "fēng míng liǎng àn yè,yuè zhào yī gū zhōu.", "jiàn dé fēi wú tǔ,wéi yáng yì jiù yóu.", "hái jiāng liǎng xíng lèi,yáo jì hǎi xī tóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-124','留别王维',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["寂寂竟何待，朝朝空自归。欲寻芳草去，惜与故人违。", "当路谁相假，知音世所稀。只应守寂寞，还掩故园扉。"]'::jsonb,'["jì jì jìng hé dài,cháo cháo kōng zì guī.yù xún fāng cǎo qù,xī yǔ gù rén wéi.", "dāng lù shuí xiāng jiǎ,zhī yīn shì suǒ xī.zhǐ yīng shǒu jì mò,hái yǎn gù yuán fēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-125','早寒有怀',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["木落雁南度，北风江上寒。", "我家襄水曲，遥隔楚云端。", "乡泪客中尽，孤帆天际看。", "迷津欲有问，平海夕漫漫。"]'::jsonb,'["mù luò yàn nán dù,běi fēng jiāng shàng hán.", "wǒ jiā xiāng shuǐ qū,yáo gé chǔ yún duān.", "xiāng lèi kè zhōng jǐn,gū fān tiān jì kàn.", "mí jīn yù yǒu wèn,píng hǎi xī màn màn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-126','岁暮归南山',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["北阙休上书，南山归敝庐。不才明主弃，多病故人疏。", "白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。"]'::jsonb,'["běi quē xiū shàng shū,nán shān guī bì lú.bù cái míng zhǔ qì,duō bìng gù rén shū.", "bái fà cuī nián lǎo,qīng yáng bī suì chú.yǒng huái chóu bú mèi,sōng yuè yè chuāng xū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-127','过故人庄',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["故人具鸡黍，邀我至田家。", "绿树村边合，青山郭外斜。", "开轩面场圃，把酒话桑麻。", "待到重阳日，还来就菊花。"]'::jsonb,'["gù rén jù jī shǔ,yāo wǒ zhì tián jiā.", "lǜ shù cūn biān hé,qīng shān guō wài xié.", "kāi xuān miàn chǎng pǔ,bǎ jiǔ huà sāng má.", "dài dào chóng yáng rì,hái lái jiù jú huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-128','秦中寄远上人',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["一丘常欲卧，三径苦无资。", "北土非吾愿，东林怀我师。", "黄金燃桂尽，壮志逐年衰。", "日夕凉风至，闻蝉但益悲。"]'::jsonb,'["yī qiū cháng yù wò,sān jìng kǔ wú zī.", "běi tǔ fēi wú yuàn,dōng lín huái wǒ shī.", "huáng jīn rán guì jǐn,zhuàng zhì zhú nián shuāi.", "rì xī liáng fēng zhì,wén chán dàn yì bēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-129','望洞庭湖赠张丞相',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["八月湖水平，涵虚混太清。", "气蒸云梦泽，波撼岳阳城。", "欲济无舟楫，端居耻圣明。", "坐观垂钓者，徒有羡鱼情。"]'::jsonb,'["bā yuè hú shuǐ píng,hán xū hùn tài qīng.", "qì zhēng yún mèng zé,bō hàn yuè yáng chéng.", "yù jì wú zhōu jí,duān jū chǐ shèng míng.", "zuò guān chuí diào zhě,tú yǒu xiàn yú qíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-130','与诸子登岘山',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["人事有代谢，往来成古今。", "江山留胜迹，我辈复登临。", "水落鱼梁浅，天寒梦泽深。", "羊公碑尚在，读罢泪沾襟。"]'::jsonb,'["rén shì yǒu dài xiè,wǎng lái chéng gǔ jīn.", "jiāng shān liú shèng jì,wǒ bèi fù dēng lín.", "shuǐ luò yú liáng qiǎn,tiān hán mèng zé shēn.", "yáng gōng bēi shàng zài,dú bà lèi zhān jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-131','宴梅道士山房',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["林卧愁春尽，开轩览物华。", "忽逢青鸟使，邀入赤松家。", "金灶初开火，仙桃正发花。", "童颜若可驻，何惜醉流霞。"]'::jsonb,'["lín wò chóu chūn jǐn,kāi xuān lǎn wù huá.", "hū féng qīng niǎo shǐ,yāo rù chì sōng jiā.", "jīn zào chū kāi huǒ,xiān táo zhèng fā huā.", "tóng yán ruò kě zhù,hé xī zuì liú xiá."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-132','章台夜思',NULL,'韦庄',NULL,'唐','唐诗',FALSE,'["清瑟怨遥夜，绕弦风雨哀。孤灯闻楚角，残月下章台。", "芳草已云暮，故人殊未来。乡书不可寄，秋雁又南回。"]'::jsonb,'["qīng sè yuàn yáo yè,rào xián fēng yǔ āi.gū dēng wén chǔ jiǎo,cán yuè xià zhāng tái.", "fāng cǎo yǐ yún mù,gù rén shū wèi lái.xiāng shū bù kě jì,qiū yàn yòu nán huí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-133','淮上喜会梁州故人',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["江汉曾为客，相逢每醉还。", "浮云一别后，流水十年间。", "欢笑情如旧，萧疏鬓已斑。", "何因不归去？淮上有秋山。"]'::jsonb,'["jiāng hàn céng wèi kè,xiāng féng měi zuì hái.", "fú yún yī bié hòu,liú shuǐ shí nián jiān.", "huān xiào qíng rú jiù,xiāo shū bìn yǐ bān.", "hé yīn bù guī qù?huái shàng yǒu qiū shān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-134','赋得暮雨送李曹',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["楚江微雨里，建业暮钟时。", "漠漠帆来重，冥冥鸟去迟。", "海门深不见，浦树远含滋。", "相送情无限，沾襟比散丝。"]'::jsonb,'["chǔ jiāng wēi yǔ lǐ,jiàn yè mù zhōng shí.", "mò mò fān lái zhòng,míng míng niǎo qù chí.", "hǎi mén shēn bú jiàn,pǔ shù yuǎn hán zī.", "xiāng sòng qíng wú xiàn,zhān jīn bǐ sàn sī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-135','经邹鲁祭孔子而叹之',NULL,'李隆基',NULL,'唐','唐诗',FALSE,'["夫子何为者，栖栖一代中。", "地犹鄹氏邑，宅即鲁王宫。", "叹凤嗟身否，伤麟怨道穷。", "今看两楹奠，当与梦时同。"]'::jsonb,'["fū zǐ hé wèi zhě,xī xī yí dài zhōng.", "dì yóu zōu shì yì,zhái jí lǔ wáng gōng.", "tàn fèng jiē shēn fǒu,shāng lín yuàn dào qióng.", "jīn kàn liǎng yíng diàn,dāng yǔ mèng shí tóng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-136','灞上秋居',NULL,'马戴',NULL,'唐','唐诗',FALSE,'["灞原风雨定，晚见雁行频。", "落叶他乡树，寒灯独夜人。", "空园白露滴，孤壁野僧邻。", "寄卧郊扉久，何年致此身。"]'::jsonb,'["bà yuán fēng yǔ dìng,wǎn jiàn yàn háng pín.", "luò yè tā xiāng shù,hán dēng dú yè rén.", "kōng yuán bái lù dī,gū bì yě sēng lín.", "jì wò jiāo fēi jiǔ,hé nián zhì cǐ shēn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-137','楚江怀古三首·其一',NULL,'马戴',NULL,'唐','唐诗',FALSE,'["露气寒光集，微阳下楚丘。猿啼洞庭树，人在木兰舟。", "广泽生明月，苍山夹乱流。云中君不见，竟夕自悲秋。"]'::jsonb,'["lù qì hán guāng jí,wēi yáng xià chǔ qiū.yuán tí dòng tíng shù,rén zài mù lán zhōu.", "guǎng zé shēng míng yuè,cāng shān jiā luàn liú.yún zhōng jūn bú jiàn,jìng xī zì bēi qiū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-138','除夜有怀',NULL,'崔涂',NULL,'唐','唐诗',FALSE,'["迢递三巴路，羁危万里身。", "乱山残雪夜，孤烛异乡人。", "渐与骨肉远，转于僮仆亲。", "那堪正飘泊，明日岁华新。"]'::jsonb,'["tiáo dì sān bā lù,jī wēi wàn lǐ shēn.", "luàn shān cán xuě yè,gū zhú yì xiāng rén.", "jiàn yǔ gǔ ròu yuǎn,zhuǎn yú tóng pú qīn.", "nà kān zhèng piāo bó,míng rì suì huá xīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-139','孤雁',NULL,'崔涂',NULL,'唐','唐诗',FALSE,'["几行归塞尽，念尔独何之。", "暮雨相呼失，寒塘欲下迟。", "渚云低暗度，关月冷相随。", "未必逢矰缴，孤飞自可疑。"]'::jsonb,'["jǐ xíng guī sāi jǐn,niàn ěr dú hé zhī.", "mù yǔ xiāng hū shī,hán táng yù xià chí.", "zhǔ yún dī àn dù,guān yuè lěng xiāng suí.", "wèi bì féng zēng jiǎo,gū fēi zì kě yí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-140','题破山寺后禅院',NULL,'常建',NULL,'唐','唐诗',FALSE,'["清晨入古寺，初日照高林。", "曲径通幽处，禅房花木深。", "山光悦鸟性，潭影空人心。", "万籁此俱寂，唯闻钟磬音。"]'::jsonb,'["qīng chén rù gǔ sì,chū rì zhào gāo lín.", "qū jìng tōng yōu chù,chán fáng huā mù shēn.", "shān guāng yuè niǎo xìng,tán yǐng kōng rén xīn.", "wàn lài cǐ jù jì,wéi wén zhōng qìng yīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-141','望月怀远',NULL,'张九龄',NULL,'唐','唐诗',FALSE,'["海上生明月，天涯共此时。", "情人怨遥夜，竟夕起相思。", "灭烛怜光满，披衣觉露滋。", "不堪盈手赠，还寝梦佳期。"]'::jsonb,'["hǎi shàng shēng míng yuè,tiān yá gòng cǐ shí.", "qíng rén yuàn yáo yè,jìng xī qǐ xiāng sī.", "miè zhú lián guāng mǎn,pī yī jué lù zī.", "bù kān yíng shǒu zèng,hái qǐn mèng jiā qī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-142','书边事',NULL,'张乔',NULL,'唐','唐诗',FALSE,'["调角断清秋，征人倚戍楼。春风对青冢，白日落梁州。", "大汉无兵阻，穷边有客游。蕃情似此水，长愿向南流。"]'::jsonb,'["diào jiǎo duàn qīng qiū,zhēng rén yǐ shù lóu.chūn fēng duì qīng zhǒng,bái rì luò liáng zhōu.", "dà hàn wú bīng zǔ,qióng biān yǒu kè yóu.fān qíng shì cǐ shuǐ,zhǎng yuàn xiàng nán liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-143','没蕃故人',NULL,'张籍',NULL,'唐','唐诗',FALSE,'["前年伐月支，城下没全师。", "蕃汉断消息，死生长别离。", "无人收废帐，归马识残旗。", "欲祭疑君在，天涯哭此时。"]'::jsonb,'["qián nián fá yuè zhī,chéng xià méi quán shī.", "fān hàn duàn xiāo xī,sǐ shēng zhǎng bié lí.", "wú rén shōu fèi zhàng,guī mǎ shí cán qí.", "yù jì yí jūn zài,tiān yá kū cǐ shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-144','秋日赴阙题潼关驿楼',NULL,'许浑',NULL,'唐','唐诗',FALSE,'["红叶晚萧萧，长亭酒一瓢。", "残云归太华，疏雨过中条。", "树色随山迥，河声入海遥。", "帝乡明日到，犹自梦渔樵。"]'::jsonb,'["hóng yè wǎn xiāo xiāo,cháng tíng jiǔ yī piáo.", "cán yún guī tài huá,shū yǔ guò zhōng tiáo.", "shù sè suí shān jiǒng,hé shēng rù hǎi yáo.", "dì xiāng míng rì dào,yóu zì mèng yú qiáo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-145','早秋',NULL,'许浑',NULL,'唐','唐诗',FALSE,'["遥夜泛清瑟，西风生翠萝。", "残萤委玉露，早雁拂金河。", "高树晓还密，远山晴更多。", "淮南一叶下，自觉洞庭波。"]'::jsonb,'["yáo yè fàn qīng sè,xī fēng shēng cuì luó.", "cán yíng wěi yù lù,zǎo yàn fú jīn hé.", "gāo shù xiǎo hái mì,yuǎn shān qíng gèng duō.", "huái nán yī yè xià,zì jué dòng tíng bō."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-146','送人东游',NULL,'温庭筠',NULL,'唐','唐诗',FALSE,'["荒戍落黄叶，浩然离故关。", "高风汉阳渡，初日郢门山。", "江上几人在，天涯孤棹还。", "何当重相见，樽酒慰离颜。"]'::jsonb,'["huāng shù luò huáng yè,hào rán lí gù guān.", "gāo fēng hàn yáng dù,chū rì yǐng mén shān.", "jiāng shàng jǐ rén zài,tiān yá gū zhào hái.", "hé dāng zhòng xiāng jiàn,zūn jiǔ wèi lí yán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-147','寻陆鸿渐不遇',NULL,'皎然',NULL,'唐','唐诗',FALSE,'["移家虽带郭，野径入桑麻。近种篱边菊，秋来未著花。", "扣门无犬吠，欲去问西家。报道山中去，归时每日斜。"]'::jsonb,'["yí jiā suī dài guō,yě jìng rù sāng má.jìn zhǒng lí biān jú,qiū lái wèi zhù huā.", "kòu mén wú quǎn fèi,yù qù wèn xī jiā.bào dào shān zhōng qù,guī shí měi rì xié."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-148','寻南溪常道士',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["一路经行处，莓苔见履痕。", "白云依静渚，春草闭闲门。", "过雨看松色，随山到水源。", "溪花与禅意，相对亦忘言。"]'::jsonb,'["yī lù jīng xíng chù,méi tái jiàn lǚ hén.", "bái yún yī jìng zhǔ,chūn cǎo bì xián mén.", "guò yǔ kàn sōng sè,suí shān dào shuǐ yuán.", "xī huā yǔ chán yì,xiāng duì yì wàng yán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-149','新年作',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["乡心新岁切，天畔独潸然。", "老至居人下，春归在客先。", "岭猿同旦暮，江柳共风烟。", "已似长沙傅，从今又几年。"]'::jsonb,'["xiāng xīn xīn suì qiè,tiān pàn dú shān rán.", "lǎo zhì jū rén xià,chūn guī zài kè xiān.", "lǐng yuán tóng dàn mù,jiāng liǔ gòng fēng yān.", "yǐ shì cháng shā fù,cóng jīn yòu jǐ nián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-150','秋日登吴公台上寺远眺',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["古台摇落后，秋日望乡心。", "野寺来人少，云峰隔水深。", "夕阳依旧垒，寒磬满空林。", "惆怅南朝事，长江独至今。"]'::jsonb,'["gǔ tái yáo luò hòu,qiū rì wàng xiāng xīn.", "yě sì lái rén shǎo,yún fēng gé shuǐ shēn.", "xī yáng yī jiù lěi,hán qìng mǎn kōng lín.", "chóu chàng nán cháo shì,cháng jiāng dú zhì jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-151','送李中丞归汉阳别业',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["流落征南将，曾驱十万师。", "罢归无旧业，老去恋明时。", "独立三边静，轻生一剑知。", "茫茫江汉上，日暮欲何之。"]'::jsonb,'["liú luò zhēng nán jiāng,céng qū shí wàn shī.", "bà guī wú jiù yè,lǎo qù liàn míng shí.", "dú lì sān biān jìng,qīng shēng yī jiàn zhī.", "máng máng jiāng hàn shàng,rì mù yù hé zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-152','饯别王十一南游',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["望君烟水阔，挥手泪沾巾。", "飞鸟没何处，青山空向人。", "长江一帆远，落日五湖春。", "谁见汀洲上，相思愁白苹。"]'::jsonb,'["wàng jūn yān shuǐ kuò,huī shǒu lèi zhān jīn.", "fēi niǎo méi hé chù,qīng shān kōng xiàng rén.", "cháng jiāng yī fān yuǎn,luò rì wǔ hú chūn.", "shuí jiàn tīng zhōu shàng,xiāng sī chóu bái píng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-153','蜀先主庙',NULL,'刘禹锡',NULL,'唐','唐诗',FALSE,'["天地英雄气，千秋尚凛然。势分三足鼎，业复五铢钱。", "得相能开国，生儿不象贤。凄凉蜀故妓，来舞魏宫前。"]'::jsonb,'["tiān dì yīng xióng qì,qiān qiū shàng lǐn rán.shì fēn sān zú dǐng,yè fù wǔ zhū qián.", "dé xiāng néng kāi guó,shēng ér bù xiàng xián.qī liáng shǔ gù jì,lái wǔ wèi gōng qián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-154','阙题',NULL,'刘昚虚',NULL,'唐','唐诗',FALSE,'["道由白云尽，春与青溪长。", "时有落花至，远随流水香。", "闲门向山路，深柳读书堂。", "幽映每白日，清辉照衣裳。"]'::jsonb,'["dào yóu bái yún jǐn,chūn yǔ qīng xī zhǎng.", "shí yǒu luò huā zhì,yuǎn suí liú shuǐ xiāng.", "xián mén xiàng shān lù,shēn liǔ dú shū táng.", "yōu yìng měi bái rì,qīng huī zhào yī shang."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-155','送李端',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["故关衰草遍，离别自堪悲。", "路出寒云外，人归暮雪时。", "少孤为客早，多难识君迟。", "掩泪空相向，风尘何处期。"]'::jsonb,'["gù guān shuāi cǎo biàn,lí bié zì kān bēi.", "lù chū hán yún wài,rén guī mù xuě shí.", "shǎo gū wèi kè zǎo,duō nán shí jūn chí.", "yǎn lèi kōng xiāng xiàng,fēng chén hé chù qī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-156','送僧归日本',NULL,'钱起',NULL,'唐','唐诗',FALSE,'["上国随缘住，来途若梦行。", "浮天沧海远，去世法舟轻。", "水月通禅寂，鱼龙听梵声。", "惟怜一灯影，万里眼中明。"]'::jsonb,'["shàng guó suí yuán zhù,lái tú ruò mèng xíng.", "fú tiān cāng hǎi yuǎn,qù shì fǎ zhōu qīng.", "shuǐ yuè tōng chán jì,yú lóng tīng fàn shēng.", "wéi lián yī dēng yǐng,wàn lǐ yǎn zhōng míng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-157','谷口书斋寄杨补阙',NULL,'钱起',NULL,'唐','唐诗',FALSE,'["泉壑带茅茨，云霞生薜帷。", "竹怜新雨后，山爱夕阳时。", "闲鹭栖常早，秋花落更迟。", "家僮扫萝径，昨与故人期。"]'::jsonb,'["quán hè dài máo cí,yún xiá shēng bì wéi.", "zhú lián xīn yǔ hòu,shān ài xī yáng shí.", "xián lù qī cháng zǎo,qiū huā luò gèng chí.", "jiā tóng sǎo luó jìng,zuó yǔ gù rén qī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-158','在狱咏蝉',NULL,'骆宾王',NULL,'唐','唐诗',FALSE,'["西陆蝉声唱，南冠客思深。", "不堪玄鬓影，来对白头吟。", "露重飞难进，风多响易沉。", "无人信高洁，谁为表予心？"]'::jsonb,'["xī lù chán shēng chàng,nán guān kè sī shēn.", "bù kān xuán bìn yǐng,lái duì bái tóu yín.", "lù zhòng fēi nán jìn,fēng duō xiǎng yì chén.", "wú rén xìn gāo jié,shuí wèi biǎo yǔ xīn?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-159','江乡故人偶集客舍',NULL,'戴叔伦',NULL,'唐','唐诗',FALSE,'["天秋月又满，城阙夜千重。", "还作江南会，翻疑梦里逢。", "风枝惊暗鹊，露草覆寒蛩。", "羁旅长堪醉，相留畏晓钟。"]'::jsonb,'["tiān qiū yuè yòu mǎn,chéng què yè qiān zhòng.", "hái zuò jiāng nán huì,fān yí mèng lǐ féng.", "fēng zhī jīng àn què,lù cǎo fù hán qióng.", "jī lǚ zhǎng kān zuì,xiāng liú wèi xiǎo zhōng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-160','酬程延秋夜即事见赠',NULL,'韩翃',NULL,'唐','唐诗',FALSE,'["长簟迎风早，空城澹月华。", "星河秋一雁，砧杵夜千家。", "节候看应晚，心期卧亦赊。", "向来吟秀句，不觉已鸣鸦。"]'::jsonb,'["zhǎng diàn yíng fēng zǎo,kōng chéng dàn yuè huá.", "xīng hé qiū yī yàn,zhēn chǔ yè qiān jiā.", "jié hòu kàn yīng wǎn,xīn qī wò yì shē.", "xiàng lái yín xiù jù,bù jué yǐ míng yā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言律诗'),
('base-161','遣悲怀三首·其一',NULL,'元稹',NULL,'唐','唐诗',FALSE,'["谢公最小偏怜女，自嫁黔娄百事乖。", "顾我无衣搜荩箧，泥他沽酒拔金钗。", "野蔬充膳甘长藿，落叶添薪仰古槐。", "今日俸钱过十万，与君营奠复营斋。"]'::jsonb,'["xiè gōng zuì xiǎo piān lián nǚ,zì jià qián lóu bǎi shì guāi.", "gù wǒ wú yī sōu jìn qiè,ní tā gū jiǔ bá jīn chāi.", "yě shū chōng shàn gān zhǎng huò,luò yè tiān xīn yǎng gǔ huái.", "jīn rì fèng qián guò shí wàn,yǔ jūn yíng diàn fù yíng zhāi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-162','遣悲怀三首·其二',NULL,'元稹',NULL,'唐','唐诗',FALSE,'["昔日戏言身后事，今朝都到眼前来。", "衣裳已施行看尽，针线犹存未忍开。", "尚想旧情怜婢仆，也曾因梦送钱财。", "诚知此恨人人有，贫贱夫妻百事哀。"]'::jsonb,'["xī rì xì yán shēn hòu shì,jīn zhāo dōu dào yǎn qián lái.", "yī shang yǐ shī xíng kàn jǐn,zhēn xiàn yóu cún wèi rěn kāi.", "shàng xiǎng jiù qíng lián bì pū,yě céng yīn mèng sòng qián cái.", "chéng zhī cǐ hèn rén rén yǒu,pín jiàn fū qī bǎi shì āi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-163','遣悲怀三首·其三',NULL,'元稹',NULL,'唐','唐诗',FALSE,'["闲坐悲君亦自悲，百年都是几多时。", "邓攸无子寻知命，潘岳悼亡犹费词。", "同穴窅冥何所望，他生缘会更难期。", "惟将终夜常开眼，报答平生未展眉。"]'::jsonb,'["xián zuò bēi jūn yì zì bēi,bǎi nián dōu shì jǐ duō shí.", "dèng yōu wú zi xún zhī mìng,pān yuè dào wáng yóu fèi cí.", "tóng xué yǎo míng hé suǒ wàng,tā shēng yuán huì gèng nán qī.", "wéi jiāng zhōng yè cháng kāi yǎn,bào dá píng shēng wèi zhǎn méi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-164','赠郭给事',NULL,'王维',NULL,'唐','唐诗',FALSE,'["洞门高阁霭余辉，桃李阴阴柳絮飞。", "禁里疏钟官舍晚，省中啼鸟吏人稀。", "晨摇玉佩趋金殿，夕奉天书拜琐闱。", "强欲从君无那老，将因卧病解朝衣。"]'::jsonb,'["dòng mén gāo gé ǎi yú huī,táo lǐ yīn yīn liǔ xù fēi.", "jìn lǐ shū zhōng guān shě wǎn,shěng zhōng tí niǎo lì rén xī.", "chén yáo yù pèi qū jīn diàn,xī fèng tiān shū bài suǒ wéi.", "qiáng yù cóng jūn wú nà lǎo,jiāng yīn wò bìng jiě cháo yī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-165','和贾至舍人早朝大明宫',NULL,'王维',NULL,'唐','唐诗',FALSE,'["绛帻鸡人送晓筹，尚衣方进翠云裘。", "九天阊阖开宫殿，万国衣冠拜冕旒。", "日色才临仙掌动，香烟欲傍衮龙浮。", "朝罢须裁五色诏，佩声归向凤池头。"]'::jsonb,'["jiàng zé jī rén sòng xiǎo chóu,shàng yī fāng jìn cuì yún qiú.", "jiǔ tiān chāng hé kāi gōng diàn,wàn guó yī guān bài miǎn liú.", "rì sè cái lín xiān zhǎng dòng,xiāng yān yù bàng gǔn lóng fú.", "cháo bà xū cái wǔ sè zhào,pèi shēng guī xiàng fèng chí tóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-166','奉和圣制从蓬莱向兴庆阁道',NULL,'王维',NULL,'唐','唐诗',FALSE,'["渭水自萦秦塞曲，黄山旧绕汉宫斜。", "銮舆迥出千门柳，阁道回看上苑花。", "云里帝城双凤阙，雨中春树万人家。", "为乘阳气行时令，不是宸游玩物华。"]'::jsonb,'["wèi shuǐ zì yíng qín sāi qū,huáng shān jiù rào hàn gōng xié.", "luán yú jiǒng chū qiān mén liǔ,gé dào huí kàn shàng yuàn huā.", "yún lǐ dì chéng shuāng fèng quē,yǔ zhōng chūn shù wàn rén jiā.", "wèi chéng yáng qì xíng shí lìng,bú shì chén yóu wán wù huá."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-167','积雨辋川庄作',NULL,'王维',NULL,'唐','唐诗',FALSE,'["积雨空林烟火迟，蒸藜炊黍饷东菑。", "漠漠水田飞白鹭，阴阴夏木啭黄鹂。", "山中习静观朝槿，松下清斋折露葵。", "野老与人争席罢，海鸥何事更相疑。"]'::jsonb,'["jī yǔ kōng lín yān huǒ chí,zhēng lí chuī shǔ xiǎng dōng zāi.", "mò mò shuǐ tián fēi bái lù,yīn yīn xià mù zhuàn huáng lí.", "shān zhōng xí jìng guān cháo jǐn,sōng xià qīng zhāi zhé lù kuí.", "yě lǎo yǔ rén zhēng xí bà,hǎi ōu hé shì gèng xiāng yí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-168','望月有感',NULL,'白居易',NULL,'唐','唐诗',FALSE,'["时难年荒世业空，弟兄羁旅各西东。", "田园寥落干戈后，骨肉流离道路中。", "吊影分为千里雁，辞根散作九秋蓬。", "共看明月应垂泪，一夜乡心五处同。"]'::jsonb,'["shí nán nián huāng shì yè kōng,dì xiōng jī lǚ gè xī dōng.", "tián yuán liáo luò gān gē hòu,gǔ ròu liú lí dào lù zhōng.", "diào yǐng fēn wéi qiān lǐ yàn,cí gēn sàn zuò jiǔ qiū péng.", "gòng kàn míng yuè yīng chuí lèi,yī yè xiāng xīn wǔ chù tóng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-169','奉和中书舍人贾至早朝',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["鸡鸣紫陌曙光寒，莺啭皇州春色阑。", "金阙晓钟开万户，玉阶仙仗拥千官。", "花迎剑珮星初落，柳拂旌旗露未干。", "独有凤凰池上客，阳春一曲和皆难。"]'::jsonb,'["jī míng zǐ mò shǔ guāng hán,yīng zhuàn huáng zhōu chūn sè lán.", "jīn què xiǎo zhōng kāi wàn hù,yù jiē xiān zhàng yōng qiān guān.", "huā yíng jiàn pèi xīng chū luò,liǔ fú jīng qí lù wèi gàn.", "dú yǒu fèng huáng chí shàng kè,yáng chūn yī qū hé jiē nán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-170','登金陵凤凰台',NULL,'李白',NULL,'唐','唐诗',FALSE,'["凤凰台上凤凰游，凤去台空江自流。", "吴宫花草埋幽径，晋代衣冠成古丘。", "三山半落青天外，二水中分白鹭洲。", "总为浮云能蔽日，长安不见使人愁。"]'::jsonb,'["fèng huáng tái shàng fèng huáng yóu,fèng qù tái kōng jiāng zì liú.", "wú gōng huā cǎo mái yōu jìng,jìn dài yī guān chéng gǔ qiū.", "sān shān bàn luò qīng tiān wài,èr shuǐ zhōng fēn bái lù zhōu.", "zǒng wèi fú yún néng bì rì,cháng ān bú jiàn shǐ rén chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-171','无题·重帏深下莫愁堂',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["重帏深下莫愁堂，卧后清宵细细长。", "神女生涯原是梦，小姑居处本无郎。", "风波不信菱枝弱，月露谁教桂叶香。", "直道相思了无益，未妨惆怅是清狂。"]'::jsonb,'["zhòng wéi shēn xià mò chóu táng,wò hòu qīng xiāo xì xì cháng.", "shén nǚ shēng yá yuán shì mèng,xiǎo gū jū chǔ běn wú láng.", "fēng bō bù xìn líng zhī ruò,yuè lù shuí jiào guì yè xiāng.", "zhí dào xiāng sī liǎo wú yì,wèi fáng chóu chàng shì qīng kuáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-172','无题·凤尾香罗薄几重',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["凤尾香罗薄几重，碧文圆顶夜深缝。", "扇裁月魄羞难掩，车走雷声语未通。", "曾是寂寥金烬暗，断无消息石榴红。", "斑骓只系垂杨岸，何处西南任好风。"]'::jsonb,'["fèng wěi xiāng luó báo jǐ zhòng,bì wén yuán dǐng yè shēn fèng.", "shàn cái yuè pò xiū nán yǎn,chē zǒu léi shēng yǔ wèi tōng.", "céng shì jì liáo jīn jìn àn,duàn wú xiāo xī shí liú hóng.", "bān zhuī zhǐ xì chuí yáng àn,hé chù xī nán rèn hǎo fēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-173','无题·相见时难别亦难',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["相见时难别亦难，东风无力百花残。", "春蚕到死丝方尽，蜡炬成灰泪始干。", "晓镜但愁云鬓改，夜吟应觉月光寒。", "蓬山此去无多路，青鸟殷勤为探看。"]'::jsonb,'["xiāng jiàn shí nán bié yì nán,dōng fēng wú lì bǎi huā cán.", "chūn cán dào sǐ sī fāng jìn,là jù chéng huī lèi shǐ gàn.", "xiǎo jìng dàn chóu yún bìn gǎi,yè yín yīng jué yuè guāng hán.", "péng shān cǐ qù wú duō lù,qīng niǎo yīn qín wèi tàn kàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-174','无题·来是空言去绝踪',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["来是空言去绝踪，月斜楼上五更钟。", "梦为远别啼难唤，书被催成墨未浓。", "蜡照半笼金翡翠，麝薰微度绣芙蓉。", "刘郎已恨蓬山远，更隔蓬山一万重！"]'::jsonb,'["lái shì kōng yán qù jué zōng,yuè xié lóu shàng wǔ gēng zhōng.", "mèng wèi yuǎn bié tí nán huàn,shū bèi cuī chéng mò wèi nóng.", "là zhào bàn lóng jīn fěi cuì,shè xūn wēi dù xiù fú róng.", "liú láng yǐ hèn péng shān yuǎn,gèng gé péng shān yī wàn zhòng!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-175','无题·飒飒东风细雨来',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["飒飒东风细雨来，芙蓉塘外有轻雷。", "金蟾啮锁烧香入，玉虎牵丝汲井回。", "贾氏窥帘韩掾少，宓妃留枕魏王才。", "春心莫共花争发，一寸相思一寸灰！"]'::jsonb,'["sà sà dōng fēng xì yǔ lái,fú róng táng wài yǒu qīng léi.", "jīn chán niè suǒ shāo xiāng rù,yù hǔ qiān sī jí jǐng huí.", "jiǎ shì kuī lián hán yuàn shǎo,mì fēi liú zhěn wèi wáng cái.", "chūn xīn mò gòng huā zhēng fā,yī cùn xiāng sī yī cùn huī!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-176','无题·昨夜星辰昨夜风',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["昨夜星辰昨夜风，画楼西畔桂堂东。", "身无彩凤双飞翼，心有灵犀一点通。", "隔座送钩春酒暖，分曹射复蜡灯红。", "嗟余听鼓应官去，走马兰台类转蓬。"]'::jsonb,'["zuó yè xīng chén zuó yè fēng,huà lóu xī pàn guì táng dōng.", "shēn wú cǎi fèng shuāng fēi yì,xīn yǒu líng xī yī diǎn tōng.", "gé zuò sòng gōu chūn jiǔ nuǎn,fēn cáo shè fù là dēng hóng.", "jiē yú tīng gǔ yīng guān qù,zǒu mǎ lán tái lèi zhuǎn péng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-177','春雨',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["怅卧新春白袷衣，白门寥落意多违。", "红楼隔雨相望冷，珠箔飘灯独自归。", "远路应悲春晼晚，残霄犹得梦依稀。", "玉珰缄札何由达，万里云罗一雁飞。"]'::jsonb,'["chàng wò xīn chūn bái jiá yī,bái mén liáo luò yì duō wéi.", "hóng lóu gé yǔ xiāng wàng lěng,zhū bó piāo dēng dú zì guī.", "yuǎn lù yīng bēi chūn wǎn wǎn,cán xiāo yóu dé mèng yī xī.", "yù dāng jiān zhá hé yóu dá,wàn lǐ yún luó yī yàn fēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-178','筹笔驿',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["猿鸟犹疑畏简书，风云常为护储胥。", "徒令上将挥神笔，终见降王走传车。", "管乐有才原不忝，关张无命欲何如？", "他年锦里经祠庙，梁父吟成恨有余。"]'::jsonb,'["yuán niǎo yóu yí wèi jiǎn shū,fēng yún cháng wèi hù chǔ xū.", "tú lìng shàng jiàng huī shén bǐ,zhōng jiàn jiàng wáng zǒu chuán chē.", "guǎn yuè yǒu cái yuán bù tiǎn,guān zhāng wú mìng yù hé rú?", "tā nián jǐn lǐ jīng cí miào,liáng fù yín chéng hèn yǒu yú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-179','锦瑟',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["锦瑟无端五十弦，一弦一柱思华年。", "庄生晓梦迷蝴蝶，望帝春心托杜鹃。", "沧海月明珠有泪，蓝田日暖玉生烟。", "此情可待成追忆，只是当时已惘然。"]'::jsonb,'["jǐn sè wú duān wǔ shí xián,yī xián yī zhù sī huá nián.", "zhuāng shēng xiǎo mèng mí hú dié,wàng dì chūn xīn tuō dù juān.", "cāng hǎi yuè míng zhū yǒu lèi,lán tián rì nuǎn yù shēng yān.", "cǐ qíng kě dài chéng zhuī yì,zhǐ shì dāng shí yǐ wǎng rán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-180','隋宫',NULL,'李商隐',NULL,'唐','唐诗',FALSE,'["紫泉宫殿锁烟霞，欲取芜城作帝家。", "玉玺不缘归日角，锦帆应是到天涯。", "于今腐草无萤火，终古垂杨有暮鸦。", "地下若逢陈后主，岂宜重问后庭花。"]'::jsonb,'["zǐ quán gōng diàn suǒ yān xiá,yù qǔ wú chéng zuò dì jiā.", "yù xǐ bù yuán guī rì jiǎo,jǐn fān yīng shì dào tiān yá.", "yú jīn fǔ cǎo wú yíng huǒ,zhōng gǔ chuí yáng yǒu mù yā.", "dì xià ruò féng chén hòu zhǔ,qǐ yí zhòng wèn hòu tíng huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-181','送魏万之京',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["朝闻游子唱离歌，昨夜微霜初渡河。", "鸿雁不堪愁里听，云山况是客中过。", "关城树色催寒近，御苑砧声向晚多。(", "色 一作：曙)", "莫见长安行乐处，空令岁月易蹉跎。"]'::jsonb,'["cháo wén yóu zi chàng lí gē,zuó yè wēi shuāng chū dù hé.", "hóng yàn bù kān chóu lǐ tīng,yún shān kuàng shì kè zhōng guò.", "guān chéng shù sè cuī hán jìn,yù yuàn zhēn shēng xiàng wǎn duō.(", "sè   yī zuò:shǔ )", "mò jiàn zhǎng ān xíng lè chù,kōng lìng suì yuè yì cuō tuó."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-182','咏怀古迹·其一',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["支离东北风尘际，漂泊西南天地间。", "三峡楼台淹日月，五溪衣服共云山。", "羯胡事主终无赖，词客哀时且未还。", "庾信平生最萧瑟，暮年诗赋动江关。"]'::jsonb,'["zhī lí dōng běi fēng chén jì,piāo bó xī nán tiān dì jiān.", "sān xiá lóu tái yān rì yuè,wǔ xī yī fú gòng yún shān.", "jié hú shì zhǔ zhōng wú lài,cí kè āi shí qiě wèi hái.", "yǔ xìn píng shēng zuì xiāo sè,mù nián shī fù dòng jiāng guān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-183','咏怀古迹·其二',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["摇落深知宋玉悲，风流儒雅亦吾师。", "怅望千秋一洒泪，萧条异代不同时。", "江山故宅空文藻，云雨荒台岂梦思。", "最是楚宫俱泯灭，舟人指点到今疑。"]'::jsonb,'["yáo luò shēn zhī sòng yù bēi,fēng liú rú yǎ yì wú shī.", "chàng wàng qiān qiū yī sǎ lèi,xiāo tiáo yì dài bù tóng shí.", "jiāng shān gù zhái kōng wén zǎo,yún yǔ huāng tái qǐ mèng sī.", "zuì shì chǔ gōng jù mǐn miè,zhōu rén zhǐ diǎn dào jīn yí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-184','咏怀古迹·其三',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["群山万壑赴荆门，生长明妃尚有村。", "一去紫台连朔漠，独留青冢向黄昏。", "画图省识春风面，环佩空归夜月魂。(夜月 一作：月夜 环", "一作：环", ")", "千载琵琶作胡语，分明怨恨曲中论。"]'::jsonb,'["qún shān wàn hè fù jīng mén,shēng zhǎng míng fēi shàng yǒu cūn.", "yī qù zǐ tái lián shuò mò,dú liú qīng zhǒng xiàng huáng hūn.", "huà tú shěng shí chūn fēng miàn,huán pèi kōng guī yè yuè hún.( yè yuè   yī zuò:yuè yè   huán", "yī zuò:huán", ")", "qiān zài pí pá zuò hú yǔ,fēn míng yuàn hèn qū zhōng lùn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-185','咏怀古迹·其四',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["蜀主窥吴幸三峡，崩年亦在永安宫。", "翠华想像空山里，玉殿虚无野寺中。", "古庙杉松巢水鹤，岁时伏腊走村翁。", "武侯祠堂常邻近，一体君臣祭祀同。"]'::jsonb,'["shǔ zhǔ kuī wú xìng sān xiá,bēng nián yì zài yǒng ān gōng.", "cuì huá xiǎng xiàng kōng shān lǐ,yù diàn xū wú yě sì zhōng.", "gǔ miào shān sōng cháo shuǐ hè,suì shí fú là zǒu cūn wēng.", "wǔ hóu cí táng cháng lín jìn,yī tǐ jūn chén jì sì tóng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-186','咏怀古迹·其五',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["诸葛大名垂宇宙，宗臣遗像肃清高。", "三分割据纡筹策，万古云霄一羽毛。", "伯仲之间见伊吕，指挥若定失萧曹。", "运移汉祚终难复，志决身歼军务劳。"]'::jsonb,'["zhū gě dà míng chuí yǔ zhòu,zōng chén yí xiàng sù qīng gāo.", "sān fēn gē jù yū chóu cè,wàn gǔ yún xiāo yī yǔ máo.", "bó zhòng zhī jiān jiàn yī lǚ,zhǐ huī ruò dìng shī xiāo cáo.", "yùn yí hàn zuò zhōng nán fù,zhì jué shēn jiān jūn wù láo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-187','宿府',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["清秋幕府井梧寒，独宿江城蜡炬残。", "永夜角声悲自语，中天月色好谁看。", "风尘荏苒音书绝，关塞萧条行路难。", "已忍伶俜十年事，强移栖息一枝安。"]'::jsonb,'["qīng qiū mù fǔ jǐng wú hán,dú sù jiāng chéng là jù cán.", "yǒng yè jiǎo shēng bēi zì yǔ,zhōng tiān yuè sè hǎo shuí kàn.", "fēng chén rěn rǎn yīn shū jué,guān sài xiāo tiáo xíng lù nán.", "yǐ rěn líng pīng shí nián shì,qiáng yí qī xī yī zhī ān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-188','阁夜',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["岁暮阴阳催短景，天涯霜雪霁寒宵。", "五更鼓角声悲壮，三峡星河影动摇。", "野哭几家闻战伐，夷歌数处起渔樵。", "卧龙跃马终黄土，人事依依漫寂寥。"]'::jsonb,'["suì mù yīn yáng cuī duǎn jǐng,tiān yá shuāng xuě jì hán xiāo.", "wǔ gēng gǔ jiǎo shēng bēi zhuàng,sān xiá xīng hé yǐng dòng yáo.", "yě kū jǐ jiā wén zhàn fá,yí gē shù chù qǐ yú qiáo.", "wò lóng yuè mǎ zhōng huáng tǔ,rén shì yī yī màn jì liáo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-189','闻官军收河南河北',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["剑外忽传收蓟北，初闻涕泪满衣裳。", "却看妻子愁何在，漫卷诗书喜欲狂。", "白日放歌须纵酒，青春作伴好还乡。", "即从巴峡穿巫峡，便下襄阳向洛阳。"]'::jsonb,'["jiàn wài hū chuán shōu jì běi,chū wén tì lèi mǎn yī shang.", "què kàn qī zǐ chóu hé zài,màn juǎn shī shū xǐ yù kuáng.", "bái rì fàng gē xū zòng jiǔ,qīng chūn zuò bàn hǎo huán xiāng.", "jí cóng bā xiá chuān wū xiá,biàn xià xiāng yáng xiàng luò yáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-190','登高',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["风急天高猿啸哀，渚清沙白鸟飞回。", "无边落木萧萧下，不尽长江滚滚来。", "万里悲秋常作客，百年多病独登台。", "艰难苦恨繁霜鬓，潦倒新停浊酒杯。"]'::jsonb,'["fēng jí tiān gāo yuán xiào āi,zhǔ qīng shā bái niǎo fēi huí.", "wú biān luò mù xiāo xiāo xià,bù jìn cháng jiāng gǔn gǔn lái.", "wàn lǐ bēi qiū cháng zuò kè,bǎi nián duō bìng dú dēng tái.", "jiān nán kǔ hèn fán shuāng bìn,liáo dǎo xīn tíng zhuó jiǔ bēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-191','登楼',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["花近高楼伤客心，万方多难此登临。", "锦江春色来天地，玉垒浮云变古今。", "北极朝廷终不改，西山寇盗莫相侵。", "可怜后主还祠庙，日暮聊为梁甫吟。"]'::jsonb,'["huā jìn gāo lóu shāng kè xīn,wàn fāng duō nán cǐ dēng lín.", "jǐn jiāng chūn sè lái tiān dì,yù lěi fú yún biàn gǔ jīn.", "běi jí cháo tíng zhōng bù gǎi,xī shān kòu dào mò xiāng qīn.", "kě lián hòu zhǔ hái cí miào,rì mù liáo wèi liáng fǔ yín."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-192','蜀相',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["丞相祠堂何处寻，锦官城外柏森森。", "映阶碧草自春色，隔叶黄鹂空好音。", "三顾频烦天下计，两朝开济老臣心。", "出师未捷身先死，长使英雄泪满襟。"]'::jsonb,'["chéng xiàng cí táng hé chù xún,jǐn guān chéng wài bǎi sēn sēn.", "yìng jiē bì cǎo zì chūn sè,gé yè huáng lí kōng hǎo yīn.", "sān gù pín fán tiān xià jì,liǎng cháo kāi jì lǎo chén xīn.", "chū shī wèi jié shēn xiān sǐ,zhǎng shǐ yīng xióng lèi mǎn jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-193','客至',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["舍南舍北皆春水，但见群鸥日日来。", "花径不曾缘客扫，蓬门今始为君开。", "盘飧市远无兼味，樽酒家贫只旧醅。", "肯与邻翁相对饮，隔篱呼取尽余杯。"]'::jsonb,'["shě nán shě běi jiē chūn shuǐ,dàn jiàn qún ōu rì rì lái.", "huā jìng bù céng yuán kè sǎo,péng mén jīn shǐ wèi jūn kāi.", "pán sūn shì yuǎn wú jiān wèi,zūn jiǔ jiā pín zhǐ jiù pēi.", "kěn yǔ lín wēng xiāng duì yǐn,gé lí hū qǔ jǐn yú bēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-194','野望',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["西山白雪三城戍，南浦清江万里桥。", "海内风尘诸弟隔，天涯涕泪一身遥。", "惟将迟暮供多病，未有涓埃答圣朝。", "跨马出郊时极目，不堪人事日萧条。"]'::jsonb,'["xī shān bái xuě sān chéng shù,nán pǔ qīng jiāng wàn lǐ qiáo.", "hǎi nèi fēng chén zhū dì gé,tiān yá tì lèi yī shēn yáo.", "wéi jiāng chí mù gōng duō bìng,wèi yǒu juān āi dá shèng cháo.", "kuà mǎ chū jiāo shí jí mù,bù kān rén shì rì xiāo tiáo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-195','登柳州城楼寄漳汀封连四州',NULL,'柳宗元',NULL,'唐','唐诗',FALSE,'["城上高楼接大荒，海天愁思正茫茫。", "惊风乱飐芙蓉水，密雨斜侵薜荔墙。", "岭树重遮千里目，江流曲似九回肠。", "共来百越文身地，犹自音书滞一乡。"]'::jsonb,'["chéng shàng gāo lóu jiē dà huāng,hǎi tiān chóu sī zhèng máng máng.", "jīng fēng luàn zhǎn fú róng shuǐ,mì yǔ xié qīn bì lì qiáng.", "lǐng shù zhòng zhē qiān lǐ mù,jiāng liú qū shì jiǔ huí cháng.", "gòng lái bǎi yuè wén shēn dì,yóu zì yīn shū zhì yī xiāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-196','春思',NULL,'皇甫冉',NULL,'唐','唐诗',FALSE,'["莺啼燕语报新年，马邑龙堆路几千。", "家住层城临汉苑，心随明月到胡天。", "机中锦字论长恨，楼上花枝笑独眠。", "为问元戎窦车骑，何时返旆勒燕然。"]'::jsonb,'["yīng tí yàn yǔ bào xīn nián,mǎ yì lóng duī lù jǐ qiān.", "jiā zhù céng chéng lín hàn yuàn,xīn suí míng yuè dào hú tiān.", "jī zhōng jǐn zì lùn zhǎng hèn,lóu shàng huā zhī xiào dú mián.", "wèi wèn yuán róng dòu chē qí,hé shí fǎn pèi lēi yàn rán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-197','寄李儋元锡',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["去年花里逢君别，今日花开又一年。", "世事茫茫难自料，春愁黯黯独成眠。", "身多疾病思田里，邑有流亡愧俸钱。", "闻道欲来相问讯，西楼望月几回圆。"]'::jsonb,'["qù nián huā lǐ féng jūn bié,jīn rì huā kāi yòu yī nián.", "shì shì máng máng nán zì liào,chūn chóu àn àn dú chéng mián.", "shēn duō jí bìng sī tián lǐ,yì yǒu liú wáng kuì fèng qián.", "wén dào yù lái xiāng wèn xùn,xī lóu wàng yuè jǐ huí yuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-198','望蓟门',NULL,'祖咏',NULL,'唐','唐诗',FALSE,'["燕台一望客心惊，笳鼓喧喧汉将营。", "万里寒光生积雪，三边曙色动危旌。", "沙场烽火侵胡月，海畔云山拥蓟城。", "少小虽非投笔吏，论功还欲请长缨。"]'::jsonb,'["yàn tái yī wàng kè xīn jīng,jiā gǔ xuān xuān hàn jiāng yíng.", "wàn lǐ hán guāng shēng jī xuě,sān biān shǔ sè dòng wēi jīng.", "shā chǎng fēng huǒ qīn hú yuè,hǎi pàn yún shān yōng jì chéng.", "shào xiǎo suī fēi tóu bǐ lì,lùn gōng hái yù qǐng cháng yīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-199','贫女',NULL,'秦韬玉',NULL,'唐','唐诗',FALSE,'["蓬门未识绮罗香，拟托良媒益自伤。", "谁爱风流高格调，共怜时世俭梳妆。", "敢将十指夸针巧，不把双眉斗画长。", "苦恨年年压金线，为他人作嫁衣裳。"]'::jsonb,'["péng mén wèi shí qǐ luó xiāng,nǐ tuō liáng méi yì zì shāng.", "shuí ài fēng liú gāo gé diào,gòng lián shí shì jiǎn shū zhuāng.", "gǎn jiāng shí zhǐ kuā zhēn qiǎo,bù bǎ shuāng méi dòu huà zhǎng.", "kǔ hèn nián nián yā jīn xiàn,wèi tā rén zuò jià yī shang."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-200','送李少府贬峡中王少府贬',NULL,'高适',NULL,'唐','唐诗',FALSE,'["嗟君此别意何如，驻马衔杯问谪居。", "巫峡啼猿数行泪，衡阳归雁几封书。", "青枫江上秋帆远，白帝城边古木疏。", "圣代即今多雨露，暂时分手莫踌躇。"]'::jsonb,'["jiē jūn cǐ bié yì hé rú,zhù mǎ xián bēi wèn zhé jū.", "wū xiá tí yuán shù xíng lèi,héng yáng guī yàn jǐ fēng shū.", "qīng fēng jiāng shàng qiū fān yuǎn,bái dì chéng biān gǔ mù shū.", "shèng dài jí jīn duō yǔ lù,zàn shí fēn shǒu mò chóu chú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-201','九日登望仙台呈刘明府',NULL,'崔曙',NULL,'唐','唐诗',FALSE,'["汉文皇帝有高台，此日登临曙色开。", "三晋云山皆北向，二陵风雨自东来。", "关门令尹谁能识，河上仙翁去不回。", "且欲近寻彭泽宰，陶然共醉菊花杯。"]'::jsonb,'["hàn wén huáng dì yǒu gāo tái,cǐ rì dēng lín shǔ sè kāi.", "sān jìn yún shān jiē běi xiàng,èr líng fēng yǔ zì dōng lái.", "guān mén lìng yǐn shuí néng shí,hé shàng xiān wēng qù bù huí.", "qiě yù jìn xún péng zé zǎi,táo rán gòng zuì jú huā bēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-202','登黄鹤楼',NULL,'崔颢',NULL,'唐','唐诗',FALSE,'["昔人已乘黄鹤去，此地空余黄鹤楼。", "黄鹤一去不复返，白云千载空悠悠。", "晴川历历汉阳树，芳草萋萋鹦鹉洲。", "日暮乡关何处是？烟波江上使人愁。"]'::jsonb,'["xī rén yǐ chéng huáng hè qù,cǐ dì kòng yú huáng hè lóu.", "huáng hè yī qù bù fù fǎn,bái yún qiān zài kōng yōu yōu.", "qíng chuān lì lì hàn yáng shù,fāng cǎo qī qī yīng wǔ zhōu.", "rì mù xiāng guān hé chù shì?yān bō jiāng shàng shǐ rén chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-203','行经华阴',NULL,'崔颢',NULL,'唐','唐诗',FALSE,'["岧峣太华俯咸京，天外三峰削不成。", "武帝祠前云欲散，仙人掌上雨初晴。", "河山北枕秦关险，驿树西连汉畤平。", "借问路傍名利客，无如此处学长生。"]'::jsonb,'["tiáo yáo tài huá fǔ xián jīng,tiān wài sān fēng xuē bù chéng.", "wǔ dì cí qián yún yù sàn,xiān rén zhǎng shàng yǔ chū qíng.", "hé shān běi zhěn qín guān xiǎn,yì shù xī lián hàn zhì píng.", "jiè wèn lù bàng míng lì kè,wú rú cǐ chù xué zhǎng shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-204','利州南渡',NULL,'温庭筠',NULL,'唐','唐诗',FALSE,'["澹然空水对斜晖，曲岛苍茫接翠微。", "波上马嘶看棹去，柳边人歇待船归。", "数丛沙草群鸥散，万顷江田一鹭飞。", "谁解乘舟寻范蠡，五湖烟水独忘机。"]'::jsonb,'["dàn rán kōng shuǐ duì xié huī,qū dǎo cāng máng jiē cuì wēi.", "bō shàng mǎ sī kàn zhào qù,liǔ biān rén xiē dài chuán guī.", "shù cóng shā cǎo qún ōu sàn,wàn qǐng jiāng tián yī lù fēi.", "shuí jiě chéng zhōu xún fàn lǐ,wǔ hú yān shuǐ dú wàng jī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-205','苏武庙',NULL,'温庭筠',NULL,'唐','唐诗',FALSE,'["苏武魂销汉使前，古祠高树两茫然。", "云边雁断胡天月，陇上羊归塞草烟。", "回日楼台非甲帐，去时冠剑是丁年。", "茂陵不见封侯印，空向秋波哭逝川。"]'::jsonb,'["sū wǔ hún xiāo hàn shǐ qián,gǔ cí gāo shù liǎng máng rán.", "yún biān yàn duàn hú tiān yuè,lǒng shàng yáng guī sāi cǎo yān.", "huí rì lóu tái fēi jiǎ zhàng,qù shí guān jiàn shì dīng nián.", "mào líng bú jiàn fēng hóu yìn,kōng xiàng qiū bō kū shì chuān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-206','江州重别薛六柳',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["生涯岂料承优诏，世事空知学醉歌。", "江上月明胡雁过，淮南木落楚山多。", "寄身且喜沧洲近，顾影无如白发何。", "今日龙钟人共弃，愧君犹遣慎风波。"]'::jsonb,'["shēng yá qǐ liào chéng yōu zhào,shì shì kōng zhī xué zuì gē.", "jiāng shàng yuè míng hú yàn guò,huái nán mù luò chǔ shān duō.", "jì shēn qiě xǐ cāng zhōu jìn,gù yǐng wú rú bái fà hé.", "jīn rì lóng zhōng rén gòng qì,kuì jūn yóu qiǎn shèn fēng bō."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-207','长沙过贾谊宅',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["三年谪宦此栖迟，万古惟留楚客悲。", "秋草独寻人去后，寒林空见日斜时。", "汉文有道恩犹薄，湘水无情吊岂知。", "寂寂江山摇落处，怜君何事到天涯。"]'::jsonb,'["sān nián zhé huàn cǐ qī chí,wàn gǔ wéi liú chǔ kè bēi.", "qiū cǎo dú xún rén qù hòu,hán lín kōng jiàn rì xié shí.", "hàn wén yǒu dào ēn yóu báo,xiāng shuǐ wú qíng diào qǐ zhī.", "jì jì jiāng shān yáo luò chù,lián jūn hé shì dào tiān yá."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-208','自夏口至鹦鹉洲夕望岳阳',NULL,'刘长卿',NULL,'唐','唐诗',FALSE,'["汀洲无浪复无烟，楚客相思益渺然。", "汉口夕阳斜渡鸟，洞庭秋水远连天。", "孤城背岭寒吹角，独树临江夜泊船。", "贾谊上书忧汉室，长沙谪去古今怜。"]'::jsonb,'["tīng zhōu wú làng fù wú yān,chǔ kè xiāng sī yì miǎo rán.", "hàn kǒu xī yáng xié dù niǎo,dòng tíng qiū shuǐ yuǎn lián tiān.", "gū chéng bèi lǐng hán chuī jiǎo,dú shù lín jiāng yè pō chuán.", "jiǎ yì shàng shū yōu hàn shì,cháng shā zhé qù gǔ jīn lián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-209','西塞山怀古',NULL,'刘禹锡',NULL,'唐','唐诗',FALSE,'["王濬楼船下益州，金陵王气黯然收。", "千寻铁锁沉江底，一片降幡出石头。", "人世几回伤往事，山形依旧枕寒流。", "今逢四海为家日，故垒萧萧芦荻秋。"]'::jsonb,'["wáng jùn lóu chuán xià yì zhōu,jīn líng wáng qì àn rán shōu.", "qiān xún tiě suǒ chén jiāng dǐ,yī piàn jiàng fān chū shí tou.", "rén shì jǐ huí shāng wǎng shì,shān xíng yī jiù zhěn hán liú.", "jīn féng sì hǎi wéi jiā rì,gù lěi xiāo xiāo lú dí qiū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-210','晚次鄂州',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["云开远见汉阳城，犹是孤帆一日程。", "估客昼眠知浪静，舟人夜语觉潮生。", "三湘愁鬓逢秋色，万里归心对月明。", "旧业已随征战尽，更堪江上鼓鼙声。"]'::jsonb,'["yún kāi yuǎn jiàn hàn yáng chéng,yóu shì gū fān yī rì chéng.", "gū kè zhòu mián zhī làng jìng,zhōu rén yè yǔ jué cháo shēng.", "sān xiāng chóu bìn féng qiū sè,wàn lǐ guī xīn duì yuè míng.", "jiù yè yǐ suí zhēng zhàn jǐn,gèng kān jiāng shàng gǔ pí shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-211','赠阙下裴舍人',NULL,'钱起',NULL,'唐','唐诗',FALSE,'["二月黄莺飞上林，春城紫禁晓阴阴。", "长乐钟声花外尽，龙池柳色雨中深。", "阳和不散穷途恨，霄汉长怀捧日心。", "献赋十年犹未遇，羞将白发对华簪。"]'::jsonb,'["èr yuè huáng yīng fēi shàng lín,chūn chéng zǐ jìn xiǎo yīn yīn.", "cháng lè zhōng shēng huā wài jǐn,lóng chí liǔ sè yǔ zhōng shēn.", "yáng hé bù sàn qióng tú hèn,xiāo hàn zhǎng huái pěng rì xīn.", "xiàn fù shí nián yóu wèi yù,xiū jiāng bái fà duì huá zān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-212','宫词',NULL,'薛逢',NULL,'唐','唐诗',FALSE,'["十二楼中尽晓妆，望仙楼上望君王。", "锁衔金兽连环冷，水滴铜龙昼漏长。", "云髻罢梳还对镜，罗衣欲换更添香。", "遥窥正殿帘开处，袍袴宫人扫御床。"]'::jsonb,'["shí èr lóu zhōng jǐn xiǎo zhuāng,wàng xiān lóu shàng wàng jūn wáng.", "suǒ xián jīn shòu lián huán lěng,shuǐ dī tóng lóng zhòu lòu zhǎng.", "yún jì bà shū hái duì jìng,luó yī yù huàn gèng tiān xiāng.", "yáo kuī zhèng diàn lián kāi chù,páo kù gōng rén sǎo yù chuáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-213','同题仙游观',NULL,'韩翃',NULL,'唐','唐诗',FALSE,'["仙台初见五城楼，风物凄凄宿雨收。", "山色遥连秦树晚，砧声近报汉宫秋。", "疏松影落空坛静，细草香闲小洞幽。", "何用别寻方外去，人间亦自有丹丘。"]'::jsonb,'["xiān tái chū jiàn wǔ chéng lóu,fēng wù qī qī sù yǔ shōu.", "shān sè yáo lián qín shù wǎn,zhēn shēng jìn bào hàn gōng qiū.", "shū sōng yǐng luò kōng tán jìng,xì cǎo xiāng xián xiǎo dòng yōu.", "hé yòng bié xún fāng wài qù,rén jiān yì zì yǒu dān qiū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言律诗'),
('base-214','贼退示官吏',NULL,'元结',NULL,'唐','唐诗',FALSE,'["昔岁逢太平，山林二十年。", "泉源在庭户，洞壑当门前。", "井税有常期，日晏犹得眠。", "忽然遭世变，数岁亲戎旃。", "今来典斯郡，山夷又纷然。", "城小贼不屠，人贫伤可怜。", "是以陷邻境，此州独见全。", "使臣将王命，岂不如贼焉？", "今彼征敛者，迫之如火煎。", "谁能绝人命，以作时世贤！", "思欲委符节，引竿自刺船。", "将家就鱼麦，归老江湖边。"]'::jsonb,'["xī suì féng tài píng,shān lín èr shí nián.", "quán yuán zài tíng hù,dòng hè dāng mén qián.", "jǐng shuì yǒu cháng qī,rì yàn yóu dé mián.", "hū rán zāo shì biàn,shù suì qīn róng zhān.", "jīn lái diǎn sī jùn,shān yí yòu fēn rán.", "chéng xiǎo zéi bù tú,rén pín shāng kě lián.", "shì yǐ xiàn lín jìng,cǐ zhōu dú jiàn quán.", "shǐ chén jiāng wáng mìng,qǐ bù rú zéi yān?", "jīn bǐ zhēng liǎn zhě,pò zhī rú huǒ jiān.", "shuí néng jué rén mìng,yǐ zuò shí shì xián!", "sī yù wěi fú jié,yǐn gān zì cì chuán.", "jiāng jiā jiù yú mài,guī lǎo jiāng hú biān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-215','同从弟销南斋玩月忆山阴',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["高卧南斋时，开帷月初吐。", "清辉澹水木，演漾在窗户。", "冉冉几盈虚，澄澄变今古。", "美人清江畔，是夜越吟苦。", "千里共如何，微风吹兰杜。"]'::jsonb,'["gāo wò nán zhāi shí,kāi wéi yuè chū tǔ.", "qīng huī dàn shuǐ mù,yǎn yàng zài chuāng hù.", "rǎn rǎn jǐ yíng xū,chéng chéng biàn jīn gǔ.", "měi rén qīng jiāng pàn,shì yè yuè yín kǔ.", "qiān lǐ gòng rú hé,wēi fēng chuī lán dù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-216','渭川田家',NULL,'王维',NULL,'唐','唐诗',FALSE,'["斜阳照墟落，穷巷牛羊归。", "野老念牧童，倚杖候荆扉。", "雉雊麦苗秀，蚕眠桑叶稀。", "田夫荷锄至，相见语依依。", "即此羡闲逸，怅然吟式微。"]'::jsonb,'["xié yáng zhào xū luò,qióng xiàng niú yáng guī.", "yě lǎo niàn mù tóng,yǐ zhàng hòu jīng fēi.", "zhì gòu mài miáo xiù,cán mián sāng yè xī.", "tián fū hè chú zhì,xiāng jiàn yǔ yī yī.", "jí cǐ xiàn xián yì,chàng rán yín shì wēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-217','西施咏',NULL,'王维',NULL,'唐','唐诗',FALSE,'["艳色天下重，西施宁久微。", "朝为越溪女，暮作吴宫妃。", "贱日岂殊众，贵来方悟稀。", "邀人傅香粉，不自著罗衣。", "君宠益娇态，君怜无是非。", "当时浣纱伴，莫得同车归。", "持谢邻家子，效颦安可希。"]'::jsonb,'["yàn sè tiān xià zhòng,xī shī níng jiǔ wēi.", "cháo wèi yuè xī nǚ,mù zuò wú gōng fēi.", "jiàn rì qǐ shū zhòng,guì lái fāng wù xī.", "yāo rén fù xiāng fěn,bù zì zhù luó yī.", "jūn chǒng yì jiāo tài,jūn lián wú shì fēi.", "dāng shí huàn shā bàn,mò dé tóng chē guī.", "chí xiè lín jiā zi,xiào pín ān kě xī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-218','送别',NULL,'王维',NULL,'唐','唐诗',FALSE,'["下马饮君酒，问君何所之？", "君言不得意，归卧南山陲。", "但去莫复问，白云无尽时。"]'::jsonb,'["xià mǎ yǐn jūn jiǔ,wèn jūn hé suǒ zhī?", "jūn yán bù dé yì,guī wò nán shān chuí.", "dàn qù mò fù wèn,bái yún wú jìn shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-219','送綦毋潜落第还乡',NULL,'王维',NULL,'唐','唐诗',FALSE,'["圣代无隐者，英灵尽来归。", "遂令东山客，不得顾采薇。", "既至金门远，孰云吾道非。", "江淮度寒食，京洛缝春衣。", "置酒长安道，同心与我违。", "行当浮桂棹，未几拂荆扉。", "远树带行客，孤城当落晖。", "吾谋适不用，勿谓知音稀。"]'::jsonb,'["shèng dài wú yǐn zhě,yīng líng jǐn lái guī.", "suì lìng dōng shān kè,bù dé gù cǎi wēi.", "jì zhì jīn mén yuǎn,shú yún wú dào fēi.", "jiāng huái dù hán shí,jīng luò fèng chūn yī.", "zhì jiǔ cháng ān dào,tóng xīn yǔ wǒ wéi.", "háng dāng fú guì zhào,wèi jǐ fú jīng fēi.", "yuǎn shù dài xíng kè,gū chéng dāng luò huī.", "wú móu shì bù yòng,wù wèi zhī yīn xī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-220','青溪',NULL,'王维',NULL,'唐','唐诗',FALSE,'["言入黄花川，每逐清溪水。", "随山将万转，趣途无百里。", "声喧乱石中，色静深松里。", "漾漾泛菱荇，澄澄映葭苇。", "我心素已闲，清川澹如此。", "请留磐石上，垂钓将已矣。"]'::jsonb,'["yán rù huáng huā chuān,měi zhú qīng xī shuǐ.", "suí shān jiāng wàn zhuǎn,qù tú wú bǎi lǐ.", "shēng xuān luàn shí zhōng,sè jìng shēn sōng lǐ.", "yàng yàng fàn líng xìng,chéng chéng yìng jiā wěi.", "wǒ xīn sù yǐ xián,qīng chuān dàn rú cǐ.", "qǐng liú pán shí shàng,chuí diào jiāng yǐ yǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-221','与高适薛据同登慈恩寺',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["塔势如涌出，孤高耸天宫。", "登临出世界，磴道盘虚空。", "突兀压神州，峥嵘如鬼工。", "四角碍白日，七层摩苍穹。", "下窥指高鸟，俯听闻惊风。", "连山若波涛，奔凑似朝东。", "青槐夹驰道，宫馆何玲珑。", "秋色从西来，苍然满关中。", "五陵北原上，万古青蒙蒙。", "净理了可悟，胜因夙所宗。", "誓将挂冠去，觉道资无穷。"]'::jsonb,'["tǎ shì rú yǒng chū,gū gāo sǒng tiān gōng.", "dēng lín chū shì jiè,dèng dào pán xū kōng.", "tū wù yā shén zhōu,zhēng róng rú guǐ gōng.", "sì jiǎo ài bái rì,qī céng mó cāng qióng.", "xià kuī zhǐ gāo niǎo,fǔ tīng wén jīng fēng.", "lián shān ruò bō tāo,bēn còu shì cháo dōng.", "qīng huái jiā chí dào,gōng guǎn hé líng lóng.", "qiū sè cóng xī lái,cāng rán mǎn guān zhōng.", "wǔ líng běi yuán shàng,wàn gǔ qīng méng méng.", "jìng lǐ le kě wù,shèng yīn sù suǒ zōng.", "shì jiāng guà guān qù,jué dào zī wú qióng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-222','下终南山过斛斯山人宿置酒',NULL,'李白',NULL,'唐','唐诗',FALSE,'["暮从碧山下，山月随人归。", "却顾所来径，苍苍横翠微。", "相携及田家，童稚开荆扉。", "绿竹入幽径，青萝拂行衣。", "欢言得所憩，美酒聊共挥。", "长歌吟松风，曲尽河星稀。", "我醉君复乐，陶然共忘机。"]'::jsonb,'["mù cóng bì shān xià,shān yuè suí rén guī.", "què gù suǒ lái jìng,cāng cāng héng cuì wēi.", "xiāng xié jí tián jiā,tóng zhì kāi jīng fēi.", "lǜ zhú rù yōu jìng,qīng luó fú xíng yī.", "huān yán dé suǒ qì,měi jiǔ liáo gòng huī.", "zhǎng gē yín sōng fēng,qū jǐn hé xīng xī.", "wǒ zuì jūn fù lè,táo rán gòng wàng jī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-223','月下独酌四首·其一',NULL,'李白',NULL,'唐','唐诗',FALSE,'["花间一壶酒，独酌无相亲。", "举杯邀明月，对影成三人。", "月既不解饮，影徒随我身。", "暂伴月将影，行乐须及春。", "我歌月徘徊，我舞影零乱。", "醒时同交欢，醉后各分散。", "永结无情游，相期邈云汉。"]'::jsonb,'["huā jiān yī hú jiǔ,dú zhuó wú xiāng qīn.", "jǔ bēi yāo míng yuè,duì yǐng chéng sān rén.", "yuè jì bù jiě yǐn,yǐng tú suí wǒ shēn.", "zàn bàn yuè jiāng yǐng,xíng lè xū jí chūn.", "wǒ gē yuè pái huái,wǒ wǔ yǐng líng luàn.", "xǐng shí tóng jiāo huān,zuì hòu gè fēn sàn.", "yǒng jié wú qíng yóu,xiāng qī miǎo yún hàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-224','春思',NULL,'李白',NULL,'唐','唐诗',FALSE,'["燕草如碧丝，秦桑低绿枝。", "当君怀归日，是妾断肠时。", "春风不相识，何事入罗帏。"]'::jsonb,'["yàn cǎo rú bì sī,qín sāng dī lǜ zhī.", "dāng jūn huái guī rì,shì qiè duàn cháng shí.", "chūn fēng bù xiāng shí,hé shì rù luó wéi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-225','梦李白·其一',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["死别已吞声，生别常恻恻。江南瘴疠地，逐客无消息。", "故人入我梦，明我长相忆。恐非平生魂，路远不可测。", "魂来枫叶青，魂返关塞黑。君今在罗网，何以有羽翼。", "落月满屋梁，犹疑照颜色。水深波浪阔，无使蛟龙得。"]'::jsonb,'["sǐ bié yǐ tūn shēng,shēng bié cháng cè cè.jiāng nán zhàng lì dì,zhú kè wú xiāo xī.", "gù rén rù wǒ mèng,míng wǒ zhǎng xiàng yì.kǒng fēi píng shēng hún,lù yuǎn bù kě cè.", "hún lái fēng yè qīng,hún fǎn guān sài hēi.jūn jīn zài luó wǎng,hé yǐ yǒu yǔ yì.", "luò yuè mǎn wū liáng,yóu yí zhào yán sè.shuǐ shēn bō làng kuò,wú shǐ jiāo lóng dé."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-226','梦李白·其二',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["浮云终日行，游子久不至。", "三夜频梦君，情亲见君意。", "告归常局促，苦道来不易。", "江湖多风波，舟楫恐失坠。", "出门搔白首，若负平生志。", "冠盖满京华，斯人独憔悴。", "孰云网恢恢，将老身反累。", "千秋万岁名，寂寞身后事。"]'::jsonb,'["fú yún zhōng rì xíng,yóu zi jiǔ bù zhì.", "sān yè pín mèng jūn,qíng qīn jiàn jūn yì.", "gào guī cháng jú cù,kǔ dào lái bù yì.", "jiāng hú duō fēng bō,zhōu jí kǒng shī zhuì.", "chū mén sāo bái shǒu,ruò fù píng shēng zhì.", "guān gài mǎn jīng huá,sī rén dú qiáo cuì.", "shú yún wǎng huī huī,jiāng lǎo shēn fǎn lèi.", "qiān qiū wàn suì míng,jì mò shēn hòu shì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-227','望岳',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["岱宗夫如何？齐鲁青未了。", "造化钟神秀，阴阳割昏晓。", "荡胸生曾云，决眦入归鸟。", "会当凌绝顶，一览众山小。"]'::jsonb,'["dài zōng fū rú hé?qí lǔ qīng wèi liǎo.", "zào huà zhōng shén xiù,yīn yáng gē hūn xiǎo.", "dàng xiōng shēng céng yún,jué zì rù guī niǎo.", "huì dāng líng jué dǐng,yī lǎn zhòng shān xiǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-228','赠卫八处士',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["人生不相见，动如参与商。", "今夕复何夕，共此灯烛光！", "少壮能几时？鬓发各已苍！", "访旧半为鬼，惊呼热中肠。"]'::jsonb,'["rén shēng bù xiāng jiàn,dòng rú cān yù shāng.", "jīn xī fù hé xī,gòng cǐ dēng zhú guāng!", "shào zhuàng néng jǐ shí?bìn fà gè yǐ cāng!", "fǎng jiù bàn wèi guǐ,jīng hū rè zhōng cháng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-229','佳人',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["绝代有佳人，幽居在空谷。", "自云良家女，零落依草木。", "关中昔丧乱，兄弟遭杀戮。", "官高何足论，不得收骨肉。", "世情恶衰歇，万事随转烛。", "夫婿轻薄儿，新人美如玉。", "合昏尚知时，鸳鸯不独宿。", "但见新人笑，那闻旧人哭。", "在山泉水清，出山泉水浊。", "侍婢卖珠回，牵萝补茅屋。", "摘花不插发，采柏动盈掬。", "天寒翠袖薄，日暮倚修竹。"]'::jsonb,'["jué dài yǒu jiā rén,yōu jū zài kōng gǔ.", "zì yún liáng jiā nǚ,líng luò yī cǎo mù.", "guān zhōng xī sāng luàn,xiōng dì zāo shā lù.", "guān gāo hé zú lùn,bù dé shōu gǔ ròu.", "shì qíng è shuāi xiē,wàn shì suí zhuǎn zhú.", "fū xù qīng bó ér,xīn rén měi rú yù.", "hé hūn shàng zhī shí,yuān yāng bù dú sù.", "dàn jiàn xīn rén xiào,nà wén jiù rén kū.", "zài shān quán shuǐ qīng,chū shān quán shuǐ zhuó.", "shì bì mài zhū huí,qiān luó bǔ máo wū.", "zhāi huā bù chā fā,cǎi bǎi dòng yíng jū.", "tiān hán cuì xiù báo,rì mù yǐ xiū zhú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-230','秋登兰山寄张五',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["北山白云里，隐者自怡悦。", "相望试登高，心随雁飞灭。", "愁因薄暮起，兴是清秋发。", "时见归村人，沙行渡头歇。", "天边树若荠，江畔洲如月。", "何当载酒来，共醉重阳节。"]'::jsonb,'["běi shān bái yún lǐ,yǐn zhě zì yí yuè.", "xiāng wàng shì dēng gāo,xīn suí yàn fēi miè.", "chóu yīn bó mù qǐ,xīng shì qīng qiū fā.", "shí jiàn guī cūn rén,shā xíng dù tóu xiē.", "tiān biān shù ruò jì,jiāng pàn zhōu rú yuè.", "hé dāng zài jiǔ lái,gòng zuì chóng yáng jié."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-231','夏日南亭怀辛大',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["山光忽西落，池月渐东上。", "散发乘夕凉，开轩卧闲敞。", "荷风送香气，竹露滴清响。", "欲取鸣琴弹，恨无知音赏。", "感此怀故人，中宵劳梦想。(", "宵 一作：终)"]'::jsonb,'["shān guāng hū xī luò,chí yuè jiàn dōng shàng.", "sàn fà chéng xī liáng,kāi xuān wò xián chǎng.", "hé fēng sòng xiāng qì,zhú lù dī qīng xiǎng.", "yù qǔ míng qín dàn,hèn wú zhī yīn shǎng.", "gǎn cǐ huái gù rén,zhōng xiāo láo mèng xiǎng.(", "xiāo   yī zuò:zhōng )"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-232','宿业师山房待丁大不至',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["夕阳度西岭，群壑倏已暝。", "松月生夜凉，风泉满清听。", "樵人归欲尽，烟鸟栖初定。", "之子期宿来，孤琴候萝径。"]'::jsonb,'["xī yáng dù xī lǐng,qún hè shū yǐ míng.", "sōng yuè shēng yè liáng,fēng quán mǎn qīng tīng.", "qiáo rén guī yù jǐn,yān niǎo qī chū dìng.", "zhī zi qī sù lái,gū qín hòu luó jìng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-233','寻西山隐者不遇',NULL,'丘为',NULL,'唐','唐诗',FALSE,'["绝顶一茅茨，直上三十里。", "扣关无僮仆，窥室唯案几。", "若非巾柴车，应是钓秋水。", "差池不相见，黾勉空仰止。", "草色新雨中，松声晚窗里。", "及兹契幽绝，自足荡心耳。", "虽无宾主意，颇得清净理。", "兴尽方下山，何必待之子。"]'::jsonb,'["jué dǐng yī máo cí,zhí shàng sān shí lǐ.", "kòu guān wú tóng pú,kuī shì wéi àn jǐ.", "ruò fēi jīn chái chē,yīng shì diào qiū shuǐ.", "chā chí bù xiāng jiàn,mǐn miǎn kōng yǎng zhǐ.", "cǎo sè xīn yǔ zhōng,sōng shēng wǎn chuāng lǐ.", "jí zī qì yōu jué,zì zú dàng xīn ěr.", "suī wú bīn zhǔ yì,pǒ dé qīng jìng lǐ.", "xīng jǐn fāng xià shān,hé bì dài zhī zi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-234','晨诣超师院读禅经',NULL,'柳宗元',NULL,'唐','唐诗',FALSE,'["汲井漱寒齿，清心拂尘服。", "闲持贝叶书，步出东斋读。", "真源了无取，妄迹世所逐。", "遗言冀可冥，缮性何由熟。", "道人庭宇静，苔色连深竹。", "日出雾露余，青松如膏沐。", "澹然离言说，悟悦心自足。"]'::jsonb,'["jí jǐng shù hán chǐ,qīng xīn fú chén fú.", "xián chí bèi yè shū,bù chū dōng zhāi dú.", "zhēn yuán liǎo wú qǔ,wàng jì shì suǒ zhú.", "yí yán jì kě míng,shàn xìng hé yóu shú.", "dào rén tíng yǔ jìng,tái sè lián shēn zhú.", "rì chū wù lù yú,qīng sōng rú gāo mù.", "dàn rán lí yán shuō,wù yuè xīn zì zú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-235','溪居',NULL,'柳宗元',NULL,'唐','唐诗',FALSE,'["久为簪组累，幸此南夷谪。", "闲依农圃邻，偶似山林客。", "晓耕翻露草，夜榜响溪石。", "来往不逢人，长歌楚天碧。"]'::jsonb,'["jiǔ wèi zān zǔ lèi,xìng cǐ nán yí zhé.", "xián yī nóng pǔ lín,ǒu shì shān lín kè.", "xiǎo gēng fān lù cǎo,yè bǎng xiǎng xī shí.", "lái wǎng bù féng rén,zhǎng gē chǔ tiān bì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-236','送杨氏女',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["永日方戚戚，出行复悠悠。", "女子今有行，大江溯轻舟。", "尔辈苦无恃，抚念益慈柔。", "幼为长所育，两别泣不休。", "对此结中肠，义往难复留。", "自小阙内训，事姑贻我忧。", "赖兹托令门，任恤庶无尤。", "贫俭诚所尚，资从岂待周。", "孝恭遵妇道，容止顺其猷。", "别离在今晨，见尔当何秋。", "居闲始自遣，临感忽难收。", "归来视幼女，零泪缘缨流。"]'::jsonb,'["yǒng rì fāng qī qī,chū xíng fù yōu yōu.", "nǚ zǐ jīn yǒu xíng,dà jiāng sù qīng zhōu.", "ěr bèi kǔ wú shì,fǔ niàn yì cí róu.", "yòu wèi zhǎng suǒ yù,liǎng bié qì bù xiū.", "duì cǐ jié zhōng cháng,yì wǎng nán fù liú.", "zì xiǎo quē nèi xùn,shì gū yí wǒ yōu.", "lài zī tuō lìng mén,rèn xù shù wú yóu.", "pín jiǎn chéng suǒ shàng,zī cóng qǐ dài zhōu.", "xiào gōng zūn fù dào,róng zhǐ shùn qí yóu.", "bié lí zài jīn chén,jiàn ěr dāng hé qiū.", "jū xián shǐ zì qiǎn,lín gǎn hū nán shōu.", "guī lái shì yòu nǚ,líng lèi yuán yīng liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-237','长安遇冯著',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["客从东方来，衣上灞陵雨。", "问客何为来，采山因买斧。", "冥冥花正开，飏飏燕新乳。", "昨别今已春，鬓丝生几缕。"]'::jsonb,'["kè cóng dōng fāng lái,yī shàng bà líng yǔ.", "wèn kè hé wèi lái,cǎi shān yīn mǎi fǔ.", "míng míng huā zhèng kāi,yáng yáng yàn xīn rǔ.", "zuó bié jīn yǐ chūn,bìn sī shēng jǐ lǚ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-238','夕次盱眙县',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["落帆逗淮镇，停舫临孤驿。浩浩风起波，冥冥日沉夕。", "人归山郭暗，雁下芦洲白。独夜忆秦关，听钟未眠客。"]'::jsonb,'["luò fān dòu huái zhèn,tíng fǎng lín gū yì.hào hào fēng qǐ bō,míng míng rì chén xī.", "rén guī shān guō àn,yàn xià lú zhōu bái.dú yè yì qín guān,tīng zhōng wèi mián kè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-239','东郊',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["吏舍跼终年，出郊旷清曙。", "杨柳散和风，青山澹吾虑。", "依丛适自憩，缘涧还复去。", "微雨霭芳原，春鸠鸣何处。", "乐幽心屡止，遵事迹犹遽。", "终罢斯结庐，慕陶直可庶。"]'::jsonb,'["lì shě jú zhōng nián,chū jiāo kuàng qīng shǔ.", "yáng liǔ sàn hé fēng,qīng shān dàn wú lǜ.", "yī cóng shì zì qì,yuán jiàn hái fù qù.", "wēi yǔ ǎi fāng yuán,chūn jiū míng hé chù.", "lè yōu xīn lǚ zhǐ,zūn shì jì yóu jù.", "zhōng bà sī jié lú,mù táo zhí kě shù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-240','郡斋雨中与诸文士燕集',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["兵卫森画戟，宴寝凝清香。", "海上风雨至，逍遥池阁凉。", "烦疴近消散，嘉宾复满堂。", "自惭居处崇，未睹斯民康。", "理会是非遣，性达形迹忘。", "鲜肥属时禁，蔬果幸见尝。", "俯饮一杯酒，仰聆金玉章。", "神欢体自轻，意欲凌风翔。", "吴中盛文史，群彦今汪洋。", "方知大藩地，岂曰财赋强。"]'::jsonb,'["bīng wèi sēn huà jǐ,yàn qǐn níng qīng xiāng.", "hǎi shàng fēng yǔ zhì,xiāo yáo chí gé liáng.", "fán kē jìn xiāo sàn,jiā bīn fù mǎn táng.", "zì cán jū chǔ chóng,wèi dǔ sī mín kāng.", "lǐ huì shì fēi qiǎn,xìng dá xíng jì wàng.", "xiān féi shǔ shí jìn,shū guǒ xìng jiàn cháng.", "fǔ yǐn yī bēi jiǔ,yǎng líng jīn yù zhāng.", "shén huān tǐ zì qīng,yì yù líng fēng xiáng.", "wú zhōng shèng wén shǐ,qún yàn jīn wāng yáng.", "fāng zhī dà fān dì,qǐ yuē cái fù qiáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-241','初发扬子寄元大校书',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["凄凄去亲爱，泛泛入烟雾。", "归棹洛阳人，残钟广陵树。", "今朝此为别，何处还相遇。", "世事波上舟，沿洄安得住。"]'::jsonb,'["qī qī qù qīn ài,fàn fàn rù yān wù.", "guī zhào luò yáng rén,cán zhōng guǎng líng shù.", "jīn zhāo cǐ wèi bié,hé chù hái xiāng yù.", "shì shì bō shàng zhōu,yán huí ān dé zhù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-242','寄全椒山中道士',NULL,'韦应物',NULL,'唐','唐诗',FALSE,'["今朝郡斋冷，忽念山中客。", "涧底束荆薪，归来煮白石。", "欲持一瓢酒，远慰风雨夕。", "落叶满空山，何处寻行迹。"]'::jsonb,'["jīn zhāo jùn zhāi lěng,hū niàn shān zhōng kè.", "jiàn dǐ shù jīng xīn,guī lái zhǔ bái shí.", "yù chí yī piáo jiǔ,yuǎn wèi fēng yǔ xī.", "luò yè mǎn kōng shān,hé chù xún xíng jì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-243','宿王昌龄隐居',NULL,'常建',NULL,'唐','唐诗',FALSE,'["清溪深不测，隐处唯孤云。", "松际露微月，清光犹为君。", "茅亭宿花影，药院滋苔纹。", "余亦谢时去，西山鸾鹤群。"]'::jsonb,'["qīng xī shēn bù cè,yǐn chù wéi gū yún.", "sōng jì lù wēi yuè,qīng guāng yóu wèi jūn.", "máo tíng sù huā yǐng,yào yuàn zī tái wén.", "yú yì xiè shí qù,xī shān luán hè qún."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-244','感遇·孤鸿海上来',NULL,'张九龄',NULL,'唐','唐诗',FALSE,'["孤鸿海上来，池潢不敢顾。", "侧见双翠鸟，巢在三珠树。", "矫矫珍木巅，得无金丸惧？", "美服患人指，高明逼神恶。", "今我游冥冥，弋者何所慕！"]'::jsonb,'["gū hóng hǎi shàng lái,chí huáng bù gǎn gù.", "cè jiàn shuāng cuì niǎo,cháo zài sān zhū shù.", "jiǎo jiǎo zhēn mù diān,dé wú jīn wán jù?", "měi fú huàn rén zhǐ,gāo míng bī shén è.", "jīn wǒ yóu míng míng,yì zhě hé suǒ mù!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-245','感遇·兰叶春葳蕤',NULL,'张九龄',NULL,'唐','唐诗',FALSE,'["兰叶春葳蕤，桂华秋皎洁。", "欣欣此生意，自尔为佳节。", "谁知林栖者，闻风坐相悦。", "草木有本心，何求美人折！"]'::jsonb,'["lán yè chūn wēi ruí,guì huá qiū jiǎo jié.", "xīn xīn cǐ shēng yì,zì ěr wèi jiā jié.", "shuí zhī lín qī zhě,wén fēng zuò xiāng yuè.", "cǎo mù yǒu běn xīn,hé qiú měi rén zhé!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-246','感遇·幽人归独卧',NULL,'张九龄',NULL,'唐','唐诗',FALSE,'["幽人归独卧，滞虑洗孤清。", "持此谢高鸟，因之传远情。", "日夕怀空意，人谁感至精？", "飞沈理自隔，何所慰吾诚?"]'::jsonb,'["yōu rén guī dú wò,zhì lǜ xǐ gū qīng.", "chí cǐ xiè gāo niǎo,yīn zhī chuán yuǎn qíng.", "rì xī huái kōng yì,rén shuí gǎn zhì jīng?", "fēi shěn lǐ zì gé,hé suǒ wèi wú chéng ?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-247','感遇·江南有丹橘',NULL,'张九龄',NULL,'唐','唐诗',FALSE,'["江南有丹橘，经冬犹绿林。", "岂伊地气暖？自有岁寒心。", "可以荐嘉客，奈何阻重深。", "运命惟所遇，循环不可寻。", "徒言树桃李，此木岂无阴？"]'::jsonb,'["jiāng nán yǒu dān jú,jīng dōng yóu lù lín.", "qǐ yī dì qì nuǎn?zì yǒu suì hán xīn.", "kě yǐ jiàn jiā kè,nài hé zǔ zhòng shēn.", "yùn mìng wéi suǒ yù,xún huán bù kě xún.", "tú yán shù táo lǐ,cǐ mù qǐ wú yīn?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-248','春泛若耶溪',NULL,'綦毋潜',NULL,'唐','唐诗',FALSE,'["幽意无断绝，此去随所偶。", "晚风吹行舟，花路入溪口。", "际夜转西壑，隔山望南斗。", "潭烟飞溶溶，林月低向后。", "生事且弥漫，愿为持竿叟。"]'::jsonb,'["yōu yì wú duàn jué,cǐ qù suí suǒ ǒu.", "wǎn fēng chuī xíng zhōu,huā lù rù xī kǒu.", "jì yè zhuǎn xī hè,gé shān wàng nán dòu.", "tán yān fēi róng róng,lín yuè dī xiàng hòu.", "shēng shì qiě mí màn,yuàn wèi chí gān sǒu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'五言古诗'),
('base-249','石鱼湖上醉歌',NULL,'元结',NULL,'唐','唐诗',FALSE,'["石鱼湖，似洞庭，夏水欲满君山青。", "山为樽，水为沼，酒徒历历坐洲岛。", "长风连日作大浪，不能废人运酒舫。", "我持长瓢坐巴丘，酌饮四坐以散愁。"]'::jsonb,'["shí yú hú,shì dòng tíng,xià shuǐ yù mǎn jūn shān qīng.", "shān wèi zūn,shuǐ wèi zhǎo,jiǔ tú lì lì zuò zhōu dǎo.", "zhǎng fēng lián rì zuò dà làng,bù néng fèi rén yùn jiǔ fǎng.", "wǒ chí zhǎng piáo zuò bā qiū,zhuó yǐn sì zuò yǐ sàn chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-250','走马川行奉送封大夫出师',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["君不见走马川行雪海边，平沙莽莽黄入天。", "轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。", "匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。", "将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。", "马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。", "虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。"]'::jsonb,'["jūn bú jiàn zǒu mǎ chuān xíng xuě hǎi biān,píng shā mǎng mǎng huáng rù tiān.", "lún tái jiǔ yuè fēng yè hǒu,yī chuān suì shí dà rú dòu,suí fēng mǎn dì shí luàn zǒu.", "xiōng nú cǎo huáng mǎ zhèng féi,jīn shān xī jiàn yān chén fēi,hàn jiā dà jiàng xī chū shī.", "jiāng jūn jīn jiǎ yè bù tuō,bàn yè jūn xíng gē xiāng bō,fēng tou rú dāo miàn rú gē.", "mǎ máo dài xuě hàn qì zhēng,wǔ huā lián qián xuán zuò bīng,mù zhōng cǎo xí yàn shuǐ níng.", "lǔ qí wén zhī yīng dǎn shè,liào zhī duǎn bīng bù gǎn jiē,chē shī xī mén zhù xiàn jié."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-251','轮台歌奉送封大夫出师',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["轮台城头夜吹角，轮台城北旄头落。", "羽书昨夜过渠黎，单于已在金山西。", "戍楼西望烟尘黑，汉军屯在轮台北。", "上将拥旄西出征，平明吹笛大军行。", "四边伐鼓雪海涌，三军大呼阴山动。", "虏塞兵气连云屯，战场白骨缠草根。", "剑河风急雪片阔，沙口石冻马蹄脱。", "亚相勤王甘苦辛，誓将报主静边尘。", "古来青史谁不见，今见功名胜古人。"]'::jsonb,'["lún tái chéng tóu yè chuī jiǎo,lún tái chéng běi máo tóu luò.", "yǔ shū zuó yè guò qú lí,chán yú yǐ zài jīn shān xī.", "shù lóu xī wàng yān chén hēi,hàn jūn tún zài lún tái běi.", "shàng jiàng yōng máo xī chū zhēng,píng míng chuī dí dà jūn xíng.", "sì biān fá gǔ xuě hǎi yǒng,sān jūn dà hū yīn shān dòng.", "lǔ sāi bīng qì lián yún tún,zhàn chǎng bái gǔ chán cǎo gēn.", "jiàn hé fēng jí xuě piàn kuò,shā kǒu shí dòng mǎ tí tuō.", "yà xiāng qín wáng gān kǔ xīn,shì jiāng bào zhǔ jìng biān chén.", "gǔ lái qīng shǐ shuí bú jiàn,jīn jiàn gōng míng shèng gǔ rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-252','白雪歌送武判官归京',NULL,'岑参',NULL,'唐','唐诗',FALSE,'["北风卷地白草折，胡天八月即飞雪。", "忽如一夜春风来，千树万树梨花开。", "散入珠帘湿罗幕，狐裘不暖锦衾薄。", "将军角弓不得控，都护铁衣冷难着。", "瀚海阑干百丈冰，愁云惨淡万里凝。", "中军置酒饮归客，胡琴琵琶与羌笛。", "纷纷暮雪下辕门，风掣红旗冻不翻。", "轮台东门送君去，去时雪满天山路。", "山回路转不见君，雪上空留马行处。"]'::jsonb,'["běi fēng juǎn dì bái cǎo zhé,hú tiān bā yuè jí fēi xuě.", "hū rú yī yè chūn fēng lái,qiān shù wàn shù lí huā kāi.", "sàn rù zhū lián shī luó mù,hú qiú bù nuǎn jǐn qīn báo.", "jiāng jūn jiǎo gōng bù dé kòng,dōu hù tiě yī lěng nán zhe.", "hàn hǎi lán gān bǎi zhàng bīng,chóu yún cǎn dàn wàn lǐ níng.", "zhōng jūn zhì jiǔ yǐn guī kè,hú qín pí pá yǔ qiāng dí.", "fēn fēn mù xuě xià yuán mén,fēng chè hóng qí dòng bù fān.", "lún tái dōng mén sòng jūn qù,qù shí xuě mǎn tiān shān lù.", "shān huí lù zhuǎn bú jiàn jūn,xuě shàng kōng liú mǎ xíng chù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-253','宣州谢脁楼饯别校书叔云',NULL,'李白',NULL,'唐','唐诗',FALSE,'["弃我去者，昨日之日不可留；", "乱我心者，今日之日多烦忧。", "长风万里送秋雁，对此可以酣高楼。", "蓬莱文章建安骨，中间小谢又清发。", "俱怀逸兴壮思飞，欲上青天揽明月。", "抽刀断水水更流，举杯消愁愁更愁。", "人生在世不称意，明朝散发弄扁舟。"]'::jsonb,'["qì wǒ qù zhě,zuó rì zhī rì bù kě liú;", "luàn wǒ xīn zhě,jīn rì zhī rì duō fán yōu.", "zhǎng fēng wàn lǐ sòng qiū yàn,duì cǐ kě yǐ hān gāo lóu.", "péng lái wén zhāng jiàn ān gǔ,zhōng jiān xiǎo xiè yòu qīng fā.", "jù huái yì xīng zhuàng sī fēi,yù shàng qīng tiān lǎn míng yuè.", "chōu dāo duàn shuǐ shuǐ gèng liú,jǔ bēi xiāo chóu chóu gèng chóu.", "rén shēng zài shì bù chēng yì,míng cháo sàn fà nòng piān zhōu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-254','庐山谣寄卢侍御虚舟',NULL,'李白',NULL,'唐','唐诗',FALSE,'["我本楚狂人，凤歌笑孔丘。", "手持绿玉杖，朝别黄鹤楼。", "五岳寻仙不辞远，一生好入名山游。", "庐山秀出南斗傍，屏风九叠云锦张。", "影落明湖青黛光，金阙前开二峰长，银河倒挂三石梁。", "香炉瀑布遥相望，回崖沓嶂凌苍苍。", "翠影红霞映朝日，鸟飞不到吴天长。", "登高壮观天地间，大江茫茫去不还。", "黄云万里动风色，白波九道流雪山。", "好为庐山谣，兴因庐山发。", "闲窥石镜清我心，谢公行处苍苔没。", "早服还丹无世情，琴心三叠道初成。", "遥见仙人彩云里，手把芙蓉朝玉京。", "先期汗漫九垓上，愿接卢敖游太清。"]'::jsonb,'["wǒ běn chǔ kuáng rén,fèng gē xiào kǒng qiū.", "shǒu chí lǜ yù zhàng,cháo bié huáng hè lóu.", "wǔ yuè xún xiān bù cí yuǎn,yī shēng hǎo rù míng shān yóu.", "lú shān xiù chū nán dòu bàng,píng fēng jiǔ dié yún jǐn zhāng.", "yǐng luò míng hú qīng dài guāng,jīn què qián kāi èr fēng zhǎng,yín hé dào guà sān shí liáng.", "xiāng lú pù bù yáo xiāng wàng,huí yá dá zhàng líng cāng cāng.", "cuì yǐng hóng xiá yìng zhāo rì,niǎo fēi bú dào wú tiān zhǎng.", "dēng gāo zhuàng guān tiān dì jiān,dà jiāng máng máng qù bù hái.", "huáng yún wàn lǐ dòng fēng sè,bái bō jiǔ dào liú xuě shān.", "hǎo wèi lú shān yáo,xīng yīn lú shān fā.", "xián kuī shí jìng qīng wǒ xīn,xiè gōng xíng chù cāng tái méi.", "zǎo fú hái dān wú shì qíng,qín xīn sān dié dào chū chéng.", "yáo jiàn xiān rén cǎi yún lǐ,shǒu bǎ fú róng cháo yù jīng.", "xiān qī hàn màn jiǔ gāi shàng,yuàn jiē lú áo yóu tài qīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-255','金陵酒肆留别',NULL,'李白',NULL,'唐','唐诗',FALSE,'["风吹柳花满店香，吴姬压酒唤客尝。", "金陵子弟来相送，欲行不行各尽觞。", "请君试问东流水，别意与之谁短长。"]'::jsonb,'["fēng chuī liǔ huā mǎn diàn xiāng,wú jī yā jiǔ huàn kè cháng.", "jīn líng zǐ dì lái xiāng sòng,yù xíng bù xíng gè jǐn shāng.", "qǐng jūn shì wèn dōng liú shuǐ,bié yì yǔ zhī shuí duǎn cháng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-256','听董大弹胡笳声兼寄语',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["蔡女昔造胡笳声，一弹一十有八拍。", "胡人落泪沾边草，汉使断肠对归客。", "古戍苍苍烽火寒，大荒沉沉飞雪白。", "先拂商弦后角羽，四郊秋叶惊摵摵。", "董夫子，通神明，深山窃听来妖精。", "言迟更速皆应手，将往复旋如有情。", "空山百鸟散还合，万里浮云阴且晴。", "嘶酸雏雁失群夜，断绝胡儿恋母声。", "川为静其波，鸟亦罢其鸣。", "乌孙部落家乡远，逻娑沙尘哀怨生。", "幽音变调忽飘洒，长风吹林雨堕瓦。", "迸泉飒飒飞木末，野鹿呦呦走堂下。", "长安城连东掖垣，凤凰池对青琐门。", "高才脱略名与利，日夕望君抱琴至。"]'::jsonb,'["cài nǚ xī zào hú jiā shēng,yī dàn yī shí yǒu bā pāi.", "hú rén luò lèi zhān biān cǎo,hàn shǐ duàn cháng duì guī kè.", "gǔ shù cāng cāng fēng huǒ hán,dà huāng chén chén fēi xuě bái.", "xiān fú shāng xián hòu jiǎo yǔ,sì jiāo qiū yè jīng shè shè.", "dǒng fū zǐ,tōng shén míng,shēn shān qiè tīng lái yāo jīng.", "yán chí gèng sù jiē yìng shǒu,jiāng wǎng fù xuán rú yǒu qíng.", "kōng shān bǎi niǎo sàn hái hé,wàn lǐ fú yún yīn qiě qíng.", "sī suān chú yàn shī qún yè,duàn jué hú ér liàn mǔ shēng.", "chuān wèi jìng qí bō,niǎo yì bà qí míng.", "wū sūn bù luò jiā xiāng yuǎn,luó suō shā chén āi yuàn shēng.", "yōu yīn biàn diào hū piāo sǎ,zhǎng fēng chuī lín yǔ duò wǎ.", "bèng quán sà sà fēi mù mò,yě lù yōu yōu zǒu táng xià.", "cháng ān chéng lián dōng yē yuán,fèng huáng chí duì qīng suǒ mén.", "gāo cái tuō lüè míng yǔ lì,rì xī wàng jūn bào qín zhì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-257','听安万善吹觱篥歌',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["南山截竹为觱篥，此乐本自龟兹出。", "流传汉地曲转奇，凉州胡人为我吹。", "傍邻闻者多叹息，远客思乡皆泪垂。", "世人解听不解赏，长飙风中自来往。", "枯桑老柏寒飕飗，九雏鸣凤乱啾啾。", "龙吟虎啸一时发，万籁百泉相与秋。", "忽然更作渔阳掺，黄云萧条白日暗。", "变调如闻杨柳春，上林繁花照眼新。", "岁夜高堂列明烛，美酒一杯声一曲。"]'::jsonb,'["nán shān jié zhú wèi bì lì,cǐ lè běn zì qiū cí chū.", "liú chuán hàn dì qū zhuǎn qí,liáng zhōu hú rén wéi wǒ chuī.", "bàng lín wén zhě duō tàn xī,yuǎn kè sī xiāng jiē lèi chuí.", "shì rén jiě tīng bù jiě shǎng,zhǎng biāo fēng zhōng zì lái wǎng.", "kū sāng lǎo bǎi hán sōu liú,jiǔ chú míng fèng luàn jiū jiū.", "lóng yín hǔ xiào yī shí fā,wàn lài bǎi quán xiāng yǔ qiū.", "hū rán gèng zuò yú yáng càn,huáng yún xiāo tiáo bái rì àn.", "biàn diào rú wén yáng liǔ chūn,shàng lín fán huā zhào yǎn xīn.", "suì yè gāo táng liè míng zhú,měi jiǔ yī bēi shēng yī qū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-258','古意',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["男儿事长征，少小幽燕客。", "赌胜马蹄下，由来轻七尺。", "杀人莫敢前，须如猬毛磔。", "黄云陇底白云飞，未得报恩不能归。", "辽东小妇年十五，惯弹琵琶解歌舞。", "今为羌笛出塞声，使我三军泪如雨。"]'::jsonb,'["nán ér shì cháng zhēng,shào xiǎo yōu yàn kè.", "dǔ shèng mǎ tí xià,yóu lái qīng qī chǐ.", "shā rén mò gǎn qián,xū rú wèi máo zhé.", "huáng yún lǒng dǐ bái yún fēi,wèi dé bào ēn bù néng guī.", "liáo dōng xiǎo fù nián shí wǔ,guàn dàn pí pá jiě gē wǔ.", "jīn wèi qiāng dí chū sài shēng,shǐ wǒ sān jūn lèi rú yǔ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-259','送陈章甫',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["四月南风大麦黄，枣花未落桐阴长。", "青山朝别暮还见，嘶马出门思旧乡。", "陈侯立身何坦荡，虬须虎眉仍大颡。", "腹中贮书一万卷，不肯低头在草莽。", "东门酤酒饮我曹，心轻万事如鸿毛。", "醉卧不知白日暮，有时空望孤云高。", "长河浪头连天黑，津口停舟渡不得。", "郑国游人未及家，洛阳行子空叹息。", "闻道故林相识多，罢官昨日今如何。"]'::jsonb,'["sì yuè nán fēng dà mài huáng,zǎo huā wèi luò tóng yīn zhǎng.", "qīng shān cháo bié mù hái jiàn,sī mǎ chū mén sī jiù xiāng.", "chén hóu lì shēn hé tǎn dàng,qiú xū hǔ méi réng dà sǎng.", "fù zhōng zhù shū yī wàn juàn,bù kěn dī tóu zài cǎo mǎng.", "dōng mén gū jiǔ yǐn wǒ cáo,xīn qīng wàn shì rú hóng máo.", "zuì wò bù zhī bái rì mù,yǒu shí kōng wàng gū yún gāo.", "cháng hé làng tou lián tiān hēi,jīn kǒu tíng zhōu dù bù dé.", "zhèng guó yóu rén wèi jí jiā,luò yáng xíng zi kōng tàn xī.", "wén dào gù lín xiāng shí duō,bà guān zuó rì jīn rú hé."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-260','琴歌',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["主人有酒欢今夕，请奏鸣琴广陵客。", "月照城头乌半飞，霜凄万树风入衣。", "铜炉华烛烛增辉，初弹渌水后楚妃。", "一声已动物皆静，四座无言星欲稀。", "清淮奉使千余里，敢告云山从此始。"]'::jsonb,'["zhǔ rén yǒu jiǔ huān jīn xī,qǐng zòu míng qín guǎng líng kè.", "yuè zhào chéng tóu wū bàn fēi,shuāng qī wàn shù fēng rù yī.", "tóng lú huá zhú zhú zēng huī,chū dàn lù shuǐ hòu chǔ fēi.", "yī shēng yǐ dòng wù jiē jìng,sì zuò wú yán xīng yù xī.", "qīng huái fèng shǐ qiān yú lǐ,gǎn gào yún shān cóng cǐ shǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-261','古柏行',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["孔明庙前有老柏，柯如青铜根如石。", "霜皮溜雨四十围，黛色参天二千尺。", "君臣已与时际会，树木犹为人爱惜。", "云来气接巫峡长，月出寒通雪山白。", "忆昨路绕锦亭东，先主武侯同閟宫。", "崔嵬枝干郊原古，窈窕丹青户牖空。", "落落盘踞虽得地，冥冥孤高多烈风。", "扶持自是神明力，正直原因造化工。", "大厦如倾要梁栋，万牛回首丘山重。", "不露文章世已惊，未辞翦伐谁能送？", "苦心岂免容蝼蚁，香叶终经宿鸾凤。", "志士幽人莫怨嗟：古来材大难为用。"]'::jsonb,'["kǒng míng miào qián yǒu lǎo bǎi,kē rú qīng tóng gēn rú shí.", "shuāng pí liū yǔ sì shí wéi,dài sè cān tiān èr qiān chǐ.", "jūn chén yǐ yǔ shí jì huì,shù mù yóu wéi rén ài xī.", "yún lái qì jiē wū xiá zhǎng,yuè chū hán tōng xuě shān bái.", "yì zuó lù rào jǐn tíng dōng,xiān zhǔ wǔ hóu tóng bì gōng.", "cuī wéi zhī gàn jiāo yuán gǔ,yǎo tiǎo dān qīng hù yǒu kōng.", "luò luò pán jù suī dé dì,míng míng gū gāo duō liè fēng.", "fú chí zì shì shén míng lì,zhèng zhí yuán yīn zào huà gōng.", "dà shà rú qīng yào liáng dòng,wàn niú huí shǒu qiū shān zhòng.", "bù lù wén zhāng shì yǐ jīng,wèi cí jiǎn fá shuí néng sòng?", "kǔ xīn qǐ miǎn róng lóu yǐ,xiāng yè zhōng jīng sù luán fèng.", "zhì shì yōu rén mò yuàn jiē:gǔ lái cái dà nàn wèi yòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-262','观公孙大娘弟子舞剑器行',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["昔有佳人公孙氏，一舞剑器动四方。", "观者如山色沮丧，天地为之久低昂。", "霍如羿射九日落，矫如群帝骖龙翔。", "来如雷霆收震怒，罢如江海凝清光。", "绛唇珠袖两寂寞，晚有弟子传芬芳。", "临颍美人在白帝，妙舞此曲神扬扬。", "与余问答既有以，感时抚事增惋伤。", "先帝侍女八千人，公孙剑器初第一。", "五十年间似反掌，风尘澒洞昏王室。", "梨园弟子散如烟，女乐余姿映寒日。", "金粟堆南木已拱，瞿唐石城草萧瑟。", "玳筵急管曲复终，乐极哀来月东出。", "老夫不知其所往，足茧荒山转愁疾。"]'::jsonb,'["xī yǒu jiā rén gōng sūn shì,yī wǔ jiàn qì dòng sì fāng.", "guān zhě rú shān sè jǔ sàng,tiān dì wèi zhī jiǔ dī áng.", "huò rú yì shè jiǔ rì luò,jiǎo rú qún dì cān lóng xiáng.", "lái rú léi tíng shōu zhèn nù,bà rú jiāng hǎi níng qīng guāng.", "jiàng chún zhū xiù liǎng jì mò,wǎn yǒu dì zǐ chuán fēn fāng.", "lín yǐng měi rén zài bái dì,miào wǔ cǐ qū shén yáng yáng.", "yǔ yú wèn dá jì yǒu yǐ,gǎn shí fǔ shì zēng wǎn shāng.", "xiān dì shì nǚ bā qiān rén,gōng sūn jiàn qì chū dì yī.", "wǔ shí nián jiān shì fǎn zhǎng,fēng chén hòng dòng hūn wáng shì.", "lí yuán dì zǐ sàn rú yān,nǚ lè yú zī yìng hán rì.", "jīn sù duī nán mù yǐ gǒng,qú táng shí chéng cǎo xiāo sè.", "dài yán jí guǎn qū fù zhōng,lè jí āi lái yuè dōng chū.", "lǎo fū bù zhī qí suǒ wǎng,zú jiǎn huāng shān zhuǎn chóu jí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-263','寄韩谏议',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["今我不乐思岳阳，身欲奋飞病在床。", "美人娟娟隔秋水，濯足洞庭望八荒。", "鸿飞冥冥日月白，青枫叶赤天雨霜。", "玉京群帝集北斗，或骑麒麟翳凤凰。", "芙蓉旌旗烟雾落，影动倒景摇潇湘。", "星宫之君醉琼浆，羽人稀少不在旁。", "似闻昨者赤松子，恐是汉代韩张良。", "昔随刘氏定长安，帷幄未改神惨伤。", "国家成败吾岂敢，色难腥腐餐枫香。", "周南留滞古所惜，南极老人应寿昌。", "美人胡为隔秋水，焉得置之贡玉堂。"]'::jsonb,'["jīn wǒ bù lè sī yuè yáng,shēn yù fèn fēi bìng zài chuáng.", "měi rén juān juān gé qiū shuǐ,zhuó zú dòng tíng wàng bā huāng.", "hóng fēi míng míng rì yuè bái,qīng fēng yè chì tiān yǔ shuāng.", "yù jīng qún dì jí běi dǒu,huò qí qí lín yì fèng huáng.", "fú róng jīng qí yān wù luò,yǐng dòng dào jǐng yáo xiāo xiāng.", "xīng gōng zhī jūn zuì qióng jiāng,yǔ rén xī shǎo bù zài páng.", "shì wén zuó zhě chì sōng zi,kǒng shì hàn dài hán zhāng liáng.", "xī suí liú shì dìng cháng ān,wéi wò wèi gǎi shén cǎn shāng.", "guó jiā chéng bài wú qǐ gǎn,sè nán xīng fǔ cān fēng xiāng.", "zhōu nán liú zhì gǔ suǒ xī,nán jí lǎo rén yīng shòu chāng.", "měi rén hú wèi gé qiū shuǐ,yān dé zhì zhī gòng yù táng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-264','夜归鹿门山歌',NULL,'孟浩然',NULL,'唐','唐诗',FALSE,'["山寺钟鸣昼已昏，渔梁渡头争渡喧。", "人随沙岸向江村，余亦乘舟归鹿门。", "鹿门月照开烟树，忽到庞公栖隐处。", "岩扉松径长寂寥，惟有幽人自来去。"]'::jsonb,'["shān sì zhōng míng zhòu yǐ hūn,yú liáng dù tóu zhēng dù xuān.", "rén suí shā àn xiàng jiāng cūn,yú yì chéng zhōu guī lù mén.", "lù mén yuè zhào kāi yān shù,hū dào páng gōng qī yǐn chù.", "yán fēi sōng jìng zhǎng jì liáo,wéi yǒu yōu rén zì lái qù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-265','渔翁',NULL,'柳宗元',NULL,'唐','唐诗',FALSE,'["渔翁夜傍西岩宿，晓汲清湘燃楚竹。", "烟销日出不见人，欸乃一声山水绿。", "回看天际下中流，岩上无心云相逐。"]'::jsonb,'["yú wēng yè bàng xī yán sù,xiǎo jí qīng xiāng rán chǔ zhú.", "yān xiāo rì chū bú jiàn rén,āi nǎi yī shēng shān shuǐ lǜ.", "huí kàn tiān jì xià zhōng liú,yán shàng wú xīn yún xiāng zhú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-266','登幽州台歌',NULL,'陈子昂',NULL,'唐','唐诗',FALSE,'["前不见古人，后不见来者。", "念天地之悠悠，独怆然而涕下。"]'::jsonb,'["qián bú jiàn gǔ rén,hòu bú jiàn lái zhě.", "niàn tiān dì zhī yōu yōu,dú chuàng rán ér tì xià."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-267','山石',NULL,'韩愈',NULL,'唐','唐诗',FALSE,'["山石荦确行径微，黄昏到寺蝙蝠飞。", "升堂坐阶新雨足，芭蕉叶大栀子肥。", "僧言古壁佛画好，以火来照所见稀。", "铺床拂席置羹饭，疏粝亦足饱我饥。", "夜深静卧百虫绝，清月出岭光入扉。", "天明独去无道路，出入高下穷烟霏。", "山红涧碧纷烂漫，时见松枥皆十围。", "当流赤足踏涧石，水声激激风吹衣。", "人生如此自可乐，岂必局束为人鞿？", "嗟哉吾党二三子，安得至老不更归。"]'::jsonb,'["shān shí luò què xíng jìng wēi,huáng hūn dào sì biān fú fēi.", "shēng táng zuò jiē xīn yǔ zú,bā jiāo yè dà zhī zi féi.", "sēng yán gǔ bì fú huà hǎo,yǐ huǒ lái zhào suǒ jiàn xī.", "pū chuáng fú xí zhì gēng fàn,shū lì yì zú bǎo wǒ jī.", "yè shēn jìng wò bǎi chóng jué,qīng yuè chū lǐng guāng rù fēi.", "tiān míng dú qù wú dào lù,chū rù gāo xià qióng yān fēi.", "shān hóng jiàn bì fēn làn màn,shí jiàn sōng lì jiē shí wéi.", "dāng liú chì zú tà jiàn shí,shuǐ shēng jī jī fēng chuī yī.", "rén shēng rú cǐ zì kě lè,qǐ bì jú shù wéi rén jī?", "jiē zāi wú dǎng èr sān zi,ān dé zhì lǎo bù gèng guī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'七言古诗'),
('base-268','凉州词',NULL,'王之涣',NULL,'唐','唐诗',FALSE,'["黄河远上白云间，一片孤城万仞山。", "羌笛何须怨杨柳，春风不度玉门关。"]'::jsonb,'["huáng hé yuǎn shàng bái yún jiān,yī piàn gū chéng wàn rèn shān.", "qiāng dí hé xū yuàn yáng liǔ,chūn fēng bù dù yù mén guān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-269','出塞·秦时明月汉时关',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["秦时明月汉时关，万里长征人未还。", "但使龙城飞将在，不教胡马度阴山。"]'::jsonb,'["qín shí míng yuè hàn shí guān,wàn lǐ cháng zhēng rén wèi hái.", "dàn shǐ lóng chéng fēi jiāng zài,bù jiào hú mǎ dù yīn shān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-270','塞上曲·蝉鸣空桑林',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["蝉鸣空桑林，八月萧关道。", "出塞入塞寒，处处黄芦草。", "从来幽并客，皆共尘沙老。", "莫学游侠儿，矜夸紫骝好。"]'::jsonb,'["chán míng kōng sāng lín,bā yuè xiāo guān dào.", "chū sài rù sāi hán,chù chù huáng lú cǎo.", "cóng lái yōu bìng kè,jiē gòng chén shā lǎo.", "mò xué yóu xiá ér,jīn kuā zǐ liú hǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-271','塞下曲·饮马渡秋水',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["饮马渡秋水，水寒风似刀。", "平沙日未没，黯黯见临洮。", "昔日长城战，咸言意气高。", "黄尘足今古，白骨乱蓬蒿。"]'::jsonb,'["yǐn mǎ dù qiū shuǐ,shuǐ hán fēng shì dāo.", "píng shā rì wèi méi,àn àn jiàn lín táo.", "xī rì cháng chéng zhàn,xián yán yì qì gāo.", "huáng chén zú jīn gǔ,bái gǔ luàn péng hāo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-272','长信怨',NULL,'王昌龄',NULL,'唐','唐诗',FALSE,'["金井梧桐秋叶黄，珠帘不卷夜来霜。", "熏笼玉枕无颜色，卧听南宫清漏长。", "高殿秋砧响夜阑，霜深犹忆御衣寒。", "银灯青琐裁缝歇，还向金城明主看。", "奉帚平明金殿开，暂将团扇共徘徊。", "玉颜不及寒鸦色，犹带昭阳日影来。", "真成薄命久寻思，梦见君王觉后疑。", "火照西宫知夜饮，分明复道奉恩时。", "长信宫中秋月明，昭阳殿下捣衣声。", "白露堂中细草迹，红罗帐里不胜情。"]'::jsonb,'["jīn jǐng wú tóng qiū yè huáng,zhū lián bù juǎn yè lái shuāng.", "xūn lóng yù zhěn wú yán sè,wò tīng nán gōng qīng lòu zhǎng.", "gāo diàn qiū zhēn xiǎng yè lán,shuāng shēn yóu yì yù yī hán.", "yín dēng qīng suǒ cái féng xiē,hái xiàng jīn chéng míng zhǔ kàn.", "fèng zhǒu píng míng jīn diàn kāi,zàn jiāng tuán shàn gòng pái huái.", "yù yán bù jí hán yā sè,yóu dài zhāo yáng rì yǐng lái.", "zhēn chéng bó mìng jiǔ xín sī,mèng jiàn jūn wáng jué hòu yí.", "huǒ zhào xī gōng zhī yè yǐn,fēn míng fù dào fèng ēn shí.", "zhǎng xìn gōng zhōng qiū yuè míng,zhāo yáng diàn xià dǎo yī shēng.", "bái lù táng zhōng xì cǎo jì,hóng luó zhàng lǐ bù shèng qíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-273','渭城曲',NULL,'王维',NULL,'唐','唐诗',FALSE,'["渭城朝雨浥轻尘，客舍青青柳色新。", "劝君更尽一杯酒，西出阳关无故人。"]'::jsonb,'["wèi chéng cháo yǔ yì qīng chén,kè shě qīng qīng liǔ sè xīn.", "quàn jūn gèng jǐn yī bēi jiǔ,xī chū yáng guān wú gù rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-274','秋夜曲',NULL,'王维',NULL,'唐','唐诗',FALSE,'["桂魄初生秋露微，轻罗已薄未更衣。", "银筝夜久殷勤弄，心怯空房不忍归。"]'::jsonb,'["guì pò chū shēng qiū lù wēi,qīng luó yǐ báo wèi gēng yī.", "yín zhēng yè jiǔ yīn qín nòng,xīn qiè kòng fáng bù rěn guī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-275','洛阳女儿行',NULL,'王维',NULL,'唐','唐诗',FALSE,'["洛阳女儿对门居，才可颜容十五余。", "良人玉勒乘骢马，侍女金盘脍鲤鱼。", "画阁朱楼尽相望，红桃绿柳垂檐向。", "罗帷送上七香车，宝扇迎归九华帐。", "狂夫富贵在青春，意气骄奢剧季伦。", "自怜碧玉亲教舞，不惜珊瑚持与人。", "春窗曙灭九微火，九微片片飞花琐。", "戏罢曾无理曲时，妆成祗是薰香坐。", "城中相识尽繁华，日夜经过赵李家。", "谁怜越女颜如玉，贫贱江头自浣纱。"]'::jsonb,'["luò yáng nǚ ér duì mén jū,cái kě yán róng shí wǔ yú.", "liáng rén yù lēi chéng cōng mǎ,shì nǚ jīn pán kuài lǐ yú.", "huà gé zhū lóu jǐn xiāng wàng,hóng táo lǜ liǔ chuí yán xiàng.", "luó wéi sòng shàng qī xiāng chē,bǎo shàn yíng guī jiǔ huá zhàng.", "kuáng fū fù guì zài qīng chūn,yì qì jiāo shē jù jì lún.", "zì lián bì yù qīn jiào wǔ,bù xī shān hú chí yǔ rén.", "chūn chuāng shǔ miè jiǔ wēi huǒ,jiǔ wēi piàn piàn fēi huā suǒ.", "xì bà céng wú lǐ qū shí,zhuāng chéng zhī shì xūn xiāng zuò.", "chéng zhōng xiāng shí jǐn fán huá,rì yè jīng guò zhào lǐ jiā.", "shuí lián yuè nǚ yán rú yù,pín jiàn jiāng tóu zì huàn shā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-276','清平调·云想衣裳花想容',NULL,'李白',NULL,'唐','唐诗',FALSE,'["云想衣裳花想容，春风拂槛露华浓。", "若非群玉山头见，会向瑶台月下逢。"]'::jsonb,'["yún xiǎng yī shang huā xiǎng róng,chūn fēng fú kǎn lù huá nóng.", "ruò fēi qún yù shān tóu jiàn,huì xiàng yáo tái yuè xià féng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-277','清平调·一枝红艳露凝香',NULL,'李白',NULL,'唐','唐诗',FALSE,'["一枝红艳露凝香，云雨巫山枉断肠。", "借问汉宫谁得似，可怜飞燕倚新妆。"]'::jsonb,'["yī zhī hóng yàn lù níng xiāng,yún yǔ wū shān wǎng duàn cháng.", "jiè wèn hàn gōng shuí dé shì,kě lián fēi yàn yǐ xīn zhuāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-278','清平调·名花倾国两相欢',NULL,'李白',NULL,'唐','唐诗',FALSE,'["名花倾国两相欢，常得君王带笑看。", "解释春风无限恨，沉香亭北倚栏杆。"]'::jsonb,'["míng huā qīng guó liǎng xiāng huān,cháng dé jūn wáng dài xiào kàn.", "jiě shì chūn fēng wú xiàn hèn,chén xiāng tíng běi yǐ lán gān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-279','行路难·金樽清酒斗十千',NULL,'李白',NULL,'唐','唐诗',FALSE,'["金樽清酒斗十千，玉盘珍羞直万钱。", "停杯投箸不能食，拔剑四顾心茫然。", "欲渡黄河冰塞川，将登太行雪满山。", "闲来垂钓碧溪上，忽复乘舟梦日边。", "行路难！行路难！多歧路，今安在？", "长风破浪会有时，直挂云帆济沧海。"]'::jsonb,'["jīn zūn qīng jiǔ dòu shí qiān,yù pán zhēn xiū zhí wàn qián.", "tíng bēi tóu zhù bù néng shí,bá jiàn sì gù xīn máng rán.", "yù dù huáng hé bīng sāi chuān,jiāng dēng tài xíng xuě mǎn shān.", "xián lái chuí diào bì xī shàng,hū fù chéng zhōu mèng rì biān.", "xíng lù nán!xíng lù nán!duō qí lù,jīn ān zài?", "cháng fēng pò làng huì yǒu shí,zhí guà yún fān jì cāng hǎi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-280','行路难·大道如青天',NULL,'李白',NULL,'唐','唐诗',FALSE,'["大道如青天，我独不得出。", "羞逐长安社中儿，赤鸡白雉赌梨栗。", "弹剑作歌奏苦声，曳裾王门不称情。", "淮阴市井笑韩信，汉朝公卿忌贾生。", "君不见昔时燕家重郭隗，拥篲折节无嫌猜。", "剧辛乐毅感恩分，输肝剖胆效英才。", "昭王白骨萦蔓草，谁人更扫黄金台？", "行路难，归去来！"]'::jsonb,'["dà dào rú qīng tiān,wǒ dú bù dé chū.", "xiū zhú cháng ān shè zhōng ér,chì jī bái zhì dǔ lí lì.", "tán jiàn zuò gē zòu kǔ shēng,yè jū wáng mén bù chēng qíng.", "huái yīn shì jǐng xiào hán xìn,hàn cháo gōng qīng jì jiǎ shēng.", "jūn bú jiàn xī shí yàn jiā zhòng guō kuí,yōng huì zhé jié wú xián cāi.", "jù xīn yuè yì gǎn ēn fēn,shū gān pōu dǎn xiào yīng cái.", "zhāo wáng bái gǔ yíng màn cǎo,shuí rén gèng sǎo huáng jīn tái?", "xíng lù nán,guī qù lái!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-281','行路难·有耳莫洗颍川水',NULL,'李白',NULL,'唐','唐诗',FALSE,'["有耳莫洗颍川水，有口莫食首阳蕨。", "含光混世贵无名，何用孤高比云月？", "吾观自古贤达人，功成不退皆殒身。", "子胥既弃吴江上，屈原终投湘水滨。", "陆机雄才岂自保？李斯税驾苦不早。", "华亭鹤唳讵可闻？上蔡苍鹰何足道？", "君不见吴中张翰称达生，秋风忽忆江东行。", "且乐生前一杯酒，何须身后千载名？"]'::jsonb,'["yǒu ěr mò xǐ yǐng chuān shuǐ,yǒu kǒu mò shí shǒu yáng jué.", "hán guāng hùn shì guì wú míng,hé yòng gū gāo bǐ yún yuè?", "wú guān zì gǔ xián dá rén,gōng chéng bù tuì jiē yǔn shēn.", "zi xū jì qì wú jiāng shàng,qū yuán zhōng tóu xiāng shuǐ bīn.", "lù jī xióng cái qǐ zì bǎo?lǐ sī shuì jià kǔ bù zǎo.", "huà tíng hè lì jù kě wén?shàng cài cāng yīng hé zú dào?", "jūn bú jiàn wú zhōng zhāng hàn chēng dá shēng,qiū fēng hū yì jiāng dōng xíng.", "qiě lè shēng qián yī bēi jiǔ,hé xū shēn hòu qiān zài míng?"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-282','将进酒',NULL,'李白',NULL,'唐','唐诗',FALSE,'["君不见，黄河之水天上来，奔流到海不复回。", "君不见，高堂明镜悲白发，朝如青丝暮成雪。", "人生得意须尽欢，莫使金樽空对月。", "天生我材必有用，千金散尽还复来。", "烹羊宰牛且为乐，会须一饮三百杯。", "岑夫子，丹丘生，将进酒，杯莫停。", "与君歌一曲，请君为我倾耳听。", "钟鼓馔玉不足贵，但愿长醉不复醒。", "古来圣贤皆寂寞，惟有饮者留其名。", "陈王昔时宴平乐，斗酒十千恣欢谑。", "主人何为言少钱，径须沽取对君酌。", "五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"]'::jsonb,'["jūn bú jiàn,huáng hé zhī shuǐ tiān shàng lái,bēn liú dào hǎi bù fù huí.", "jūn bú jiàn,gāo táng míng jìng bēi bái fà,cháo rú qīng sī mù chéng xuě.", "rén shēng dé yì xū jìn huān,mò shǐ jīn zūn kōng duì yuè.", "tiān shēng wǒ cái bì yǒu yòng,qiān jīn sàn jǐn hái fù lái.", "pēng yáng zǎi niú qiě wèi lè,huì xū yī yǐn sān bǎi bēi.", "cén fū zǐ,dān qiū shēng,qiāng jìn jiǔ,bēi mò tíng.", "yǔ jūn gē yī qū,qǐng jūn wèi wǒ qīng ěr tīng.", "zhōng gǔ zhuàn yù bù zú guì,dàn yuàn zhǎng zuì bù fù xǐng.", "gǔ lái shèng xián jiē jì mò,wéi yǒu yǐn zhě liú qí míng.", "chén wáng xī shí yàn píng lè,dòu jiǔ shí qiān zì huān xuè.", "zhǔ rén hé wèi yán shǎo qián,jìng xū gū qǔ duì jūn zhuó.", "wǔ huā mǎ,qiān jīn qiú,hū ér jiāng chū huàn měi jiǔ,yǔ ěr tóng xiāo wàn gǔ chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-283','玉阶怨',NULL,'李白',NULL,'唐','唐诗',FALSE,'["玉阶生白露，夜久侵罗袜。", "却下水晶帘，玲珑望秋月。"]'::jsonb,'["yù jiē shēng bái lù,yè jiǔ qīn luó wà.", "què xià shuǐ jīng lián,líng lóng wàng qiū yuè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-284','长相思·其一',NULL,'李白',NULL,'唐','唐诗',FALSE,'["长相思，在长安。", "络纬秋啼金井阑，微霜凄凄簟色寒。", "孤灯不明思欲绝，卷帷望月空长叹。", "美人如花隔云端！", "上有青冥之长天，下有渌水之波澜。", "天长路远魂飞苦，梦魂不到关山难。", "长相思，摧心肝！"]'::jsonb,'["zhǎng xiàng sī,zài cháng ān.", "luò wěi qiū tí jīn jǐng lán,wēi shuāng qī qī diàn sè hán.", "gū dēng bù míng sī yù jué,juǎn wéi wàng yuè kōng cháng tàn.", "měi rén rú huā gé yún duān!", "shàng yǒu qīng míng zhī cháng tiān,xià yǒu lù shuǐ zhī bō lán.", "tiān zhǎng lù yuǎn hún fēi kǔ,mèng hún bú dào guān shān nán.", "zhǎng xiàng sī,cuī xīn gān!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-285','长相思·其二',NULL,'李白',NULL,'唐','唐诗',FALSE,'["日色欲尽花含烟，月明欲素愁不眠。", "赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。", "此曲有意无人传，愿随春风寄燕然。", "忆君迢迢隔青天，昔日横波目，今作流泪泉。", "不信妾断肠，归来看取明镜前。"]'::jsonb,'["rì sè yù jǐn huā hán yān,yuè míng yù sù chóu bù mián.", "zhào sè chū tíng fèng huáng zhù,shǔ qín yù zòu yuān yāng xián.", "cǐ qū yǒu yì wú rén chuán,yuàn suí chūn fēng jì yàn rán.", "yì jūn tiáo tiáo gé qīng tiān,xī rì héng bō mù,jīn zuò liú lèi quán.", "bù xìn qiè duàn cháng,guī lái kàn qǔ míng jìng qián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-286','长干行·其一',NULL,'李白',NULL,'唐','唐诗',FALSE,'["妾发初覆额，折花门前剧。", "郎骑竹马来，绕床弄青梅。", "同居长干里，两小无嫌猜，", "十四为君妇，羞颜未尝开。", "低头向暗壁，千唤不一回。", "十五始展眉，愿同尘与灰。", "常存抱柱信，岂上望夫台。", "十六君远行，瞿塘滟滪堆。", "五月不可触，猿声天上哀。(猿", "一作：鸣)", "门前迟行迹，一一生绿苔。", "苔深不能扫，落叶秋风早。", "八月蝴蝶来，双飞西园草。", "感此伤妾心，坐愁红颜老。", "早晚下三巴，预将书报家。", "相迎不道远，直至长风沙。"]'::jsonb,'["qiè fā chū fù é,zhé huā mén qián jù.", "láng qí zhú mǎ lái,rào chuáng nòng qīng méi.", "tóng jū zhǎng gàn lǐ,liǎng xiǎo wú xián cāi,", "shí sì wèi jūn fù,xiū yán wèi cháng kāi.", "dī tóu xiàng àn bì,qiān huàn bù yī huí.", "shí wǔ shǐ zhǎn méi,yuàn tóng chén yǔ huī.", "cháng cún bào zhù xìn,qǐ shàng wàng fū tái.", "shí liù jūn yuǎn xíng,qú táng yàn yù duī.", "wǔ yuè bù kě chù,yuán shēng tiān shàng āi.( yuán", "yī zuò:míng )", "mén qián chí xíng jì,yī yī shēng lǜ tái.", "tái shēn bù néng sǎo,luò yè qiū fēng zǎo.", "bā yuè hú dié lái,shuāng fēi xī yuán cǎo.", "gǎn cǐ shāng qiè xīn,zuò chóu hóng yán lǎo.", "zǎo wǎn xià sān bā,yù jiāng shū bào jiā.", "xiāng yíng bù dào yuǎn,zhí zhì zhǎng fēng shā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-287','子夜吴歌·春歌',NULL,'李白',NULL,'唐','唐诗',FALSE,'["秦地罗敷女，采桑绿水边。", "素手青条上，红妆白日鲜。", "蚕饥妾欲去，五马莫留连。"]'::jsonb,'["qín dì luó fū nǚ,cǎi sāng lǜ shuǐ biān.", "sù shǒu qīng tiáo shàng,hóng zhuāng bái rì xiān.", "cán jī qiè yù qù,wǔ mǎ mò liú lián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-288','子夜吴歌·夏歌',NULL,'李白',NULL,'唐','唐诗',FALSE,'["镜湖三百里，菡萏发荷花。", "五月西施采，人看隘若耶。", "回舟不待月，归去越王家。"]'::jsonb,'["jìng hú sān bǎi lǐ,hàn dàn fā hé huā.", "wǔ yuè xī shī cǎi,rén kàn ài ruò yé.", "huí zhōu bù dài yuè,guī qù yuè wáng jiā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-289','子夜吴歌·秋歌',NULL,'李白',NULL,'唐','唐诗',FALSE,'["长安一片月，万户捣衣声。", "秋风吹不尽，总是玉关情。", "何日平胡虏，良人罢远征。"]'::jsonb,'["cháng ān yī piàn yuè,wàn hù dǎo yī shēng.", "qiū fēng chuī bù jìn,zǒng shì yù guān qíng.", "hé rì píng hú lǔ,liáng rén bà yuǎn zhēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-290','子夜吴歌·冬歌',NULL,'李白',NULL,'唐','唐诗',FALSE,'["明朝驿使发，一夜絮征袍。", "素手抽针冷，那堪把剪刀。", "裁缝寄远道，几日到临洮。"]'::jsonb,'["míng cháo yì shǐ fā,yī yè xù zhēng páo.", "sù shǒu chōu zhēn lěng,nà kān bǎ jiǎn dāo.", "cái féng jì yuǎn dào,jǐ rì dào lín táo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-291','关山月',NULL,'李白',NULL,'唐','唐诗',FALSE,'["明月出天山，苍茫云海间。", "长风几万里，吹度玉门关。", "汉下白登道，胡窥青海湾。", "由来征战地，不见有人还。", "戍客望边邑，思归多苦颜。", "高楼当此夜，叹息未应闲。"]'::jsonb,'["míng yuè chū tiān shān,cāng máng yún hǎi jiān.", "zhǎng fēng jǐ wàn lǐ,chuī dù yù mén guān.", "hàn xià bái dēng dào,hú kuī qīng hǎi wān.", "yóu lái zhēng zhàn dì,bú jiàn yǒu rén hái.", "shù kè wàng biān yì,sī guī duō kǔ yán.", "gāo lóu dāng cǐ yè,tàn xī wèi yīng xián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-292','江南曲',NULL,'李益',NULL,'唐','唐诗',FALSE,'["嫁得瞿塘贾，朝朝误妾期。", "早知潮有信，嫁与弄潮儿。"]'::jsonb,'["jià dé qú táng jiǎ,cháo cháo wù qiè qī.", "zǎo zhī cháo yǒu xìn,jià yǔ nòng cháo ér."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-293','古从军行',NULL,'李颀',NULL,'唐','唐诗',FALSE,'["白日登山望烽火，黄昏饮马傍交河。", "行人刁斗风沙暗，公主琵琶幽怨多。", "野云万里无城郭，雨雪纷纷连大漠。", "胡雁哀鸣夜夜飞，胡儿眼泪双双落。", "闻道玉门犹被遮，应将性命逐轻车。", "年年战骨埋荒外，空见蒲桃入汉家。"]'::jsonb,'["bái rì dēng shān wàng fēng huǒ,huáng hūn yǐn mǎ bàng jiāo hé.", "xíng rén diāo dòu fēng shā àn,gōng zhǔ pí pá yōu yuàn duō.", "yě yún wàn lǐ wú chéng guō,yǔ xuě fēn fēn lián dà mò.", "hú yàn āi míng yè yè fēi,hú ér yǎn lèi shuāng shuāng luò.", "wén dào yù mén yóu bèi zhē,yīng jiāng xìng mìng zhú qīng chē.", "nián nián zhàn gǔ mái huāng wài,kōng jiàn pú táo rù hàn jiā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-294','丽人行',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["三月三日天气新，长安水边多丽人。", "态浓意远淑且真，肌理细腻骨肉匀。", "绣罗衣裳照暮春，蹙金孔雀银麒麟。", "头上何所有？翠微盍叶垂鬓唇。", "背后何所见？珠压腰衱稳称身。", "就中云幕椒房亲，赐名大国虢与秦。", "紫驼之峰出翠釜，水精之盘行素鳞。", "犀箸厌饫久未下，鸾刀缕切空纷纶。", "黄门飞鞚不动尘，御厨络绎送八珍。", "箫鼓哀吟感鬼神，宾从杂遝实要津。", "后来鞍马何逡巡，当轩下马入锦茵。", "杨花雪落覆白苹，青鸟飞去衔红巾。", "炙手可热势绝伦，慎莫近前丞相嗔！"]'::jsonb,'["sān yuè sān rì tiān qì xīn,cháng ān shuǐ biān duō lì rén.", "tài nóng yì yuǎn shū qiě zhēn,jī lǐ xì nì gǔ ròu yún.", "xiù luó yī shang zhào mù chūn,cù jīn kǒng què yín qí lín.", "tóu shàng hé suǒ yǒu?cuì wēi hé yè chuí bìn chún.", "bèi hòu hé suǒ jiàn?zhū yā yāo jié wěn chèn shēn.", "jiù zhōng yún mù jiāo fáng qīn,cì míng dà guó guó yǔ qín.", "zǐ tuó zhī fēng chū cuì fǔ,shuǐ jīng zhī pán xíng sù lín.", "xī zhù yàn yù jiǔ wèi xià,luán dāo lǚ qiè kōng fēn lún.", "huáng mén fēi kòng bù dòng chén,yù chú luò yì sòng bā zhēn.", "xiāo gǔ āi yín gǎn guǐ shén,bīn cóng zá tà shí yào jīn.", "hòu lái ān mǎ hé qūn xún,dāng xuān xià mǎ rù jǐn yīn.", "yáng huā xuě luò fù bái píng,qīng niǎo fēi qù xián hóng jīn.", "zhì shǒu kě rè shì jué lún,shèn mò jìn qián chéng xiàng chēn!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-295','哀江头',NULL,'杜甫',NULL,'唐','唐诗',FALSE,'["少陵野老吞声哭，春日潜行曲江曲。", "江头宫殿锁千门，细柳新蒲为谁绿？", "忆昔霓旌下南苑，苑中万物生颜色。", "昭阳殿里第一人，同辇随君侍君侧。", "辇前才人带弓箭，白马嚼啮黄金勒。", "翻身向天仰射云，一笑正坠双飞翼。", "明眸皓齿今何在？血污游魂归不得。", "清渭东流剑阁深，去住彼此无消息。", "人生有情泪沾臆，江水江花岂终极！", "黄昏胡骑尘满城，欲往城南望城北。"]'::jsonb,'["shǎo líng yě lǎo tūn shēng kū,chūn rì qián xíng qǔ jiāng qū.", "jiāng tóu gōng diàn suǒ qiān mén,xì liǔ xīn pú wèi shuí lǜ?", "yì xī ní jīng xià nán yuàn,yuàn zhōng wàn wù shēng yán sè.", "zhāo yáng diàn lǐ dì yī rén,tóng niǎn suí jūn shì jūn cè.", "niǎn qián cái rén dài gōng jiàn,bái mǎ jué niè huáng jīn lēi.", "fān shēn xiàng tiān yǎng shè yún,yī xiào zhèng zhuì shuāng fēi yì.", "míng móu hào chǐ jīn hé zài?xuè wū yóu hún guī bù dé.", "qīng wèi dōng liú jiàn gé shēn,qù zhù bǐ cǐ wú xiāo xī.", "rén shēng yǒu qíng lèi zhān yì,jiāng shuǐ jiāng huā qǐ zhōng jí!", "huáng hūn hú qí chén mǎn chéng,yù wǎng chéng nán wàng chéng běi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-296','金缕衣',NULL,'佚名',NULL,'唐','唐诗',FALSE,'["劝君莫惜金缕衣，劝君惜取少年时。", "花开堪折直须折，莫待无花空折枝。"]'::jsonb,'["quàn jūn mò xī jīn lǚ yī,quàn jūn xī qǔ shào nián shí.", "huā kāi kān zhé zhí xū zhé,mò dài wú huā kōng zhé zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-297','独不见',NULL,'沈佺期',NULL,'唐','唐诗',FALSE,'["卢家少妇郁金堂，海燕双栖玳瑁梁。", "九月寒砧催木叶，十年征戍忆辽阳。", "白狼河北音书断，丹凤城南秋夜长。", "谁谓含愁独不见，更教明月照流黄。"]'::jsonb,'["lú jiā shào fù yù jīn táng,hǎi yàn shuāng qī dài mào liáng.", "jiǔ yuè hán zhēn cuī mù yè,shí nián zhēng shù yì liáo yáng.", "bái láng hé běi yīn shū duàn,dān fèng chéng nán qiū yè zhǎng.", "shuí wèi hán chóu dú bú jiàn,gèng jiào míng yuè zhào liú huáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-298','烈女操',NULL,'孟郊',NULL,'唐','唐诗',FALSE,'["梧桐相待老，鸳鸯会双死。", "贞女贵殉夫，舍生亦如此。", "波澜誓不起，妾心古井水。"]'::jsonb,'["wú tóng xiāng dài lǎo,yuān yāng huì shuāng sǐ.", "zhēn nǚ guì xùn fū,shě shēng yì rú cǐ.", "bō lán shì bù qǐ,qiè xīn gǔ jǐng shuǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-299','游子吟',NULL,'孟郊',NULL,'唐','唐诗',FALSE,'["慈母手中线，游子身上衣。", "临行密密缝，意恐迟迟归。", "谁言寸草心，报得三春晖。"]'::jsonb,'["cí mǔ shǒu zhōng xiàn,yóu zi shēn shàng yī.", "lín xíng mì mì fèng,yì kǒng chí chí guī.", "shuí yán cùn cǎo xīn,bào dé sān chūn huī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-300','长干行·君家何处住',NULL,'崔颢',NULL,'唐','唐诗',FALSE,'["君家何处住，妾住在横塘。", "停船暂借问，或恐是同乡。"]'::jsonb,'["jūn jiā hé chù zhù,qiè zhù zài héng táng.", "tíng chuán zàn jiè wèn,huò kǒng shì tóng xiāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-301','长干行·家临九江水',NULL,'崔颢',NULL,'唐','唐诗',FALSE,'["家临九江水，来去九江侧。", "同是长干人，生小不相识。"]'::jsonb,'["jiā lín jiǔ jiāng shuǐ,lái qù jiǔ jiāng cè.", "tóng shì zhǎng gàn rén,shēng xiǎo bù xiāng shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-302','塞下曲·鹫翎金仆姑',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["鹫翎金仆姑，燕尾绣蝥弧。", "独立扬新令，千营共一呼。"]'::jsonb,'["jiù líng jīn pū gū,yàn wěi xiù máo hú.", "dú lì yáng xīn lìng,qiān yíng gòng yī hū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-303','塞下曲·林暗草惊风',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["林暗草惊风，将军夜引弓。", "平明寻白羽，没在石棱中。"]'::jsonb,'["lín àn cǎo jīng fēng,jiāng jūn yè yǐn gōng.", "píng míng xún bái yǔ,méi zài shí léng zhōng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-304','塞下曲·月黑雁飞高',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["月黑雁飞高，单于夜遁逃。", "欲将轻骑逐，大雪满弓刀。"]'::jsonb,'["yuè hēi yàn fēi gāo,chán yú yè dùn táo.", "yù jiāng qīng qí zhú,dà xuě mǎn gōng dāo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-305','塞下曲·野幕敞琼筵',NULL,'卢纶',NULL,'唐','唐诗',FALSE,'["野幕敞琼筵，羌戎贺劳旋。", "醉和金甲舞，雷鼓动山川。"]'::jsonb,'["yě mù chǎng qióng yán,qiāng róng hè láo xuán.", "zuì hé jīn jiǎ wǔ,léi gǔ dòng shān chuān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'乐府'),
('base-306','水调歌头',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["明月几时有，把酒问青天。", "不知天上宫阙，今夕是何年。", "我欲乘风归去，又恐琼楼玉宇，高处不胜寒。", "起舞弄清影，何似在人间。", "转朱阁，低绮户，照无眠。", "不应有恨，何事长向别时圆。", "人有悲欢离合，月有阴晴圆缺，此事古难全。", "但愿人长久，千里共婵娟。"]'::jsonb,'["míng yuè jǐ shí yǒu,bǎ jiǔ wèn qīng tiān.", "bù zhī tiān shàng gōng què,jīn xī shì hé nián.", "wǒ yù chéng fēng guī qù,yòu kǒng qióng lóu yù yǔ,gāo chù bù shèng hán.", "qǐ wǔ nòng qīng yǐng,hé shì zài rén jiān.", "zhuǎn zhū gé,dī qǐ hù,zhào wú mián.", "bù yīng yǒu hèn,hé shì zhǎng xiàng bié shí yuán.", "rén yǒu bēi huān lí hé,yuè yǒu yīn qíng yuán quē,cǐ shì gǔ nán quán.", "dàn yuàn rén cháng jiǔ,qiān lǐ gòng chán juān."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-307','念奴娇',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["大江东去，浪淘尽、千古风流人物。", "故垒西边人道是，三国周郎赤壁。", "乱石穿空，惊涛拍岸，卷起千堆雪。", "江山如画，一时多少豪杰。", "遥想公瑾当年，小乔初嫁了，雄姿英发。", "羽扇纶巾谈笑间，强虏灰飞烟灭。", "故国神游，多情应笑，我早生华发。", "人间如梦，一尊还酹江月。"]'::jsonb,'["dà jiāng dōng qù,làng táo jǐn,qiān gǔ fēng liú rén wù.", "gù lěi xī biān rén dào shì,sān guó zhōu láng chì bì.", "luàn shí chuān kōng,jīng tāo pāi àn,juǎn qǐ qiān duī xuě.", "jiāng shān rú huà,yī shí duō shǎo háo jié.", "yáo xiǎng gōng jǐn dāng nián,xiǎo qiáo chū jià le,xióng zī yīng fā.", "yǔ shàn guān jīn tán xiào jiān,qiáng lǔ huī fēi yān miè.", "gù guó shén yóu,duō qíng yīng xiào,wǒ zǎo shēng huá fà.", "rén jiān rú mèng,yī zūn hái lèi jiāng yuè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-308','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["莫听穿林打叶声。", "何妨吟啸且徐行。", "竹杖芒鞋轻胜马。", "谁怕。", "一蓑烟雨任平生。", "料峭春风吹酒醒。", "微冷。", "山头斜照却相迎。", "回首向来潇洒处。", "归去。", "也无风雨也无晴。"]'::jsonb,'["mò tīng chuān lín dǎ yè shēng.", "hé fáng yín xiào qiě xú xíng.", "zhú zhàng máng xié qīng shèng mǎ.", "shuí pà.", "yī suō yān yǔ rèn píng shēng.", "liào qiào chūn fēng chuī jiǔ xǐng.", "wēi lěng.", "shān tóu xié zhào què xiāng yíng.", "huí shǒu xiàng lái xiāo sǎ chù.", "guī qù.", "yě wú fēng yǔ yě wú qíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-309','江神子・江城子',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["十年生死两茫茫。", "不思量。", "自难忘。", "千里孤坟，无处话凄凉。", "纵使相逢应不识，尘满面，鬓如霜。", "夜来幽梦忽还乡。", "小轩窗。", "正梳妆。", "相顾无言，惟有泪千行。", "料得年年断肠处，明月夜，短松冈。"]'::jsonb,'["shí nián shēng sǐ liǎng máng máng.", "bù sī liáng.", "zì nán wàng.", "qiān lǐ gū fén,wú chǔ huà qī liáng.", "zòng shǐ xiāng féng yīng bù shí,chén mǎn miàn,bìn rú shuāng.", "yè lái yōu mèng hū huán xiāng.", "xiǎo xuān chuāng.", "zhèng shū zhuāng.", "xiāng gù wú yán,wéi yǒu lèi qiān xíng.", "liào dé nián nián duàn cháng chù,míng yuè yè,duǎn sōng gāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-310','如梦令',NULL,'李清照',NULL,'宋','宋词',FALSE,'["常记溪亭日暮。", "沈醉不知归路。", "兴尽晚回舟，误入藕花深处。", "争渡。", "争渡。", "惊起一滩鸥鹭。"]'::jsonb,'["cháng jì xī tíng rì mù.", "shěn zuì bù zhī guī lù.", "xīng jǐn wǎn huí zhōu,wù rù ǒu huā shēn chù.", "zhēng dù.", "zhēng dù.", "jīng qǐ yī tān ōu lù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-311','如梦令',NULL,'李清照',NULL,'宋','宋词',FALSE,'["昨夜雨疏风骤。", "浓睡不消残酒。", "试问卷帘人，却道海棠依旧。", "知否。", "知否。", "应是绿肥红瘦。"]'::jsonb,'["zuó yè yǔ shū fēng zhòu.", "nóng shuì bù xiāo cán jiǔ.", "shì wèn juàn lián rén,què dào hǎi táng yī jiù.", "zhī fǒu.", "zhī fǒu.", "yīng shì lǜ féi hóng shòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-312','声声慢',NULL,'李清照',NULL,'宋','宋词',FALSE,'["寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", "乍暖还寒时候，最难将息。", "三杯两盏淡酒，怎敌他、晚来风急。", "雁过也，正伤心，却是旧时相识。", "满地黄花堆积。", "憔悴损，如今有谁忺摘。", "守著窗儿，独自怎生得黑。", "梧桐更兼细雨，到黄昏、点点滴滴。", "这次第，怎一个、愁字了得。"]'::jsonb,'["xún xún mì mì,lěng lěng qīng qīng,qī qī cǎn cǎn qī qī.", "zhà nuǎn huán hán shí hòu,zuì nán jiāng xī.", "sān bēi liǎng zhǎn dàn jiǔ,zěn dí tā,wǎn lái fēng jí.", "yàn guò yě,zhèng shāng xīn,què shì jiù shí xiāng shí.", "mǎn dì huáng huā duī jī.", "qiáo cuì sǔn,rú jīn yǒu shuí xiān zhāi.", "shǒu zhù chuāng ér,dú zì zěn shēng dé hēi.", "wú tóng gèng jiān xì yǔ,dào huáng hūn,diǎn diǎn dī dī.", "zhè cì dì,zěn yí gè,chóu zì liǎo de."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-313','醉花阴',NULL,'李清照',NULL,'宋','宋词',FALSE,'["薄雾浓云愁永昼。", "瑞脑消金兽。", "佳节又重阳，玉枕纱厨，半夜凉初透。", "东篱把洒黄昏后，有暗香盈袖。", "莫道不消魂，帘卷西风，人似黄花瘦。"]'::jsonb,'["bó wù nóng yún chóu yǒng zhòu.", "ruì nǎo xiāo jīn shòu.", "jiā jié yòu chóng yáng,yù zhěn shā chú,bàn yè liáng chū tòu.", "dōng lí bǎ sǎ huáng hūn hòu,yǒu àn xiāng yíng xiù.", "mò dào bù xiāo hún,lián juǎn xī fēng,rén shì huáng huā shòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-314','西江月',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["明月别枝惊鹊，清风半夜鸣蝉。", "稻花香里说丰年。", "听取蛙声一片。", "七八个星天外，两三点雨山前。", "旧时茅店社林边。", "路转溪桥忽见。"]'::jsonb,'["míng yuè bié zhī jīng què,qīng fēng bàn yè míng chán.", "dào huā xiāng lǐ shuō fēng nián.", "tīng qǔ wā shēng yī piàn.", "qī bā gè xīng tiān wài,liǎng sān diǎn yǔ shān qián.", "jiù shí máo diàn shè lín biān.", "lù zhuǎn xī qiáo hū jiàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-315','破阵子',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["醉里挑灯看剑，梦回吹角连营。", "八百里分麾下炙，五十弦翻塞外声。", "沙场秋点兵。", "马作的卢飞快，弓如霹雳弦惊。", "了却君王天下事，赢得生前身后名。", "可怜白发生。"]'::jsonb,'["zuì lǐ tiǎo dēng kàn jiàn,mèng huí chuī jiǎo lián yíng.", "bā bǎi lǐ fēn huī xià zhì,wǔ shí xián fān sài wài shēng.", "shā chǎng qiū diǎn bīng.", "mǎ zuò de lú fēi kuài,gōng rú pī lì xián jīng.", "liǎo què jūn wáng tiān xià shì,yíng dé shēng qián shēn hòu míng.", "kě lián bái fà shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-316','丑奴儿・采桑子',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["少年不识愁滋味，爱上层楼。", "爱上层楼。", "为赋新词强说愁。", "而今识尽愁滋味，欲说还休。", "欲说还休。", "却道天凉好个秋。"]'::jsonb,'["shào nián bù shí chóu zī wèi,ài shàng céng lóu.", "ài shàng céng lóu.", "wèi fù xīn cí qiáng shuō chóu.", "ér jīn shí jǐn chóu zī wèi,yù shuō hái xiū.", "yù shuō hái xiū.", "què dào tiān liáng hǎo gè qiū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-317','满江红',NULL,'岳飞',NULL,'宋','宋词',FALSE,'["怒发冲冠，凭阑处、潇潇雨歇。", "抬望眼、仰天长啸，壮怀激烈。", "三十功名尘与土，八千里路云和月。", "莫等闲、白了少年头，空悲切。", "靖康耻，犹未雪。", "臣子恨，何时灭。", "驾长车踏破，贺兰山缺。", "壮志饥餐胡虏肉，笑谈渴饮匈奴血。", "待从头、收拾旧山河，朝天阙。"]'::jsonb,'["nù fà chōng guān,píng lán chù,xiāo xiāo yǔ xiē.", "tái wàng yǎn,yǎng tiān cháng xiào,zhuàng huái jī liè.", "sān shí gōng míng chén yǔ tǔ,bā qiān lǐ lù yún hé yuè.", "mò děng xián,bái le shào nián tóu,kōng bēi qiè.", "jìng kāng chǐ,yóu wèi xuě.", "chén zi hèn,hé shí miè.", "jià zhǎng chē tà pò,hè lán shān quē.", "zhuàng zhì jī cān hú lǔ ròu,xiào tán kě yǐn xiōng nú xuè.", "dài cóng tóu,shōu shí jiù shān hé,cháo tiān quē."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-318','渔家傲',NULL,'范仲淹',NULL,'宋','宋词',FALSE,'["塞下秋来风景异。", "衡阳雁去无留意。", "四面边声连角起。", "千嶂里。", "长烟落日孤城闭。", "浊酒一杯家万里。", "燕然未勒归无计。", "羌管悠悠霜满地。", "人不寐。", "将军白发征夫泪。"]'::jsonb,'["sāi xià qiū lái fēng jǐng yì.", "héng yáng yàn qù wú liú yì.", "sì miàn biān shēng lián jiǎo qǐ.", "qiān zhàng lǐ.", "zhǎng yān luò rì gū chéng bì.", "zhuó jiǔ yī bēi jiā wàn lǐ.", "yàn rán wèi lēi guī wú jì.", "qiāng guǎn yōu yōu shuāng mǎn dì.", "rén bú mèi.", "jiāng jūn bái fà zhēng fū lèi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-319','卜算子',NULL,'陆游',NULL,'宋','宋词',FALSE,'["驿外断桥边，寂寞开无主。", "已是黄昏独自愁，更著风和雨。", "无意苦争春，一任群芳妒。", "零落成泥碾作尘，只有香如故。"]'::jsonb,'["yì wài duàn qiáo biān,jì mò kāi wú zhǔ.", "yǐ shì huáng hūn dú zì chóu,gèng zhù fēng hé yǔ.", "wú yì kǔ zhēng chūn,yī rèn qún fāng dù.", "líng luò chéng ní niǎn zuò chén,zhǐ yǒu xiāng rú gù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-320','雨霖铃',NULL,'柳永',NULL,'宋','宋词',FALSE,'["寒蝉凄切。", "对长亭晚，骤雨初歇。", "都门帐饮无绪，留恋处、兰舟催发。", "执手相看泪眼，竟无语凝噎。", "念去去、千里烟波，暮霭沈沈楚天阔。", "多情自古伤离别。", "更那堪、冷落清秋节。", "今宵酒醒何处，杨柳岸、晓风残月。", "此去经年，应是良辰、好景虚设。", "便纵有、千种风情，更与何人说。"]'::jsonb,'["hán chán qī qiè.", "duì cháng tíng wǎn,zhòu yǔ chū xiē.", "dōu mén zhàng yǐn wú xù,liú liàn chù,lán zhōu cuī fā.", "zhí shǒu xiàng kàn lèi yǎn,jìng wú yǔ níng yē.", "niàn qù qù,qiān lǐ yān bō,mù ǎi shěn shěn chǔ tiān kuò.", "duō qíng zì gǔ shāng lí bié.", "gèng nà kān,lěng luò qīng qiū jié.", "jīn xiāo jiǔ xǐng hé chù,yáng liǔ àn,xiǎo fēng cán yuè.", "cǐ qù jīng nián,yīng shì liáng chén,hǎo jǐng xū shè.", "biàn zòng yǒu,qiān zhǒng fēng qíng,gèng yǔ hé rén shuō."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-321','鹊桥仙',NULL,'秦观',NULL,'宋','宋词',FALSE,'["纤云弄巧，飞星传恨，银汉迢迢暗度。", "金风玉露一相逢，便胜却、人间无数。", "柔情似水，佳期如梦，忍顾鹊桥归路。", "两情若是长久时，又岂在、朝朝暮暮。"]'::jsonb,'["xiān yún nòng qiǎo,fēi xīng chuán hèn,yín hàn tiáo tiáo àn dù.", "jīn fēng yù lù yī xiāng féng,biàn shèng què,rén jiān wú shù.", "róu qíng shì shuǐ,jiā qī rú mèng,rěn gù què qiáo guī lù.", "liǎng qíng ruò shì cháng jiǔ shí,yòu qǐ zài,zhāo zhāo mù mù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-322','浣溪沙',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["一曲新词酒一杯。", "去年天气旧亭台。", "夕阳西下几时回。", "无可奈何花落去，似曾相识燕归来。", "小园香径独徘徊。"]'::jsonb,'["yī qū xīn cí jiǔ yī bēi.", "qù nián tiān qì jiù tíng tái.", "xī yáng xī xià jǐ shí huí.", "wú kě nài hé huā luò qù,sì céng xiāng shí yàn guī lái.", "xiǎo yuán xiāng jìng dú pái huái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-323','渔家傲',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["一曲《阳关》情几许。", "知君欲向秦川去。", "白马皂貂留不住。", "回首处。", "孤城不见天霖雾。", "到日长安花似雨。", "故关杨柳初飞絮。", "渐见靴刀迎夹路。", "谁得似。", "风流膝上王文度。"]'::jsonb,'["yī qū 《 yáng guān 》 qíng jǐ xǔ.", "zhī jūn yù xiàng qín chuān qù.", "bái mǎ zào diāo liú bú zhù.", "huí shǒu chù.", "gū chéng bú jiàn tiān lín wù.", "dào rì cháng ān huā shì yǔ.", "gù guān yáng liǔ chū fēi xù.", "jiàn jiàn xuē dāo yíng jiā lù.", "shuí dé shì.", "fēng liú xī shàng wáng wén dù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-324','苏幕遮',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["暑笼晴，风解愠。", "雨后馀清，暗袭衣裾润。", "一局选仙逃暑困。", "笑指尊前、谁向青霄近。", "整金盆，轮玉笋。", "凤驾鸾车，谁敢争先进。", "重五休言升最紧。", "纵有碧油，到了输堂印。"]'::jsonb,'["shǔ lóng qíng,fēng jiě yùn.", "yǔ hòu yú qīng,àn xí yī jū rùn.", "yī jú xuǎn xiān táo shǔ kùn.", "xiào zhǐ zūn qián,shuí xiàng qīng xiāo jìn.", "zhěng jīn pén,lún yù sǔn.", "fèng jià luán chē,shuí gǎn zhēng xiān jìn.", "zhòng wǔ xiū yán shēng zuì jǐn.", "zòng yǒu bì yóu,dào le shū táng yìn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-325','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["两两轻红半晕腮。", "依依独为使君回。", "若道使君无此意。", "何为。", "双花不向别人开。", "但看低昂烟雨里。", "不已。", "劝君休诉十分杯。", "更问尊前狂副使。", "来岁。", "花开时节与谁来。"]'::jsonb,'["liǎng liǎng qīng hóng bàn yūn sāi.", "yī yī dú wèi shǐ jūn huí.", "ruò dào shǐ jūn wú cǐ yì.", "hé wèi.", "shuāng huā bù xiàng bié rén kāi.", "dàn kàn dī áng yān yǔ lǐ.", "bù yǐ.", "quàn jūn xiū sù shí fēn bēi.", "gèng wèn zūn qián kuáng fù shǐ.", "lái suì.", "huā kāi shí jié yǔ shuí lái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-326','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["与客携壶上翠微。", "江涵秋影雁初飞。", "尘世难逢开口笑。", "年少。", "菊花须插满头归。", "酩酊但酬佳节了。", "云峤。", "登临不用怨斜晖。", "古往今来谁不老。", "多少。", "牛山何必更沾衣。"]'::jsonb,'["yǔ kè xié hú shàng cuì wēi.", "jiāng hán qiū yǐng yàn chū fēi.", "chén shì nán féng kāi kǒu xiào.", "nián shào.", "jú huā xū chā mǎn tóu guī.", "mǐng dǐng dàn chóu jiā jié le.", "yún jiào.", "dēng lín bù yòng yuàn xié huī.", "gǔ wǎng jīn lái shuí bù lǎo.", "duō shǎo.", "niú shān hé bì gèng zhān yī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-327','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["莫怪鸳鸯绣带长。", "腰轻不胜舞衣裳。", "薄幸只贪游冶去。", "何处。", "垂杨系马恣轻狂。", "花谢絮飞春又尽。", "堪恨。", "断弦尘管伴啼妆。", "不信归来但自看。", "怕见。", "为郎憔悴却羞郎。"]'::jsonb,'["mò guài yuān yāng xiù dài zhǎng.", "yāo qīng bù shèng wǔ yī shang.", "bó xìng zhǐ tān yóu yě qù.", "hé chù.", "chuí yáng xì mǎ zì qīng kuáng.", "huā xiè xù fēi chūn yòu jǐn.", "kān hèn.", "duàn xián chén guǎn bàn tí zhuāng.", "bù xìn guī lái dàn zì kàn.", "pà jiàn.", "wèi láng qiáo cuì què xiū láng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-328','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["千古风流阮步兵。", "平生游宦爱东平。", "千里远来还不住。", "归去。", "空留风韵照人清。", "红粉尊前深懊恼。", "休道。", "怎生留得许多情。", "记得明年花絮乱。", "须看。", "泛西湖是断肠声。"]'::jsonb,'["qiān gǔ fēng liú ruǎn bù bīng.", "píng shēng yóu huàn ài dōng píng.", "qiān lǐ yuǎn lái hái bú zhù.", "guī qù.", "kōng liú fēng yùn zhào rén qīng.", "hóng fěn zūn qián shēn ào nǎo.", "xiū dào.", "zěn shēng liú dé xǔ duō qíng.", "jì de míng nián huā xù luàn.", "xū kàn.", "fàn xī hú shì duàn cháng shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-329','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["雨洗娟娟嫩叶光。", "风吹细细绿筠香。", "秀色乱侵书帙晚。", "帘卷。", "清阴微过酒尊凉。", "人画竹身肥拥肿。", "何用。", "先生落笔胜萧郎。", "记得小轩岑寂夜。", "廊下。", "月和疏影上东墙。"]'::jsonb,'["yǔ xǐ juān juān nèn yè guāng.", "fēng chuī xì xì lǜ yún xiāng.", "xiù sè luàn qīn shū zhì wǎn.", "lián juǎn.", "qīng yīn wēi guò jiǔ zūn liáng.", "rén huà zhú shēn féi yōng zhǒng.", "hé yòng.", "xiān shēng luò bǐ shèng xiāo láng.", "jì de xiǎo xuān cén jì yè.", "láng xià.", "yuè hé shū yǐng shàng dōng qiáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-330','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["好睡慵开莫厌迟。", "自怜冰脸不时宜。", "偶作小红桃杏色，闲雅，尚馀孤瘦雪霜姿。", "休把闲心随物态，何事，酒生微晕沁瑶肌。", "诗老不知梅格在，吟咏，更看绿叶与青枝。"]'::jsonb,'["hǎo shuì yōng kāi mò yàn chí.", "zì lián bīng liǎn bù shí yí.", "ǒu zuò xiǎo hóng táo xìng sè,xián yǎ,shàng yú gū shòu xuě shuāng zī.", "xiū bǎ xián xīn suí wù tài,hé shì,jiǔ shēng wēi yùn qìn yáo jī.", "shī lǎo bù zhī méi gé zài,yín yǒng,gèng kàn lǜ yè yǔ qīng zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-331','定风波',NULL,'苏轼',NULL,'宋','宋词',FALSE,'["月满苕溪照夜堂。", "五星一老斗光芒。", "十五年间真梦里。", "何事。", "长庚对月独凄凉。", "绿鬓苍颜同一醉。", "还是。", "六人吟笑水云乡。", "宾主谈锋谁得似。", "看取。", "曹刘今对两苏张。"]'::jsonb,'["yuè mǎn sháo xī zhào yè táng.", "wǔ xīng yī lǎo dòu guāng máng.", "shí wǔ nián jiān zhēn mèng lǐ.", "hé shì.", "cháng gēng duì yuè dú qī liáng.", "lǜ bìn cāng yán tóng yī zuì.", "hái shì.", "liù rén yín xiào shuǐ yún xiāng.", "bīn zhǔ tán fēng shuí dé shì.", "kàn qǔ.", "cáo liú jīn duì liǎng sū zhāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-332','渔家傲',NULL,'李清照',NULL,'宋','宋词',FALSE,'["雪里已知春信至。", "寒梅点缀琼枝腻。", "香脸半开娇旖旎。", "当庭际。", "玉人浴出新妆洗。", "造化可能偏有意。", "故教明月玲珑地。", "共赏金尊沈绿蚁。", "莫辞醉。", "此花不与群花比。"]'::jsonb,'["xuě lǐ yǐ zhī chūn xìn zhì.", "hán méi diǎn zhuì qióng zhī nì.", "xiāng liǎn bàn kāi jiāo yǐ nǐ.", "dāng tíng jì.", "yù rén yù chū xīn zhuāng xǐ.", "zào huà kě néng piān yǒu yì.", "gù jiào míng yuè líng lóng dì.", "gòng shǎng jīn zūn shěn lǜ yǐ.", "mò cí zuì.", "cǐ huā bù yǔ qún huā bǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-333','渔家傲',NULL,'李清照',NULL,'宋','宋词',FALSE,'["天接云涛连晓雾。", "星河欲转千帆舞。", "彷佛梦魂归帝所。", "闻天语。", "殷勤问我归何处。", "我报路长嗟日暮。", "学诗谩有惊人句。", "九万里风鹏正举。", "风休住。", "蓬舟吹取三山去。"]'::jsonb,'["tiān jiē yún tāo lián xiǎo wù.", "xīng hé yù zhuǎn qiān fān wǔ.", "páng fó mèng hún guī dì suǒ.", "wén tiān yǔ.", "yīn qín wèn wǒ guī hé chù.", "wǒ bào lù zhǎng jiē rì mù.", "xué shī mán yǒu jīng rén jù.", "jiǔ wàn lǐ fēng péng zhèng jǔ.", "fēng xiū zhù.", "péng zhōu chuī qǔ sān shān qù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-334','蝶恋花',NULL,'李清照',NULL,'宋','宋词',FALSE,'["泪湿罗衣脂粉满。", "四叠阳关，唱到千千遍。", "人道山长山又断。", "萧萧微雨闻孤馆。", "惜别伤离方寸乱。", "忘了临行，酒盏深和浅。", "好把音书凭过雁。", "东来不似蓬莱远。"]'::jsonb,'["lèi shī luó yī zhī fěn mǎn.", "sì dié yáng guān,chàng dào qiān qiān biàn.", "rén dào shān zhǎng shān yòu duàn.", "xiāo xiāo wēi yǔ wén gū guǎn.", "xī bié shāng lí fāng cùn luàn.", "wàng le lín xíng,jiǔ zhǎn shēn hé qiǎn.", "hǎo bǎ yīn shū píng guò yàn.", "dōng lái bù shì péng lái yuǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-335','蝶恋花',NULL,'李清照',NULL,'宋','宋词',FALSE,'["暖日晴风初破冻。", "柳眼眉腮，已觉春心动。", "酒意诗情谁与共。", "泪融残粉花钿重。", "乍试夹衫金缕缝。", "山枕斜敧，枕损钗头凤。", "独抱浓愁无好梦。", "夜阑犹剪灯花弄。"]'::jsonb,'["nuǎn rì qíng fēng chū pò dòng.", "liǔ yǎn méi sāi,yǐ jué chūn xīn dòng.", "jiǔ yì shī qíng shuí yǔ gòng.", "lèi róng cán fěn huā diàn zhòng.", "zhà shì jiā shān jīn lǚ fèng.", "shān zhěn xié jī,zhěn sǔn chāi tóu fèng.", "dú bào nóng chóu wú hǎo mèng.", "yè lán yóu jiǎn dēng huā nòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-336','蝶恋花',NULL,'李清照',NULL,'宋','宋词',FALSE,'["永夜恹恹欢意少。", "空梦长安，认取长安道。", "为报今年春色好。", "花光月影宜相照。", "随意杯盘虽草草。", "酒美梅酸，恰称人怀抱。", "醉莫插花花莫笑。", "可怜春似人将老。"]'::jsonb,'["yǒng yè yān yān huān yì shǎo.", "kōng mèng cháng ān,rèn qǔ cháng ān dào.", "wèi bào jīn nián chūn sè hǎo.", "huā guāng yuè yǐng yí xiāng zhào.", "suí yì bēi pán suī cǎo cǎo.", "jiǔ měi méi suān,qià chēng rén huái bào.", "zuì mò chā huā huā mò xiào.", "kě lián chūn shì rén jiāng lǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-337','武陵春',NULL,'李清照',NULL,'宋','宋词',FALSE,'["风住尘香花已尽，日晚倦梳头。", "物是人非事事休。", "欲语泪先流。", "闻说双溪春尚好，也拟泛轻舟。", "只恐双溪舴艋舟。", "载不动、许多愁。"]'::jsonb,'["fēng zhù chén xiāng huā yǐ jǐn,rì wǎn juàn shū tóu.", "wù shì rén fēi shì shì xiū.", "yù yǔ lèi xiān liú.", "wén shuō shuāng xī chūn shàng hǎo,yě nǐ fàn qīng zhōu.", "zhǐ kǒng shuāng xī zé měng zhōu.", "zài bù dòng,xǔ duō chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-338','清平乐',NULL,'李清照',NULL,'宋','宋词',FALSE,'["年年雪里。", "常插梅花醉。", "挼尽梅花无好意。", "赢得满衣清泪。", "今年海角天涯。", "萧萧两鬓生华。", "看取晚来风势，故应难看梅花。"]'::jsonb,'["nián nián xuě lǐ.", "cháng chā méi huā zuì.", "ruá jǐn méi huā wú hǎo yì.", "yíng dé mǎn yī qīng lèi.", "jīn nián hǎi jiǎo tiān yá.", "xiāo xiāo liǎng bìn shēng huá.", "kàn qǔ wǎn lái fēng shì,gù yīng nán kàn méi huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-339','菩萨蛮',NULL,'李清照',NULL,'宋','宋词',FALSE,'["风柔日薄春犹早。", "夹衫乍著心情好。", "睡起觉微寒。", "梅花鬓上残。", "故乡何处是。", "忘了除非醉。", "沈水卧时烧。", "香消酒未消。"]'::jsonb,'["fēng róu rì báo chūn yóu zǎo.", "jiā shān zhà zhù xīn qíng hǎo.", "shuì qǐ jué wēi hán.", "méi huā bìn shàng cán.", "gù xiāng hé chù shì.", "wàng le chú fēi zuì.", "shěn shuǐ wò shí shāo.", "xiāng xiāo jiǔ wèi xiāo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-340','菩萨蛮',NULL,'李清照',NULL,'宋','宋词',FALSE,'["归鸿声断残云碧。", "背窗雪落炉烟直。", "烛底凤钗明。", "钗头人胜轻。", "角声催晓漏。", "曙色回牛斗。", "春意看花难。", "西风留旧寒。"]'::jsonb,'["guī hóng shēng duàn cán yún bì.", "bèi chuāng xuě luò lú yān zhí.", "zhú dǐ fèng chāi míng.", "chāi tóu rén shèng qīng.", "jiǎo shēng cuī xiǎo lòu.", "shǔ sè huí niú dòu.", "chūn yì kàn huā nán.", "xī fēng liú jiù hán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-341','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["山路风来草木香。", "雨馀凉意到胡床。", "泉石膏肓吾已甚。", "多病。", "堤防风月费篇章。", "孤负寻常山简醉。", "独自。", "故应知子草《玄》忙。", "湖海早知身汗漫。", "谁伴。", "只甘松竹共凄凉。"]'::jsonb,'["shān lù fēng lái cǎo mù xiāng.", "yǔ yú liáng yì dào hú chuáng.", "quán shí gāo huāng wú yǐ shèn.", "duō bìng.", "dī fáng fēng yuè fèi piān zhāng.", "gū fù xún cháng shān jiǎn zuì.", "dú zì.", "gù yīng zhī zi cǎo 《 xuán 》 máng.", "hú hǎi zǎo zhī shēn hàn màn.", "shuí bàn.", "zhǐ gān sōng zhú gòng qī liáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-342','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["少日春怀似酒浓。", "插花走马醉千锺。", "老去逢春如病酒。", "唯有。", "茶瓯香篆小帘栊。", "卷尽残花风未定。", "休恨。", "花开元自要春风。", "试问春归谁得见。", "飞燕。", "来时相遇夕阳中。"]'::jsonb,'["shǎo rì chūn huái shì jiǔ nóng.", "chā huā zǒu mǎ zuì qiān zhōng.", "lǎo qù féng chūn rú bìng jiǔ.", "wéi yǒu.", "chá ōu xiāng zhuàn xiǎo lián lóng.", "juǎn jǐn cán huā fēng wèi dìng.", "xiū hèn.", "huā kāi yuán zì yào chūn fēng.", "shì wèn chūn guī shuí dé jiàn.", "fēi yàn.", "lái shí xiāng yù xī yáng zhōng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-343','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["听我尊前醉后歌。", "人生亡奈别离何。", "但使情亲千里近。", "须信。", "无情对面是山河。", "寄语石头城下水。", "居士。", "而今浑不怕风波。", "借使未如鸥鸟惯。", "相伴。", "也应学得老渔蓑。"]'::jsonb,'["tīng wǒ zūn qián zuì hòu gē.", "rén shēng wáng nài bié lí hé.", "dàn shǐ qíng qīn qiān lǐ jìn.", "xū xìn.", "wú qíng duì miàn shì shān hé.", "jì yǔ shí tou chéng xià shuǐ.", "jū shì.", "ér jīn hún bù pà fēng bō.", "jiè shǐ wèi rú ōu niǎo guàn.", "xiāng bàn.", "yě yīng xué dé lǎo yú suō."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-344','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["仄月高寒水石乡。", "倚空青碧对禅床。", "白发自怜心似铁。", "风月。", "使君子细与平章。", "已判生涯筇竹杖。", "来往。", "却惭沙鸟笑人忙。", "便好剩留黄绢句。", "谁赋。", "银钩小草晚天凉。"]'::jsonb,'["zè yuè gāo hán shuǐ shí xiāng.", "yǐ kōng qīng bì duì chán chuáng.", "bái fà zì lián xīn shì tiě.", "fēng yuè.", "shǐ jūn zǐ xì yǔ píng zhāng.", "yǐ pàn shēng yá qióng zhú zhàng.", "lái wǎng.", "què cán shā niǎo xiào rén máng.", "biàn hǎo shèng liú huáng juàn jù.", "shuí fù.", "yín gōu xiǎo cǎo wǎn tiān liáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-345','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["昨夜山公倒载归。", "儿童应笑醉如泥。", "试与扶头浑未醒。", "休问。", "梦魂犹在葛家溪。", "千古醉乡来往路。", "知处。", "温柔东畔白云西。", "起向绿窗高处看。", "题遍。", "刘伶元自有贤妻。"]'::jsonb,'["zuó yè shān gōng dǎo zǎi guī.", "ér tóng yīng xiào zuì rú ní.", "shì yǔ fú tóu hún wèi xǐng.", "xiū wèn.", "mèng hún yóu zài gé jiā xī.", "qiān gǔ zuì xiāng lái wǎng lù.", "zhī chù.", "wēn róu dōng pàn bái yún xī.", "qǐ xiàng lǜ chuāng gāo chù kàn.", "tí biàn.", "liú líng yuán zì yǒu xián qī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-346','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["春到蓬壶特地晴。", "神仙队里相公行。", "翠玉相挨呼小字。", "须记。", "笑簪花底是飞琼。", "总是倾城来一处。", "谁妒。", "谁携歌舞到园亭。", "柳妒腰肢花妒艳。", "听看。", "流莺直是妒歌声。"]'::jsonb,'["chūn dào péng hú tè dì qíng.", "shén xiān duì lǐ xiàng gōng xíng.", "cuì yù xiāng āi hū xiǎo zì.", "xū jì.", "xiào zān huā dǐ shì fēi qióng.", "zǒng shì qīng chéng lái yī chù.", "shuí dù.", "shuí xié gē wǔ dào yuán tíng.", "liǔ dù yāo zhī huā dù yàn.", "tīng kàn.", "liú yīng zhí shì dù gē shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-347','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["百紫千红过了春。", "杜鹃声苦不堪闻。", "却解啼教春小住。", "风雨。", "空山招得海棠魂。", "一似蜀宫当日女。", "无数。", "猩猩血染赭罗巾。", "毕竟花开谁作主。", "记取。", "大都花属惜花人。"]'::jsonb,'["bǎi zǐ qiān hóng guò le chūn.", "dù juān shēng kǔ bù kān wén.", "què jiě tí jiào chūn xiǎo zhù.", "fēng yǔ.", "kōng shān zhāo dé hǎi táng hún.", "yī sì shǔ gōng dāng rì nǚ.", "wú shù.", "xīng xīng xuè rǎn zhě luó jīn.", "bì jìng huā kāi shuí zuò zhǔ.", "jì qǔ.", "dà dū huā shǔ xī huā rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-348','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["少日犹堪话别离。", "老来怕作送行诗。", "极目南云无过雁。", "君看。", "梅花也解寄相思。", "无限江山行未了。", "父老。", "不须和泪看旌旗。", "后会丁宁何日□。", "须记。", "春风十日放灯时。"]'::jsonb,'["shǎo rì yóu kān huà bié lí.", "lǎo lái pà zuò sòng xíng shī.", "jí mù nán yún wú guò yàn.", "jūn kàn.", "méi huā yě jiě jì xiāng sī.", "wú xiàn jiāng shān xíng wèi liǎo.", "fù lǎo.", "bù xū hé lèi kàn jīng qí.", "hòu huì dīng níng hé rì □.", "xū jì.", "chūn fēng shí rì fàng dēng shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-349','定风波',NULL,'辛弃疾',NULL,'宋','宋词',FALSE,'["莫望中州叹黍离。", "元和圣德要君诗。", "老去不堪谁似我。", "归卧。", "青山活计费寻思。", "谁筑诗墙高十丈。", "直上。", "看君斩将更搴旗。", "歌舞正浓还有语。", "记取。", "须髯不似少年时。"]'::jsonb,'["mò wàng zhōng zhōu tàn shǔ lí.", "yuán hé shèng dé yào jūn shī.", "lǎo qù bù kān shuí shì wǒ.", "guī wò.", "qīng shān huó jì fèi xín sī.", "shuí zhù shī qiáng gāo shí zhàng.", "zhí shàng.", "kàn jūn zhǎn jiāng gèng qiān qí.", "gē wǔ zhèng nóng hái yǒu yǔ.", "jì qǔ.", "xū rán bù shì shào nián shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-350','西江月',NULL,'柳永',NULL,'宋','宋词',FALSE,'["凤额绣帘高卷，兽环朱户频摇。", "两竿红日上花梢。", "春睡厌厌难觉。", "好梦狂随飞絮，闲愁浓胜香醪。", "不成雨暮与云朝。", "又是韶光过了。"]'::jsonb,'["fèng é xiù lián gāo juǎn,shòu huán zhū hù pín yáo.", "liǎng gān hóng rì shàng huā shāo.", "chūn shuì yàn yàn nán jué.", "hǎo mèng kuáng suí fēi xù,xián chóu nóng shèng xiāng láo.", "bù chéng yǔ mù yǔ yún cháo.", "yòu shì sháo guāng guò le."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-351','西江月',NULL,'柳永',NULL,'宋','宋词',FALSE,'["师师生得艳冶，香香于我情多。", "安安那更久比和。", "四个打成一个。", "幸自苍皇未款，新词写处多磨。", "几回扯了又重挼。", "奸字中心著我。"]'::jsonb,'["shī shī shēng dé yàn yě,xiāng xiāng yú wǒ qíng duō.", "ān ān nà gèng jiǔ bǐ hé.", "sì gè dǎ chéng yí gè.", "xìng zì cāng huáng wèi kuǎn,xīn cí xiě chù duō mó.", "jǐ huí chě le yòu zhòng ruá.", "jiān zì zhōng xīn zhù wǒ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-352','清平乐',NULL,'柳永',NULL,'宋','宋词',FALSE,'["繁华锦烂。", "已恨归期晚。", "翠减红稀莺似懒。", "特地柔肠欲断。", "不堪尊酒频倾。", "恼人转转愁生。", "□□□□□□，多情争似无情。"]'::jsonb,'["fán huá jǐn làn.", "yǐ hèn guī qī wǎn.", "cuì jiǎn hóng xī yīng shì lǎn.", "tè dì róu cháng yù duàn.", "bù kān zūn jiǔ pín qīng.", "nǎo rén zhuǎn zhuǎn chóu shēng.", "□□□□□□,duō qíng zhēng shì wú qíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-353','鹊桥仙',NULL,'柳永',NULL,'宋','宋词',FALSE,'["届征途，携书剑，迢迢匹马东去。", "惨离怀，嗟少年易分难聚。", "佳人方恁缱绻，便忍分鸳侣。", "当媚景，算密意幽欢，尽成轻负。", "此际寸肠万绪。", "惨愁颜、断魂无语。", "和泪眼、片时几番回顾。", "伤心脉脉谁诉。", "但黯然凝伫。", "暮烟寒雨。", "望秦楼何处。"]'::jsonb,'["jiè zhēng tú,xié shū jiàn,tiáo tiáo pǐ mǎ dōng qù.", "cǎn lí huái,jiē shào nián yì fēn nán jù.", "jiā rén fāng nèn qiǎn quǎn,biàn rěn fēn yuān lǚ.", "dāng mèi jǐng,suàn mì yì yōu huān,jǐn chéng qīng fù.", "cǐ jì cùn cháng wàn xù.", "cǎn chóu yán,duàn hún wú yǔ.", "hé lèi yǎn,piàn shí jǐ fān huí gù.", "shāng xīn mò mò shuí sù.", "dàn àn rán níng zhù.", "mù yān hán yǔ.", "wàng qín lóu hé chù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-354','卜算子',NULL,'柳永',NULL,'宋','宋词',FALSE,'["江风渐老，汀蕙半凋，满目败红衰翠。", "楚客登临，正是暮秋天气。", "引疏砧、断续残阳里。", "对晚景、伤怀念远，新愁旧恨相继。", "脉脉人千里。", "念两处风情，万重烟水。", "雨歇天高，望断翠峰十二。", "尽无言、谁会凭高意。", "纵写得、离肠万种，奈归云谁寄。"]'::jsonb,'["jiāng fēng jiàn lǎo,tīng huì bàn diāo,mǎn mù bài hóng shuāi cuì.", "chǔ kè dēng lín,zhèng shì mù qiū tiān qì.", "yǐn shū zhēn,duàn xù cán yáng lǐ.", "duì wǎn jǐng,shāng huái niàn yuǎn,xīn chóu jiù hèn xiāng jì.", "mò mò rén qiān lǐ.", "niàn liǎng chù fēng qíng,wàn zhòng yān shuǐ.", "yǔ xiē tiān gāo,wàng duàn cuì fēng shí èr.", "jǐn wú yán,shuí huì píng gāo yì.", "zòng xiě dé,lí cháng wàn zhǒng,nài guī yún shuí jì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-355','满江红',NULL,'柳永',NULL,'宋','宋词',FALSE,'["匹马驱驱，摇征辔、溪边谷畔。", "望斜日西照，渐沈山半。", "两两栖禽归去急，对人相并声相唤。", "似笑我、独自向长途，离魂乱。", "中心事，多伤感。", "人是宿，前村馆。", "想鸳衾今夜，共他谁暖。", "惟有枕前相思泪，背灯弹了依前满。", "怎忘得、香阁共伊时，嫌更短。"]'::jsonb,'["pǐ mǎ qū qū,yáo zhēng pèi,xī biān gǔ pàn.", "wàng xié rì xī zhào,jiàn shěn shān bàn.", "liǎng liǎng qī qín guī qù jí,duì rén xiāng bìng shēng xiāng huàn.", "shì xiào wǒ,dú zì xiàng cháng tú,lí hún luàn.", "zhōng xīn shì,duō shāng gǎn.", "rén shì sù,qián cūn guǎn.", "xiǎng yuān qīn jīn yè,gòng tā shuí nuǎn.", "wéi yǒu zhěn qián xiāng sī lèi,bèi dēng dàn le yī qián mǎn.", "zěn wàng dé,xiāng gé gòng yī shí,xián gèng duǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-356','满江红',NULL,'柳永',NULL,'宋','宋词',FALSE,'["暮雨初收，长川静、征帆夜落。", "临岛屿、蓼烟疏淡，苇风萧索。", "几许渔人飞短艇，尽载灯火归村落。", "遣行客、当此念回程，伤漂泊。", "桐江好，烟漠漠。", "波似染，山如削。", "绕严陵滩畔，鹭飞鱼跃。", "游宦区区成底事，平生况有云泉约。", "归去来、一曲仲宣吟，从军乐。"]'::jsonb,'["mù yǔ chū shōu,cháng chuān jìng,zhēng fān yè luò.", "lín dǎo yǔ,liǎo yān shū dàn,wěi fēng xiāo suǒ.", "jǐ xǔ yú rén fēi duǎn tǐng,jǐn zài dēng huǒ guī cūn luò.", "qiǎn xíng kè,dāng cǐ niàn huí chéng,shāng piāo bó.", "tóng jiāng hǎo,yān mò mò.", "bō shì rǎn,shān rú xuē.", "rào yán líng tān pàn,lù fēi yú yuè.", "yóu huàn qū qū chéng dǐ shì,píng shēng kuàng yǒu yún quán yuē.", "guī qù lái,yī qū zhòng xuān yín,cóng jūn lè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-357','满江红',NULL,'柳永',NULL,'宋','宋词',FALSE,'["访雨寻云，无非是、奇容艳色。", "就中有、天真妖丽，自然标格。", "恶发姿颜欢喜面，细追想处皆堪惜。", "自别后、幽怨与闲愁，成堆积。", "鳞鸿阻，无信息。", "梦魂断，难寻觅。", "尽思量，休又怎生休得。", "谁恁多情凭向道，纵来相见且相忆。", "便不成、常遣似如今，轻抛掷。"]'::jsonb,'["fǎng yǔ xún yún,wú fēi shì,qí róng yàn sè.", "jiù zhōng yǒu,tiān zhēn yāo lì,zì rán biāo gé.", "è fā zī yán huān xǐ miàn,xì zhuī xiǎng chù jiē kān xī.", "zì bié hòu,yōu yuàn yǔ xián chóu,chéng duī jī.", "lín hóng zǔ,wú xìn xī.", "mèng hún duàn,nán xún mì.", "jǐn sī liáng,xiū yòu zěn shēng xiū dé.", "shuí nèn duō qíng píng xiàng dào,zòng lái xiāng jiàn qiě xiāng yì.", "biàn bù chéng,cháng qiǎn shì rú jīn,qīng pāo zhì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-358','满江红',NULL,'柳永',NULL,'宋','宋词',FALSE,'["万恨千愁，将年少、衷肠牵系。", "残梦断、酒醒孤馆，夜长无味。", "可惜许枕前多少意，到如今两总无终始。", "独自个、赢得不成眠，成憔悴。", "添伤感，将何计。", "空只恁，厌厌地。", "无人处思量，几度垂泪。", "不会得都来些子事，甚恁底死难拚弃。", "待到头、终久问伊看，如何是。"]'::jsonb,'["wàn hèn qiān chóu,jiāng nián shào,zhōng cháng qiān xì.", "cán mèng duàn,jiǔ xǐng gū guǎn,yè zhǎng wú wèi.", "kě xī xǔ zhěn qián duō shǎo yì,dào rú jīn liǎng zǒng wú zhōng shǐ.", "dú zì gè,yíng dé bù chéng mián,chéng qiáo cuì.", "tiān shāng gǎn,jiāng hé jì.", "kōng zhǐ nèn,yàn yàn dì.", "wú rén chù sī liáng,jǐ dù chuí lèi.", "bú huì dé dōu lái xiē zi shì,shèn nèn dǐ sǐ nàn pàn qì.", "dài dào tóu,zhōng jiǔ wèn yī kàn,rú hé shì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-359','渔家傲',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["十一月新阳排寿宴。", "黄锺应管添宫线。", "猎猎寒威云不卷。", "风头转。", "时看雪霰吹人面。", "南至迎长知漏箭。", "书云纪候冰生妍。", "腊近探春春尚远。", "闲庭院。", "梅花落尽千千片。"]'::jsonb,'["shí yī yuè xīn yáng pái shòu yàn.", "huáng zhōng yīng guǎn tiān gōng xiàn.", "liè liè hán wēi yún bù juǎn.", "fēng tou zhuǎn.", "shí kàn xuě xiàn chuī rén miàn.", "nán zhì yíng zhǎng zhī lòu jiàn.", "shū yún jì hòu bīng shēng yán.", "là jìn tàn chūn chūn shàng yuǎn.", "xián tíng yuàn.", "méi huā luò jǐn qiān qiān piàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-360','渔家傲',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["十二月严凝天地闭。", "莫嫌台榭无花卉。", "惟有酒能欺雪意。", "增豪气。", "直教耳热笙歌沸。", "陇上雕鞍惟数骑。", "猎围半合新霜里。", "霜重鼓声寒不起。", "千人指。", "马前一雁寒空坠。"]'::jsonb,'["shí èr yuè yán níng tiān dì bì.", "mò xián tái xiè wú huā huì.", "wéi yǒu jiǔ néng qī xuě yì.", "zēng háo qì.", "zhí jiào ěr rè shēng gē fèi.", "lǒng shàng diāo ān wéi shù qí.", "liè wéi bàn hé xīn shuāng lǐ.", "shuāng zhòng gǔ shēng hán bù qǐ.", "qiān rén zhǐ.", "mǎ qián yī yàn hán kōng zhuì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-361','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["把酒花前欲问他。", "对花何吝醉颜酡。", "春到几人能烂赏。", "何况。", "无情风雨等闲多。", "艳树香丛都几许。", "朝暮。", "惜红愁粉奈情何。", "好是金船浮玉浪。", "相向。", "十分深送一声歌。"]'::jsonb,'["bǎ jiǔ huā qián yù wèn tā.", "duì huā hé lìn zuì yán tuó.", "chūn dào jǐ rén néng làn shǎng.", "hé kuàng.", "wú qíng fēng yǔ děng xián duō.", "yàn shù xiāng cóng dōu jǐ xǔ.", "zhāo mù.", "xī hóng chóu fěn nài qíng hé.", "hǎo shì jīn chuán fú yù làng.", "xiāng xiàng.", "shí fēn shēn sòng yī shēng gē."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-362','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["把酒花前欲问伊。", "忍嫌金盏负春时。", "红颜不能旬日看。", "宜算。", "须知开谢只相随。", "蝶去蝶来犹解恋。", "难见。", "回头还是度年期。", "莫候饮阑花已尽。", "方信。", "无人堪与补残枝。"]'::jsonb,'["bǎ jiǔ huā qián yù wèn yī.", "rěn xián jīn zhǎn fù chūn shí.", "hóng yán bù néng xún rì kàn.", "yí suàn.", "xū zhī kāi xiè zhǐ xiāng suí.", "dié qù dié lái yóu jiě liàn.", "nán jiàn.", "huí tóu hái shì dù nián qī.", "mò hòu yǐn lán huā yǐ jǐn.", "fāng xìn.", "wú rén kān yǔ bǔ cán zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-363','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["把酒花前欲问公。", "对花何事诉金锺。", "为问去年春甚处。", "虚度。", "莺声撩乱一场空。", "今岁春来须爱惜。", "难得。", "须知花面不长红。", "待得酒醒君不见。", "千片。", "不随流水即随风。"]'::jsonb,'["bǎ jiǔ huā qián yù wèn gōng.", "duì huā hé shì sù jīn zhōng.", "wèi wèn qù nián chūn shèn chù.", "xū dù.", "yīng shēng liáo luàn yī cháng kōng.", "jīn suì chūn lái xū ài xī.", "nán dé.", "xū zhī huā miàn bù zhǎng hóng.", "dài dé jiǔ xǐng jūn bú jiàn.", "qiān piàn.", "bù suí liú shuǐ jí suí fēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-364','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["把酒花前欲问君。", "世间何计可留春。", "纵使青春留得住。", "虚语。", "无情花对有情人。", "任是好花须落去。", "自古。", "红颜能得几时新。", "暗想浮生何时好。", "唯有。", "清歌一曲倒金尊。"]'::jsonb,'["bǎ jiǔ huā qián yù wèn jūn.", "shì jiān hé jì kě liú chūn.", "zòng shǐ qīng chūn liú dé zhù.", "xū yǔ.", "wú qíng huā duì yǒu qíng rén.", "rèn shì hǎo huā xū luò qù.", "zì gǔ.", "hóng yán néng dé jǐ shí xīn.", "àn xiǎng fú shēng hé shí hǎo.", "wéi yǒu.", "qīng gē yī qū dào jīn zūn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-365','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["过尽韶华不可添。", "小楼红日下层檐。", "春睡觉来情绪恶。", "寂寞。", "杨花缭乱拂珠帘。", "早是闲愁依旧在。", "无奈。", "那堪更被宿酲兼。", "把酒送春惆怅甚。", "长恁。", "年年三月病厌厌。"]'::jsonb,'["guò jǐn sháo huá bù kě tiān.", "xiǎo lóu hóng rì xià céng yán.", "chūn shuì jiào lái qíng xù è.", "jì mò.", "yáng huā liáo luàn fú zhū lián.", "zǎo shì xián chóu yī jiù zài.", "wú nài.", "nà kān gèng bèi sù chéng jiān.", "bǎ jiǔ sòng chūn chóu chàng shèn.", "zhǎng nèn.", "nián nián sān yuè bìng yàn yàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-366','定风波',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["对酒追欢莫负春。", "春光归去可饶人。", "昨日红芳今绿树。", "已暮。", "残花飞絮两纷纷。", "粉面丽姝歌窈窕。", "清妙。", "尊前信任醉醺醺。", "不是狂心贪燕乐。", "自觉。", "年来白发满头新。"]'::jsonb,'["duì jiǔ zhuī huān mò fù chūn.", "chūn guāng guī qù kě ráo rén.", "zuó rì hóng fāng jīn lǜ shù.", "yǐ mù.", "cán huā fēi xù liǎng fēn fēn.", "fěn miàn lì shū gē yǎo tiǎo.", "qīng miào.", "zūn qián xìn rèn zuì xūn xūn.", "bú shì kuáng xīn tān yàn lè.", "zì jué.", "nián lái bái fà mǎn tóu xīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-367','渔家傲',NULL,'欧阳修',NULL,'宋','宋词',FALSE,'["一派潺湲流碧涨。", "新亭四面山相向。", "翠竹岭头明月上。", "迷俯仰。", "月轮正在泉中漾。", "更待高秋天气爽。", "菊花香里开新酿。", "酒美宾嘉真胜赏。", "红粉唱。", "山深分外歌声响。"]'::jsonb,'["yī pài chán yuán liú bì zhǎng.", "xīn tíng sì miàn shān xiāng xiàng.", "cuì zhú lǐng tóu míng yuè shàng.", "mí fǔ yǎng.", "yuè lún zhèng zài quán zhōng yàng.", "gèng dài gāo qiū tiān qì shuǎng.", "jú huā xiāng lǐ kāi xīn niàng.", "jiǔ měi bīn jiā zhēn shèng shǎng.", "hóng fěn chàng.", "shān shēn fèn wài gē shēng xiǎng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-368','破阵子',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["海上蟠桃易熟，人间好月长圆。", "惟有掰钗分钿侣，离别常多会面难。", "此情须问天。", "蜡烛到明垂泪，熏炉尽日生烟。", "一点凄凉愁绝意，谩道秦筝有剩弦。", "何曾为细传。"]'::jsonb,'["hǎi shàng pán táo yì shú,rén jiān hǎo yuè cháng yuán.", "wéi yǒu bāi chāi fēn diàn lǚ,lí bié cháng duō huì miàn nán.", "cǐ qíng xū wèn tiān.", "là zhú dào míng chuí lèi,xūn lú jǐn rì shēng yān.", "yì diǎn qī liáng chóu jué yì,mán dào qín zhēng yǒu shèng xián.", "hé zēng wèi xì chuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-369','破阵子',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["燕子欲归时节，高楼昨夜西风。", "求得人间成小会，试把金尊傍菊丛。", "歌长粉面红。", "斜日更穿帘幕，微凉渐入梧桐。", "多少襟怀言不尽，写向蛮笺曲调中。", "此情千万重。"]'::jsonb,'["yàn zi yù guī shí jié,gāo lóu zuó yè xī fēng.", "qiú dé rén jiān chéng xiǎo huì,shì bǎ jīn zūn bàng jú cóng.", "gē zhǎng fěn miàn hóng.", "xié rì gèng chuān lián mù,wēi liáng jiàn rù wú tóng.", "duō shǎo jīn huái yán bù jǐn,xiě xiàng mán jiān qǔ diào zhōng.", "cǐ qíng qiān wàn zhòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-370','破阵子',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["忆得去年今日，黄花已满东篱。", "曾与玉人临小槛，共折香英泛酒卮。", "长条插鬓垂。", "人貌不应迁换，珍丛又睹芳菲。", "重把一尊寻旧径，所惜光阴去似飞。", "风飘露冷时。"]'::jsonb,'["yì dé qù nián jīn rì,huáng huā yǐ mǎn dōng lí.", "céng yǔ yù rén lín xiǎo kǎn,gòng zhé xiāng yīng fàn jiǔ zhī.", "cháng tiáo chā bìn chuí.", "rén mào bù yīng qiān huàn,zhēn cóng yòu dǔ fāng fēi.", "zhòng bǎ yī zūn xún jiù jìng,suǒ xī guāng yīn qù shì fēi.", "fēng piāo lù lěng shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-371','破阵子',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["湖上西风斜日，荷花落尽红英。", "金菊满丛珠颗细，海燕辞巢翅羽轻。", "年年岁岁情。", "美酒一杯新熟，高歌数阕堪听。", "不向尊前同一醉，可奈光阴似水声。", "迢迢去未停。"]'::jsonb,'["hú shàng xī fēng xié rì,hé huā luò jǐn hóng yīng.", "jīn jú mǎn cóng zhū kē xì,hǎi yàn cí cháo chì yǔ qīng.", "nián nián suì suì qíng.", "měi jiǔ yī bēi xīn shú,gāo gē shù què kān tīng.", "bù xiàng zūn qián tóng yī zuì,kě nài guāng yīn shì shuǐ shēng.", "tiáo tiáo qù wèi tíng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-372','渔家傲',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["画鼓声中昏又晓。", "时光只解催人老。", "求得浅欢风日好。", "齐揭调。", "神仙一曲渔家傲。", "绿水悠悠天杳杳。", "浮生岂得长年少。", "莫惜醉来开口笑。", "须信道。", "人间万事何时了。"]'::jsonb,'["huà gǔ shēng zhōng hūn yòu xiǎo.", "shí guāng zhǐ jiě cuī rén lǎo.", "qiú dé qiǎn huān fēng rì hǎo.", "qí jiē diào.", "shén xiān yī qū yú jiā ào.", "lǜ shuǐ yōu yōu tiān yǎo yǎo.", "fú shēng qǐ dé cháng nián shǎo.", "mò xī zuì lái kāi kǒu xiào.", "xū xìn dào.", "rén jiān wàn shì hé shí le."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-373','渔家傲',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["荷叶荷花相间斗。", "红娇绿嫩新妆就。", "昨日小池疏雨后。", "铺锦绣。", "行人过去频回首。", "倚遍朱阑凝望久。", "鸳鸯浴处波文皱。", "谁唤谢娘斟美酒。", "萦舞袖。", "当筵劝我千长寿。"]'::jsonb,'["hé yè hé huā xiāng jiàn dòu.", "hóng jiāo lǜ nèn xīn zhuāng jiù.", "zuó rì xiǎo chí shū yǔ hòu.", "pù jǐn xiù.", "xíng rén guò qù pín huí shǒu.", "yǐ biàn zhū lán níng wàng jiǔ.", "yuān yāng yù chù bō wén zhòu.", "shuí huàn xiè niáng zhēn měi jiǔ.", "yíng wǔ xiù.", "dāng yán quàn wǒ qiān cháng shòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-374','渔家傲',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["荷叶初开犹半卷。", "荷花欲拆犹微绽。", "此叶此花真可羡。", "秋水畔。", "青凉伞映红妆面。", "美酒一杯留客宴。", "拈花摘叶情无限。", "争奈世人多聚散。", "频祝愿。", "如花似叶长相见。"]'::jsonb,'["hé yè chū kāi yóu bàn juǎn.", "hé huā yù chāi yóu wēi zhàn.", "cǐ yè cǐ huā zhēn kě xiàn.", "qiū shuǐ pàn.", "qīng liáng sǎn yìng hóng zhuāng miàn.", "měi jiǔ yī bēi liú kè yàn.", "niān huā zhāi yè qíng wú xiàn.", "zhēng nài shì rén duō jù sàn.", "pín zhù yuàn.", "rú huā shì yè zhǎng xiàng jiàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-375','渔家傲',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["杨柳风前香百步。", "盘心碎点真珠露。", "疑是水仙开洞府。", "妆景趣。", "红幢绿盖朝天路。", "小鸭飞来稠闹处。", "三三两两能言语。", "饮散短亭人欲去。", "留不住。", "黄昏更下萧萧雨。"]'::jsonb,'["yáng liǔ fēng qián xiāng bǎi bù.", "pán xīn suì diǎn zhēn zhū lù.", "yí shì shuǐ xiān kāi dòng fǔ.", "zhuāng jǐng qù.", "hóng chuáng lǜ gài cháo tiān lù.", "xiǎo yā fēi lái chóu nào chù.", "sān sān liǎng liǎng néng yán yǔ.", "yǐn sàn duǎn tíng rén yù qù.", "liú bú zhù.", "huáng hūn gèng xià xiāo xiāo yǔ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-376','渔家傲',NULL,'晏殊',NULL,'宋','宋词',FALSE,'["粉笔丹青描未得。", "金针彩线功难敌。", "谁傍暗香轻采摘。", "风淅淅。", "船头触散双㶉𫛶。", "夜雨染成天水碧。", "朝阳借出胭脂色。", "欲落又开人共惜。", "秋气逼。", "盘中已见新莲菂。"]'::jsonb,'["fěn bǐ dān qīng miáo wèi dé.", "jīn zhēn cǎi xiàn gōng nán dí.", "shuí bàng àn xiāng qīng cǎi zhāi.", "fēng xī xī.", "chuán tóu chù sàn shuāng xī chì.", "yè yǔ rǎn chéng tiān shuǐ bì.", "zhāo yáng jiè chū yān zhī sè.", "yù luò yòu kāi rén gòng xī.", "qiū qì bī.", "pán zhōng yǐ jiàn xīn lián dì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-377','定风波',NULL,'陆游',NULL,'宋','宋词',FALSE,'["敧帽垂鞭送客回。", "小桥流水一枝梅。", "衰病逢春都不记。", "谁谓。", "幽香却解逐人来。", "安得身闲频置酒。", "携手。", "与君看到十分开。", "少壮相从今雪鬓。", "因甚。", "流年羁恨两相催。"]'::jsonb,'["jī mào chuí biān sòng kè huí.", "xiǎo qiáo liú shuǐ yī zhī méi.", "shuāi bìng féng chūn dōu bù jì.", "shuí wèi.", "yōu xiāng què jiě zhú rén lái.", "ān dé shēn xián pín zhì jiǔ.", "xié shǒu.", "yǔ jūn kàn dào shí fēn kāi.", "shào zhuàng xiāng cóng jīn xuě bìn.", "yīn shèn.", "liú nián jī hèn liǎng xiāng cuī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-378','蝶恋花',NULL,'陆游',NULL,'宋','宋词',FALSE,'["桐叶晨飘蛩夜语。", "旅思秋光，黯黯长安路。", "忽记横戈盘马处。", "散关清渭应如故。", "江海轻舟今已具。", "一卷兵书，叹息无人付。", "早信此生终不遇。", "当年悔草《长杨赋》。"]'::jsonb,'["tóng yè chén piāo qióng yè yǔ.", "lǚ sī qiū guāng,àn àn cháng ān lù.", "hū jì héng gē pán mǎ chù.", "sàn guān qīng wèi yīng rú gù.", "jiāng hǎi qīng zhōu jīn yǐ jù.", "yī juàn bīng shū,tàn xī wú rén fù.", "zǎo xìn cǐ shēng zhōng bù yù.", "dāng nián huǐ cǎo 《 zhǎng yáng fù 》."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-379','渔家傲',NULL,'陆游',NULL,'宋','宋词',FALSE,'["东望山阴何处是。", "往来一万三千里。", "写得家书空满纸。", "流清泪。", "书回已是明年事。", "寄语红桥桥下水。", "扁舟何日寻兄弟。", "行遍天涯真老矣。", "愁无寐。", "鬓丝几缕茶烟里。"]'::jsonb,'["dōng wàng shān yīn hé chù shì.", "wǎng lái yī wàn sān qiān lǐ.", "xiě dé jiā shū kōng mǎn zhǐ.", "liú qīng lèi.", "shū huí yǐ shì míng nián shì.", "jì yǔ hóng qiáo qiáo xià shuǐ.", "piān zhōu hé rì xún xiōng dì.", "xíng biàn tiān yá zhēn lǎo yǐ.", "chóu wú mèi.", "bìn sī jǐ lǚ chá yān lǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-380','破阵子',NULL,'陆游',NULL,'宋','宋词',FALSE,'["仕至千锺良易，年过七十常稀。", "眼底荣华元是梦，身后声名不自知。", "营营端为谁。", "幸有旗亭沽酒，何妨茧纸题诗。", "幽谷云萝朝采药，静院轩窗夕对棋。", "不归真个痴。"]'::jsonb,'["shì zhì qiān zhōng liáng yì,nián guò qī shí cháng xī.", "yǎn dǐ róng huá yuán shì mèng,shēn hòu shēng míng bù zì zhī.", "yíng yíng duān wèi shuí.", "xìng yǒu qí tíng gū jiǔ,hé fáng jiǎn zhǐ tí shī.", "yōu gǔ yún luó cháo cǎi yào,jìng yuàn xuān chuāng xī duì qí.", "bù guī zhēn gè chī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-381','破阵子',NULL,'陆游',NULL,'宋','宋词',FALSE,'["看破空花尘世，放轻昨梦浮名。", "蜡屐登山真率饮，筇杖穿林自在行。", "身闲心太平。", "料峭馀寒犹力，廉纤细雨初晴。", "苔纸闲题溪上句，菱唱遥闻烟外声。", "与君同醉醒。"]'::jsonb,'["kàn pò kōng huā chén shì,fàng qīng zuó mèng fú míng.", "là jī dēng shān zhēn shuài yǐn,qióng zhàng chuān lín zì zài háng.", "shēn xián xīn tài píng.", "liào qiào yú hán yóu lì,lián xiān xì yǔ chū qíng.", "tái zhǐ xián tí xī shàng jù,líng chàng yáo wén yān wài shēng.", "yǔ jūn tóng zuì xǐng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-382','青玉案',NULL,'陆游',NULL,'宋','宋词',FALSE,'["西风挟雨声翻浪。", "恰洗尽、黄茅瘴。", "老惯人间齐得丧。", "千岩高卧，五湖归棹，替却凌烟像。", "故人小驻平戎帐。", "白羽腰间气何壮。", "我老渔樵君将相。", "小槽红酒，晚香丹荔，记取蛮江上。"]'::jsonb,'["xī fēng xié yǔ shēng fān làng.", "qià xǐ jǐn,huáng máo zhàng.", "lǎo guàn rén jiān qí dé sàng.", "qiān yán gāo wò,wǔ hú guī zhào,tì què líng yān xiàng.", "gù rén xiǎo zhù píng róng zhàng.", "bái yǔ yāo jiān qì hé zhuàng.", "wǒ lǎo yú qiáo jūn jiàng xiàng.", "xiǎo cáo hóng jiǔ,wǎn xiāng dān lì,jì qǔ mán jiāng shàng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-383','蝶恋花',NULL,'陆游',NULL,'宋','宋词',FALSE,'["陌上箫声寒食近。", "雨过园林，花气浮芳润。", "千里斜阳锺欲瞑。", "凭高望断南楼信。", "海角天涯行略尽。", "三十年间，无处无遗恨。", "天若有情终欲问。", "忍教霜点相思鬓。"]'::jsonb,'["mò shàng xiāo shēng hán shí jìn.", "yǔ guò yuán lín,huā qì fú fāng rùn.", "qiān lǐ xié yáng zhōng yù míng.", "píng gāo wàng duàn nán lóu xìn.", "hǎi jiǎo tiān yá xíng lüè jǐn.", "sān shí nián jiān,wú chǔ wú yí hèn.", "tiān ruò yǒu qíng zhōng yù wèn.", "rěn jiào shuāng diǎn xiāng sī bìn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-384','蝶恋花',NULL,'陆游',NULL,'宋','宋词',FALSE,'["水漾萍根风卷絮。", "倩笑娇颦，忍记逢迎处。", "只有梦魂能再遇。", "堪嗟梦不由人做。", "梦若由人何处去。", "短帽轻衫，夜夜眉州路。", "不怕银缸深绣户。", "只愁风断青衣渡。"]'::jsonb,'["shuǐ yàng píng gēn fēng juǎn xù.", "qiàn xiào jiāo pín,rěn jì féng yíng chù.", "zhǐ yǒu mèng hún néng zài yù.", "kān jiē mèng bù yóu rén zuò.", "mèng ruò yóu rén hé chù qù.", "duǎn mào qīng shān,yè yè méi zhōu lù.", "bù pà yín gāng shēn xiù hù.", "zhǐ chóu fēng duàn qīng yī dù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-385','蝶恋花',NULL,'陆游',NULL,'宋','宋词',FALSE,'["禹庙兰亭今古路。", "一夜清霜，染尽湖边树。", "鹦鹉杯深君莫诉。", "他时相遇知何处。", "冉冉年华留不住。", "镜里朱颜，毕竟消磨去。", "一句丁宁君记取。", "神仙须是闲人做。"]'::jsonb,'["yǔ miào lán tíng jīn gǔ lù.", "yī yè qīng shuāng,rǎn jǐn hú biān shù.", "yīng wǔ bēi shēn jūn mò sù.", "tā shí xiāng yù zhī hé chù.", "rǎn rǎn nián huá liú bú zhù.", "jìng lǐ zhū yán,bì jìng xiāo mó qù.", "yī jù dīng níng jūn jì qǔ.", "shén xiān xū shì xián rén zuò."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-386','满江红',NULL,'岳飞',NULL,'宋','宋词',FALSE,'["遥望中原，荒烟外、许多城郭。", "想当年、花遮柳护，凤楼龙阁。", "万岁山前珠翠绕，蓬壶殿里笙歌作。", "到而今、铁骑满郊畿，风尘恶。", "兵安在，膏锋锷。", "民安在，填沟壑。", "叹江山如故，千村寥落。", "何日请缨提锐旅，一鞭直渡清河洛。", "却归来、再续汉阳游，骑黄鹤。"]'::jsonb,'["yáo wàng zhōng yuán,huāng yān wài,xǔ duō chéng guō.", "xiǎng dāng nián,huā zhē liǔ hù,fèng lóu lóng gé.", "wàn suì shān qián zhū cuì rào,péng hú diàn lǐ shēng gē zuò.", "dào ér jīn,tiě qí mǎn jiāo jī,fēng chén è.", "bīng ān zài,gāo fēng è.", "mín ān zài,tián gōu hè.", "tàn jiāng shān rú gù,qiān cūn liáo luò.", "hé rì qǐng yīng tí ruì lǚ,yī biān zhí dù qīng hé luò.", "què guī lái,zài xù hàn yáng yóu,qí huáng hè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-387','小重山',NULL,'岳飞',NULL,'宋','宋词',FALSE,'["昨夜寒蛩不住鸣。", "惊回千里梦，已三更。", "起来独自绕阶行。", "人悄悄，帘外月胧明。", "白首为功名。", "旧山松竹老，阻归程。", "欲将心事付瑶琴。", "知音少，弦断有谁听。"]'::jsonb,'["zuó yè hán qióng bú zhù míng.", "jīng huí qiān lǐ mèng,yǐ sān gēng.", "qǐ lái dú zì rào jiē xíng.", "rén qiāo qiāo,lián wài yuè lóng míng.", "bái shǒu wèi gōng míng.", "jiù shān sōng zhú lǎo,zǔ guī chéng.", "yù jiāng xīn shì fù yáo qín.", "zhī yīn shǎo,xián duàn yǒu shuí tīng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-388','蝶恋花',NULL,'秦观',NULL,'宋','宋词',FALSE,'["晓日窥轩双燕语。", "似与佳人，共惜春将暮。", "屈指艳阳都几许。", "可无时霎闲风雨。", "流水落花无问处。", "只有飞云，冉冉来还去。", "持酒劝云云且住。", "凭君碍断春归路。"]'::jsonb,'["xiǎo rì kuī xuān shuāng yàn yǔ.", "shì yǔ jiā rén,gòng xī chūn jiāng mù.", "qū zhǐ yàn yáng dōu jǐ xǔ.", "kě wú shí shà xián fēng yǔ.", "liú shuǐ luò huā wú wèn chù.", "zhǐ yǒu fēi yún,rǎn rǎn lái hái qù.", "chí jiǔ quàn yún yún qiě zhù.", "píng jūn ài duàn chūn guī lù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-389','虞美人',NULL,'秦观',NULL,'宋','宋词',FALSE,'["高城望断尘如雾。", "不见联骖处。", "夕阳村外小湾头。", "只有柳花无数、送归舟。", "琼枝玉树频相见。", "只恨离人远。", "欲将幽事寄青楼。", "争奈无情江水、不西流。"]'::jsonb,'["gāo chéng wàng duàn chén rú wù.", "bú jiàn lián cān chù.", "xī yáng cūn wài xiǎo wān tóu.", "zhǐ yǒu liǔ huā wú shù,sòng guī zhōu.", "qióng zhī yù shù pín xiāng jiàn.", "zhǐ hèn lí rén yuǎn.", "yù jiāng yōu shì jì qīng lóu.", "zhēng nài wú qíng jiāng shuǐ,bù xī liú."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-390','虞美人',NULL,'秦观',NULL,'宋','宋词',FALSE,'["碧桃天上栽和露。", "不是凡花数。", "乱山深处水潆回。", "可惜一枝如画、为谁开。", "轻寒细雨情何限。", "不道春难管。", "为君沈醉又何妨。", "祗怕酒醒时候、断人肠。"]'::jsonb,'["bì táo tiān shàng zāi hé lù.", "bú shì fán huā shù.", "luàn shān shēn chù shuǐ yíng huí.", "kě xī yī zhī rú huà,wèi shuí kāi.", "qīng hán xì yǔ qíng hé xiàn.", "bù dào chūn nán guǎn.", "wèi jūn shěn zuì yòu hé fáng.", "zhī pà jiǔ xǐng shí hòu,duàn rén cháng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-391','虞美人',NULL,'秦观',NULL,'宋','宋词',FALSE,'["行行信马横塘畔。", "烟水秋平岸。", "绿荷多少夕阳中。", "知为阿谁凝恨、背西风。", "红妆艇子来何处。", "荡桨偷相顾。", "鸳鸯惊起不无愁。", "柳外一双飞去、却回头。"]'::jsonb,'["xíng xíng xìn mǎ héng táng pàn.", "yān shuǐ qiū píng àn.", "lǜ hé duō shǎo xī yáng zhōng.", "zhī wèi ā shuí níng hèn,bèi xī fēng.", "hóng zhuāng tǐng zi lái hé chù.", "dàng jiǎng tōu xiāng gù.", "yuān yāng jīng qǐ bù wú chóu.", "liǔ wài yī shuāng fēi qù,què huí tóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-392','江城子',NULL,'秦观',NULL,'宋','宋词',FALSE,'["西城杨柳弄春柔。", "动离忧。", "泪难收。", "犹记多情，曾为系归舟。", "碧野朱桥当日事，人不见，水空流。", "韶华不为少年留。", "恨悠悠。", "几时休。", "飞絮落花时候、一登楼。", "便做春江都是泪，流不尽，许多愁。"]'::jsonb,'["xī chéng yáng liǔ nòng chūn róu.", "dòng lí yōu.", "lèi nán shōu.", "yóu jì duō qíng,céng wèi xì guī zhōu.", "bì yě zhū qiáo dāng rì shì,rén bú jiàn,shuǐ kōng liú.", "sháo huá bù wèi shào nián liú.", "hèn yōu yōu.", "jǐ shí xiū.", "fēi xù luò huā shí hòu,yī dēng lóu.", "biàn zuò chūn jiāng dū shì lèi,liú bù jìn,xǔ duō chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-393','江城子',NULL,'秦观',NULL,'宋','宋词',FALSE,'["南来飞燕北归鸿。", "偶相逢。", "惨愁容。", "绿鬓朱颜，重见两衰翁。", "别后悠悠君莫问，无限事，不言中。", "小槽春酒滴珠红。", "莫匆匆。", "满金锺。", "饮散落花流水、各西东。", "后会不知何处是，烟浪远，暮云重。"]'::jsonb,'["nán lái fēi yàn běi guī hóng.", "ǒu xiāng féng.", "cǎn chóu róng.", "lǜ bìn zhū yán,zhòng jiàn liǎng shuāi wēng.", "bié hòu yōu yōu jūn mò wèn,wú xiàn shì,bù yán zhōng.", "xiǎo cáo chūn jiǔ dī zhū hóng.", "mò cōng cōng.", "mǎn jīn zhōng.", "yǐn sàn luò huā liú shuǐ,gè xī dōng.", "hòu huì bù zhī hé chù shì,yān làng yuǎn,mù yún zhòng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-394','江城子',NULL,'秦观',NULL,'宋','宋词',FALSE,'["枣花金钏约柔荑。", "昔曾携。", "事难期。", "咫尺玉颜，和泪锁春闺。", "恰似小园桃与李，虽同处，不同枝。", "玉笙初度颤鸾篦。", "落花飞。", "为谁吹。", "月冷风高，此恨只天知。", "任是行人无定处，重相见，是何时。"]'::jsonb,'["zǎo huā jīn chuàn yuē róu tí.", "xī céng xié.", "shì nán qī.", "zhǐ chǐ yù yán,hé lèi suǒ chūn guī.", "qià sì xiǎo yuán táo yǔ lǐ,suī tóng chù,bù tóng zhī.", "yù shēng chū dù chàn luán bì.", "luò huā fēi.", "wèi shuí chuī.", "yuè lěng fēng gāo,cǐ hèn zhǐ tiān zhī.", "rèn shì xíng rén wú dìng chù,zhòng xiāng jiàn,shì hé shí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-395','菩萨蛮',NULL,'秦观',NULL,'宋','宋词',FALSE,'["虫声泣露惊秋枕。", "罗帏泪湿鸳鸯锦。", "独卧玉肌凉。", "残更与恨长。", "阴风翻翠幔。", "雨涩灯花暗。", "毕竟不成眠。", "鸦啼金井寒。"]'::jsonb,'["chóng shēng qì lù jīng qiū zhěn.", "luó wéi lèi shī yuān yāng jǐn.", "dú wò yù jī liáng.", "cán gèng yǔ hèn zhǎng.", "yīn fēng fān cuì màn.", "yǔ sè dēng huā àn.", "bì jìng bù chéng mián.", "yā tí jīn jǐng hán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-396','浣溪沙',NULL,'秦观',NULL,'宋','宋词',FALSE,'["漠漠轻寒上小楼。", "晓阴无赖似穷秋。", "淡烟流水画屏幽。", "自在飞花轻似梦，无边丝雨细如愁。", "宝帘闲挂小银钩。"]'::jsonb,'["mò mò qīng hán shàng xiǎo lóu.", "xiǎo yīn wú lài shì qióng qiū.", "dàn yān liú shuǐ huà píng yōu.", "zì zài fēi huā qīng shì mèng,wú biān sī yǔ xì rú chóu.", "bǎo lián xián guà xiǎo yín gōu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-397','破阵子',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["柳下笙歌庭院，花间姊妹秋千。", "记得春楼当日事，写向红窗夜月前。", "凭谁寄小莲。", "绛蜡等闲陪泪，吴蚕到了缠绵。", "绿鬓能供多少恨，未肯无情比断弦。", "今年老去年。"]'::jsonb,'["liǔ xià shēng gē tíng yuàn,huā jiān zǐ mèi qiū qiān.", "jì de chūn lóu dāng rì shì,xiě xiàng hóng chuāng yè yuè qián.", "píng shuí jì xiǎo lián.", "jiàng là děng xián péi lèi,wú cán dào le chán mián.", "lǜ bìn néng gōng duō shǎo hèn,wèi kěn wú qíng bǐ duàn xián.", "jīn nián lǎo qù nián."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-398','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["卷絮风头寒欲尽。", "坠粉飘红，日日香成阵。", "新酒又添残酒困。", "今春不减前春恨。", "蝶去莺飞无处问。", "隔水高楼，望断双鱼信。", "恼乱层波横一寸。", "斜阳只与黄昏近。"]'::jsonb,'["juǎn xù fēng tou hán yù jǐn.", "zhuì fěn piāo hóng,rì rì xiāng chéng zhèn.", "xīn jiǔ yòu tiān cán jiǔ kùn.", "jīn chūn bù jiǎn qián chūn hèn.", "dié qù yīng fēi wú chǔ wèn.", "gé shuǐ gāo lóu,wàng duàn shuāng yú xìn.", "nǎo luàn céng bō héng yī cùn.", "xié yáng zhǐ yǔ huáng hūn jìn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-399','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["初拈霜纨生怅望。", "隔叶莺声，似学秦娥唱。", "午睡醒来慵一饷。", "双纹翠簟铺寒浪。", "雨罢苹风吹碧涨。", "脉脉荷花，泪脸红相向。", "斜贴绿云新月上。", "弯环正是愁眉样。"]'::jsonb,'["chū niān shuāng wán shēng chàng wàng.", "gé yè yīng shēng,shì xué qín é chàng.", "wǔ shuì xǐng lái yōng yī xiǎng.", "shuāng wén cuì diàn pù hán làng.", "yǔ bà píng fēng chuī bì zhǎng.", "mò mò hé huā,lèi liǎn hóng xiāng xiàng.", "xié tiē lǜ yún xīn yuè shàng.", "wān huán zhèng shì chóu méi yàng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-400','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["庭院碧苔红叶遍。", "金菊开时，已近重阳宴。", "日日露荷凋绿扇。", "粉塘烟水澄如练。", "试倚凉风醒酒面。", "雁字来时，恰向层楼见。", "几点护霜云影转。", "谁家芦管吹秋怨。"]'::jsonb,'["tíng yuàn bì tái hóng yè biàn.", "jīn jú kāi shí,yǐ jìn chóng yáng yàn.", "rì rì lù hé diāo lǜ shàn.", "fěn táng yān shuǐ chéng rú liàn.", "shì yǐ liáng fēng xǐng jiǔ miàn.", "yàn zì lái shí,qià xiàng céng lóu jiàn.", "jǐ diǎn hù shuāng yún yǐng zhuǎn.", "shuí jiā lú guǎn chuī qiū yuàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-401','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["喜鹊桥成催凤驾。", "天为欢迟，乞与初凉夜。", "乞巧双蛾加意画。", "玉钩斜傍西南挂。", "分钿擘钗凉叶下。", "香袖凭肩，谁记当时话。", "路隔银河犹可借。", "世间离恨何年罢。"]'::jsonb,'["xǐ què qiáo chéng cuī fèng jià.", "tiān wèi huān chí,qǐ yǔ chū liáng yè.", "qǐ qiǎo shuāng é jiā yì huà.", "yù gōu xié bàng xī nán guà.", "fēn diàn bāi chāi liáng yè xià.", "xiāng xiù píng jiān,shuí jì dāng shí huà.", "lù gé yín hé yóu kě jiè.", "shì jiān lí hèn hé nián bà."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-402','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["碧草池塘春又晚。", "小叶风娇，尚学娥妆浅。", "双燕来时还念远。", "珠帘绣户杨花满。", "绿柱频移弦易断。", "细看秦筝，正似人情短。", "一曲啼乌心绪乱。", "红颜暗与流年换。"]'::jsonb,'["bì cǎo chí táng chūn yòu wǎn.", "xiǎo yè fēng jiāo,shàng xué é zhuāng qiǎn.", "shuāng yàn lái shí hái niàn yuǎn.", "zhū lián xiù hù yáng huā mǎn.", "lǜ zhù pín yí xián yì duàn.", "xì kàn qín zhēng,zhèng shì rén qíng duǎn.", "yī qū tí wū xīn xù luàn.", "hóng yán àn yǔ liú nián huàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-403','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["碾玉钗头双凤小。", "倒晕工夫，画得宫眉巧。", "嫩曲罗裙胜碧草。", "鸳鸯绣字春衫好。", "三月露桃芳意早。", "细看花枝，人面争多少。", "水调声长歌未了。", "掌中杯尽东池晓。"]'::jsonb,'["niǎn yù chāi tóu shuāng fèng xiǎo.", "dào yūn gōng fu,huà dé gōng méi qiǎo.", "nèn qū luó qún shèng bì cǎo.", "yuān yāng xiù zì chūn shān hǎo.", "sān yuè lù táo fāng yì zǎo.", "xì kàn huā zhī,rén miàn zhēng duō shǎo.", "shuǐ diào shēng zhǎng gē wèi liǎo.", "zhǎng zhōng bēi jǐn dōng chí xiǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-404','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["醉别西楼醒不记。", "春梦秋云，聚散真容易。", "斜月半窗还少睡。", "画屏闲展吴山翠。", "衣上酒痕诗里字。", "点点行行，总是凄凉意。", "红烛自怜无好计。", "夜寒空替人垂泪。"]'::jsonb,'["zuì bié xī lóu xǐng bù jì.", "chūn mèng qiū yún,jù sàn zhēn róng yì.", "xié yuè bàn chuāng hái shǎo shuì.", "huà píng xián zhǎn wú shān cuì.", "yī shàng jiǔ hén shī lǐ zì.", "diǎn diǎn xíng xíng,zǒng shì qī liáng yì.", "hóng zhú zì lián wú hǎo jì.", "yè hán kōng tì rén chuí lèi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-405','蝶恋花',NULL,'晏几道',NULL,'宋','宋词',FALSE,'["欲减罗衣寒未去。", "不卷珠帘，人在深深处。", "残杏枝头花几许。", "啼红正恨清明雨。", "尽日沈香烟一缕。", "宿酒醒迟，恼破春情绪。", "远信还因归燕误。", "小屏风上西江路。"]'::jsonb,'["yù jiǎn luó yī hán wèi qù.", "bù juǎn zhū lián,rén zài shēn shēn chù.", "cán xìng zhī tóu huā jǐ xǔ.", "tí hóng zhèng hèn qīng míng yǔ.", "jǐn rì shěn xiāng yān yī lǚ.", "sù jiǔ xǐng chí,nǎo pò chūn qíng xù.", "yuǎn xìn hái yīn guī yàn wù.", "xiǎo píng fēng shàng xī jiāng lù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-406','苏幕遮',NULL,'范仲淹',NULL,'宋','宋词',FALSE,'["碧云天，黄叶地。", "秋色连波，波上寒烟翠。", "山映斜阳天接水。", "芳草无情，更在斜阳外。", "黯乡魂，追旅思。", "夜夜除非，好梦留人睡。", "明月楼高休独倚。", "酒入愁肠，化作相思泪。"]'::jsonb,'["bì yún tiān,huáng yè dì.", "qiū sè lián bō,bō shàng hán yān cuì.", "shān yìng xié yáng tiān jiē shuǐ.", "fāng cǎo wú qíng,gèng zài xié yáng wài.", "àn xiāng hún,zhuī lǚ sī.", "yè yè chú fēi,hǎo mèng liú rén shuì.", "míng yuè lóu gāo xiū dú yǐ.", "jiǔ rù chóu cháng,huà zuò xiāng sī lèi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-407','定风波',NULL,'范仲淹',NULL,'宋','宋词',FALSE,'["罗绮满城春欲暮。", "百花洲上寻芳去。", "浦映□花花映浦。", "无尽处。", "恍然身入桃源路。", "莫怪山翁聊逸豫。", "功名得丧归时数。", "莺解新声蝶解舞。", "天赋与。", "争教我辈无欢绪。"]'::jsonb,'["luó qǐ mǎn chéng chūn yù mù.", "bǎi huā zhōu shàng xún fāng qù.", "pǔ yìng □ huā huā yìng pǔ.", "wú jìn chù.", "huǎng rán shēn rù táo yuán lù.", "mò guài shān wēng liáo yì yù.", "gōng míng dé sàng guī shí shù.", "yīng jiě xīn shēng dié jiě wǔ.", "tiān fù yǔ.", "zhēng jiào wǒ bèi wú huān xù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-408','御街行',NULL,'范仲淹',NULL,'宋','宋词',FALSE,'["纷纷堕叶飘香砌。", "夜寂静、寒声碎。", "真珠帘卷玉楼空，天淡银河垂地。", "年年今夜，月华如练，长是人千里。", "愁肠已断无由醉。", "酒未到、先成泪。", "残灯明灭枕头欹。", "谙尽孤眠滋味。", "都来此事，眉间心上，无计相回避。"]'::jsonb,'["fēn fēn duò yè piāo xiāng qì.", "yè jì jìng,hán shēng suì.", "zhēn zhū lián juǎn yù lóu kōng,tiān dàn yín hé chuí dì.", "nián nián jīn yè,yuè huá rú liàn,zhǎng shì rén qiān lǐ.", "chóu cháng yǐ duàn wú yóu zuì.", "jiǔ wèi dào,xiān chéng lèi.", "cán dēng míng miè zhěn tou yī.", "ān jǐn gū mián zī wèi.", "dōu lái cǐ shì,méi jiān xīn shàng,wú jì xiāng huí bì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-409','剔银灯',NULL,'范仲淹',NULL,'宋','宋词',FALSE,'["昨夜因看蜀志。", "笑曹操、孙权、刘备。", "用尽机关，徒劳心力，只得三分天地。", "屈指细寻思，争如共、刘伶一醉。", "人世都无百岁。", "少痴呆、老成尩悴。", "只有中间，些子少年，忍把浮名牵系。", "一品与千金，问白发、如何回避。"]'::jsonb,'["zuó yè yīn kàn shǔ zhì.", "xiào cáo cāo,sūn quán,liú bèi.", "yòng jǐn jī guān,tú láo xīn lì,zhǐ dé sān fēn tiān dì.", "qū zhǐ xì xín sī,zhēng rú gòng,liú líng yī zuì.", "rén shì dōu wú bǎi suì.", "shǎo chī dāi,lǎo chéng wāng cuì.", "zhǐ yǒu zhōng jiān,xiē zi shào nián,rěn bǎ fú míng qiān xì.", "yī pǐn yǔ qiān jīn,wèn bái fà,rú hé huí bì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-410','渔家傲',NULL,'王安石',NULL,'宋','宋词',FALSE,'["灯火已收正月半。", "山南山北花撩乱。", "闻说洊亭新水漫。", "骑款段。", "穿云入坞寻游伴。", "却拂僧床褰素幔。", "千岩万壑春风暖。", "一弄松声悲急管。", "吹梦断。", "西看窗日犹嫌短。"]'::jsonb,'["dēng huǒ yǐ shōu zhēng yuè bàn.", "shān nán shān běi huā liáo luàn.", "wén shuō jiàn tíng xīn shuǐ màn.", "qí kuǎn duàn.", "chuān yún rù wù xún yóu bàn.", "què fú sēng chuáng qiān sù màn.", "qiān yán wàn hè chūn fēng nuǎn.", "yī nòng sōng shēng bēi jí guǎn.", "chuī mèng duàn.", "xī kàn chuāng rì yóu xián duǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-411','渔家傲',NULL,'王安石',NULL,'宋','宋词',FALSE,'["平岸小桥千嶂抱。", "柔蓝一水萦花草。", "茅屋数间窗窈窕。", "尘不到。", "时时自有春风扫。", "午枕觉来闻语鸟。", "敧眠似听朝鸡早。", "忽忆故人今总老。", "贪梦好。", "茫然忘了邯郸道。"]'::jsonb,'["píng àn xiǎo qiáo qiān zhàng bào.", "róu lán yī shuǐ yíng huā cǎo.", "máo wū shù jiān chuāng yǎo tiǎo.", "chén bú dào.", "shí shí zì yǒu chūn fēng sǎo.", "wǔ zhěn jué lái wén yǔ niǎo.", "jī mián shì tīng cháo jī zǎo.", "hū yì gù rén jīn zǒng lǎo.", "tān mèng hǎo.", "máng rán wàng le hán dān dào."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-412','西江月',NULL,'王安石',NULL,'宋','宋词',FALSE,'["梅好惟嫌淡伫，天教薄与胭脂。", "真妃初出华清池。", "酒入琼姬半醉。", "东阁诗情易动，高楼玉管休吹。", "北人浑作杏花疑。", "惟有青枝不似。"]'::jsonb,'["méi hǎo wéi xián dàn zhù,tiān jiào báo yǔ yān zhī.", "zhēn fēi chū chū huá qīng chí.", "jiǔ rù qióng jī bàn zuì.", "dōng gé shī qíng yì dòng,gāo lóu yù guǎn xiū chuī.", "běi rén hún zuò xìng huā yí.", "wéi yǒu qīng zhī bù shì."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-413','清平乐',NULL,'王安石',NULL,'宋','宋词',FALSE,'["云垂平野。", "掩映竹篱茅舍。", "阒寂幽居实潇洒。", "是处绿娇红冶。", "丈夫运用堂堂。", "且莫五角六张。", "若有一卮芳酒，逍遥自在无妨。"]'::jsonb,'["yún chuí píng yě.", "yǎn yìng zhú lí máo shè.", "qù jì yōu jū shí xiāo sǎ.", "shì chù lǜ jiāo hóng yě.", "zhàng fū yùn yòng táng táng.", "qiě mò wǔ jiǎo liù zhāng.", "ruò yǒu yī zhī fāng jiǔ,xiāo yáo zì zài wú fáng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-414','清平乐',NULL,'王安石',NULL,'宋','宋词',FALSE,'["留春不住。", "费尽莺儿语。", "满地残红宫锦污。", "昨夜南园风雨。", "小怜初上琵琶。", "晓来思绕天涯。", "不肯画堂朱户，春风自在杨花。"]'::jsonb,'["liú chūn bú zhù.", "fèi jǐn yīng ér yǔ.", "mǎn dì cán hóng gōng jǐn wū.", "zuó yè nán yuán fēng yǔ.", "xiǎo lián chū shàng pí pá.", "xiǎo lái sī rào tiān yá.", "bù kěn huà táng zhū hù,chūn fēng zì zài yáng huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-415','菩萨蛮',NULL,'王安石',NULL,'宋','宋词',FALSE,'["数家茅屋闲临水。", "单衫短帽垂杨里。", "今日是何朝。", "看予度石桥。", "梢梢新月偃。", "午醉醒来晚。", "何物最关情。", "黄鹂三两声。"]'::jsonb,'["shù jiā máo wū xián lín shuǐ.", "dān shān duǎn mào chuí yáng lǐ.", "jīn rì shì hé cháo.", "kàn yǔ dù shí qiáo.", "shāo shāo xīn yuè yǎn.", "wǔ zuì xǐng lái wǎn.", "hé wù zuì guān qíng.", "huáng lí sān liǎng shēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-416','菩萨蛮',NULL,'王安石',NULL,'宋','宋词',FALSE,'["海棠乱发皆临水。", "君知此处花何似。", "凉月白纷纷。", "香风隔岸闻。", "啭枝黄鸟近。", "隔岸声相应。", "随意坐莓苔。", "飘零酒一杯。"]'::jsonb,'["hǎi táng luàn fà jiē lín shuǐ.", "jūn zhī cǐ chù huā hé shì.", "liáng yuè bái fēn fēn.", "xiāng fēng gé àn wén.", "zhuàn zhī huáng niǎo jìn.", "gé àn shēng xiāng yìng.", "suí yì zuò méi tái.", "piāo líng jiǔ yī bēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-417','浣溪沙',NULL,'王安石',NULL,'宋','宋词',FALSE,'["百亩中庭半是苔。", "门前白道水萦回。", "爱闲能有几人来。", "小院回廊春寂寂，山桃溪杏两三栽。", "为谁零落为谁开。"]'::jsonb,'["bǎi mǔ zhōng tíng bàn shì tái.", "mén qián bái dào shuǐ yíng huí.", "ài xián néng yǒu jǐ rén lái.", "xiǎo yuàn huí láng chūn jì jì,shān táo xī xìng liǎng sān zāi.", "wèi shuí líng luò wèi shuí kāi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-418','渔家傲',NULL,'王安石',NULL,'宋','宋词',FALSE,'["隔岸桃花红未半。", "枝头已有蜂儿乱。", "惆怅武陵人不管。", "清梦断。", "亭亭伫立春宵短。"]'::jsonb,'["gé àn táo huā hóng wèi bàn.", "zhī tóu yǐ yǒu fēng ér luàn.", "chóu chàng wǔ líng rén bù guǎn.", "qīng mèng duàn.", "tíng tíng zhù lì chūn xiāo duǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-419','苏幕遮',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["燎沈香，消溽暑。", "鸟雀呼晴，侵晓窥檐语。", "叶上初阳干宿雨，水面清圆，一一风荷举。", "故乡遥，何日去。", "家住吴门，久作长安旅。", "五月渔郎相忆否。", "小楫轻舟，梦入芙蓉浦。"]'::jsonb,'["liáo shěn xiāng,xiāo rù shǔ.", "niǎo què hū qíng,qīn xiǎo kuī yán yǔ.", "yè shàng chū yáng gàn sù yǔ,shuǐ miàn qīng yuán,yī yī fēng hé jǔ.", "gù xiāng yáo,hé rì qù.", "jiā zhù wú mén,jiǔ zuò cháng ān lǚ.", "wǔ yuè yú láng xiāng yì fǒu.", "xiǎo jí qīng zhōu,mèng rù fú róng pǔ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-420','渔家傲',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["灰暖香融销永昼。", "蒲萄架上春藤秀。", "曲角栏干群雀斗。", "清明后。", "风梳万缕亭前柳。", "日照钗梁光欲溜。", "循阶竹粉沾衣袖。", "拂拂面红如著酒。", "沈吟久。", "昨宵正是来时候。"]'::jsonb,'["huī nuǎn xiāng róng xiāo yǒng zhòu.", "pú táo jià shàng chūn téng xiù.", "qū jiǎo lán gān qún què dòu.", "qīng míng hòu.", "fēng shū wàn lǚ tíng qián liǔ.", "rì zhào chāi liáng guāng yù liū.", "xún jiē zhú fěn zhān yī xiù.", "fú fú miàn hóng rú zhù jiǔ.", "shěn yín jiǔ.", "zuó xiāo zhèng shì lái shí hòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-421','渔家傲',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["几日轻阴寒测测。", "东风急处花成积。", "醉踏阳春怀故国。", "归未得。", "黄鹂久住如相识。", "赖有蛾眉能暖客。", "长歌屡劝金杯侧。", "歌罢月痕来照席。", "贪欢适。", "帘前重露成涓滴。"]'::jsonb,'["jǐ rì qīng yīn hán cè cè.", "dōng fēng jí chù huā chéng jī.", "zuì tà yáng chūn huái gù guó.", "guī wèi dé.", "huáng lí jiǔ zhù rú xiāng shí.", "lài yǒu é méi néng nuǎn kè.", "zhǎng gē lǚ quàn jīn bēi cè.", "gē bà yuè hén lái zhào xí.", "tān huān shì.", "lián qián zhòng lù chéng juān dī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-422','蝶恋花',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["月皎惊乌栖不定。", "更漏将残，𫐆辘，牵金井。", "唤起两眸清炯炯。", "泪花落枕红棉泠。", "执手霜风吹鬓影。", "去意徊徨，别语愁难听。", "楼上阑干横斗柄。", "露寒人远鸡相应。"]'::jsonb,'["yuè jiǎo jīng wū qī bù dìng.", "gèng lòu jiāng cán,kuài lù,qiān jīn jǐng.", "huàn qǐ liǎng móu qīng jiǒng jiǒng.", "lèi huā lào zhěn hóng mián líng.", "zhí shǒu shuāng fēng chuī bìn yǐng.", "qù yì huái huáng,bié yǔ chóu nán tīng.", "lóu shàng lán gān héng dòu bǐng.", "lù hán rén yuǎn jī xiāng yìng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-423','蝶恋花',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["爱日轻明新雪后。", "柳眼星星，渐欲穿窗牖。", "不待长亭倾别酒。", "一枝已入骚人手。", "浅浅挼蓝轻蜡透。", "过尽冰霜，便与春争秀。", "强对青铜簪白首。", "老来风味难依旧。"]'::jsonb,'["ài rì qīng míng xīn xuě hòu.", "liǔ yǎn xīng xīng,jiàn yù chuān chuāng yǒu.", "bù dài cháng tíng qīng bié jiǔ.", "yī zhī yǐ rù sāo rén shǒu.", "qiǎn qiǎn ruá lán qīng là tòu.", "guò jǐn bīng shuāng,biàn yǔ chūn zhēng xiù.", "qiáng duì qīng tóng zān bái shǒu.", "lǎo lái fēng wèi nán yī jiù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-424','蝶恋花',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["桃萼新香梅落后。", "暗叶藏鸦，苒苒垂亭牖。", "舞困低迷如著酒。", "乱丝偏近游人手。", "雨过朦胧斜日透。", "客舍青青，特地添明秀。", "莫话扬鞭回别首。", "渭城荒远无交旧。"]'::jsonb,'["táo è xīn xiāng méi luò hòu.", "àn yè cáng yā,rǎn rǎn chuí tíng yǒu.", "wǔ kùn dī mí rú zhù jiǔ.", "luàn sī piān jìn yóu rén shǒu.", "yǔ guò méng lóng xié rì tòu.", "kè shě qīng qīng,tè dì tiān míng xiù.", "mò huà yáng biān huí bié shǒu.", "wèi chéng huāng yuǎn wú jiāo jiù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-425','蝶恋花',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["蠢蠢黄金初脱后。", "暖日飞绵，取次粘窗牖。", "不见长条低拂酒。", "赠行应已输先手。", "莺掷金梭飞不透。", "小榭危楼，处处添奇秀。", "何日隋堤萦马首。", "路长人倦空思旧。"]'::jsonb,'["chǔn chǔn huáng jīn chū tuō hòu.", "nuǎn rì fēi mián,qǔ cì zhān chuāng yǒu.", "bú jiàn cháng tiáo dī fú jiǔ.", "zèng xíng yīng yǐ shū xiān shǒu.", "yīng zhì jīn suō fēi bù tòu.", "xiǎo xiè wēi lóu,chù chù tiān qí xiù.", "hé rì suí dī yíng mǎ shǒu.", "lù zhǎng rén juàn kōng sī jiù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-426','蝶恋花',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["小阁阴阴人寂后。", "翠幕褰风，烛影摇疏牖。", "夜半霜寒初索酒。", "金刀正在柔荑手。", "彩薄粉轻光欲透。", "小叶尖新，未放双眉秀。", "记得长条垂鹢首。", "别离情味还依旧。"]'::jsonb,'["xiǎo gé yīn yīn rén jì hòu.", "cuì mù qiān fēng,zhú yǐng yáo shū yǒu.", "yè bàn shuāng hán chū suǒ jiǔ.", "jīn dāo zhèng zài róu tí shǒu.", "cǎi báo fěn qīng guāng yù tòu.", "xiǎo yè jiān xīn,wèi fàng shuāng méi xiù.", "jì de cháng tiáo chuí yì shǒu.", "bié lí qíng wèi hái yī jiù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-427','定风波',NULL,'周邦彦',NULL,'宋','宋词',FALSE,'["莫倚能歌敛黛眉。", "此歌能有几人知。", "他日相逢花月底。", "重理。", "好声须记得来时。", "苦恨城头更漏永，无情岂解惜分飞。", "休诉金尊推玉臂。", "从醉。", "明朝有酒遣谁持。"]'::jsonb,'["mò yǐ néng gē liǎn dài méi.", "cǐ gē néng yǒu jǐ rén zhī.", "tā rì xiāng féng huā yuè dǐ.", "zhòng lǐ.", "hǎo shēng xū jì de lái shí.", "kǔ hèn chéng tóu gèng lòu yǒng,wú qíng qǐ jiě xī fēn fēi.", "xiū sù jīn zūn tuī yù bì.", "cóng zuì.", "míng cháo yǒu jiǔ qiǎn shuí chí."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-428','虞美人',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["西园曾为梅花醉。", "叶翦春云细。", "玉笙凉夜隔帘吹。", "卧看花梢摇动、一枝枝。", "娉娉袅袅教谁惜。", "空压纱巾侧。", "沈香亭北又青苔。", "唯有当时蝴蝶、自飞来。"]'::jsonb,'["xī yuán céng wèi méi huā zuì.", "yè jiǎn chūn yún xì.", "yù shēng liáng yè gé lián chuī.", "wò kàn huā shāo yáo dòng,yī zhī zhī.", "pīng pīng niǎo niǎo jiào shuí xī.", "kōng yā shā jīn cè.", "shěn xiāng tíng běi yòu qīng tái.", "wéi yǒu dāng shí hú dié,zì fēi lái."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-429','虞美人',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["摩挲紫盖峰头石。", "上瞰苍崖立。", "玉盘摇动半崖花。", "花树扶蔬、一半白云遮。", "盈盈相望无由摘。", "惆怅归来屐。", "而今仙迹杳难寻。", "那日青楼、曾见似花人。"]'::jsonb,'["mā sā zǐ gài fēng tóu shí.", "shàng kàn cāng yá lì.", "yù pán yáo dòng bàn yá huā.", "huā shù fú shū,yí bàn bái yún zhē.", "yíng yíng xiāng wàng wú yóu zhāi.", "chóu chàng guī lái jī.", "ér jīn xiān jì yǎo nán xún.", "nà rì qīng lóu,céng jiàn shì huā rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-430','虞美人',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["阑干表立苍龙背。", "三面巉天翠。", "东游才上小蓬莱。", "不见此楼烟雨、未应回。", "而今指点来时路。", "却是冥蒙处。", "老仙鹤驭几时归。", "未必山川城郭、是耶非。"]'::jsonb,'["lán gān biǎo lì cāng lóng bèi.", "sān miàn chán tiān cuì.", "dōng yóu cái shàng xiǎo péng lái.", "bú jiàn cǐ lóu yān yǔ,wèi yīng huí.", "ér jīn zhǐ diǎn lái shí lù.", "què shì míng méng chù.", "lǎo xiān hè yù jǐ shí guī.", "wèi bì shān chuān chéng guō,shì yé fēi."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-431','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["江左咏梅人，梦绕青青路。", "因向凌风台下看，心事还将与。", "忆别庾郎时，又过林逋处。", "万古西湖寂寞春，惆怅谁能赋。"]'::jsonb,'["jiāng zuǒ yǒng méi rén,mèng rào qīng qīng lù.", "yīn xiàng líng fēng tái xià kàn,xīn shì hái jiāng yǔ.", "yì bié yǔ láng shí,yòu guò lín bū chù.", "wàn gǔ xī hú jì mò chūn,chóu chàng shuí néng fù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-432','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["月上海云沈，鸥去吴波回。", "行过西泠有一枝，竹暗人家静。", "又见水沈亭，举目悲风景。", "花下铺毡把一杯，缓饮春风影。"]'::jsonb,'["yuè shàng hǎi yún shěn,ōu qù wú bō huí.", "xíng guò xī líng yǒu yī zhī,zhú àn rén jiā jìng.", "yòu jiàn shuǐ shěn tíng,jǔ mù bēi fēng jǐng.", "huā xià pù zhān bǎ yī bēi,huǎn yǐn chūn fēng yǐng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-433','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["藓干石斜妨，玉蕊松低覆。", "日暮冥冥一见来，略比年时瘦。", "凉观酒初醒，竹阁吟才就。", "犹恨幽香作许悭，小迟春心透。"]'::jsonb,'["xiǎn gàn shí xié fáng,yù ruǐ sōng dī fù.", "rì mù míng míng yī jiàn lái,lüè bǐ nián shí shòu.", "liáng guān jiǔ chū xǐng,zhú gé yín cái jiù.", "yóu hèn yōu xiāng zuò xǔ qiān,xiǎo chí chūn xīn tòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-434','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["家在马城西，今赋梅屏雪。", "梅雪相兼不见花，月影玲珑彻。", "前度带愁看，一饷和愁折。", "若使逋仙及见之，定自成愁绝。"]'::jsonb,'["jiā zài mǎ chéng xī,jīn fù méi píng xuě.", "méi xuě xiāng jiān bú jiàn huā,yuè yǐng líng lóng chè.", "qián dù dài chóu kàn,yī xiǎng hé chóu zhé.", "ruò shǐ bū xiān jí jiàn zhī,dìng zì chéng chóu jué."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-435','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["摘蕊暝禽飞，倚树悬冰落。", "下竺桥边浅立时，香已漂流却。", "空径晚烟平，古寺春寒恶。", "老子寻花第一番，常恐吴儿觉。"]'::jsonb,'["zhāi ruǐ míng qín fēi,yǐ shù xuán bīng luò.", "xià zhú qiáo biān qiǎn lì shí,xiāng yǐ piāo liú què.", "kōng jìng wǎn yān píng,gǔ sì chūn hán è.", "lǎo zi xún huā dì yī fān,cháng kǒng wú ér jué."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-436','卜算子',NULL,'姜夔',NULL,'宋','宋词',FALSE,'["绿萼更横枝，多少梅花样。", "惆怅西村一坞春，开遍无人赏。", "细草藉金舆，岁岁长吟想。", "枝上么禽一两声，犹似宫娥唱。"]'::jsonb,'["lǜ è gèng héng zhī,duō shǎo méi huā yàng.", "chóu chàng xī cūn yī wù chūn,kāi biàn wú rén shǎng.", "xì cǎo jí jīn yú,suì suì cháng yín xiǎng.", "zhī shàng me qín yī liǎng shēng,yóu shì gōng é chàng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-437','渔家傲',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["莫厌香醪斟绣履。", "吐茵也是风流事。", "今夜夜寒愁不睡。", "披衣起。", "挑灯开卷花生纸。", "倩问尊前桃与李。", "重来若个犹相记。", "前度刘郎应老矣。", "行乐地。", "兔葵燕麦春风里。"]'::jsonb,'["mò yàn xiāng láo zhēn xiù lǚ.", "tǔ yīn yě shì fēng liú shì.", "jīn yè yè hán chóu bù shuì.", "pī yī qǐ.", "tiǎo dēng kāi juàn huā shēng zhǐ.", "qiàn wèn zūn qián táo yǔ lǐ.", "zhòng lái ruò gè yóu xiāng jì.", "qián dù liú láng yīng lǎo yǐ.", "xíng lè dì.", "tù kuí yàn mài chūn fēng lǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-438','蝶恋花',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["小院朱扉开一扇。", "内样新妆，镜里分明见。", "眉晕半深唇注浅。", "朵云冠子偏宜面。", "被掩芙蓉熏麝煎。", "帘影沈沈，祗有双飞燕。", "心事向人犹腼腆。", "强来窗下寻针线。"]'::jsonb,'["xiǎo yuàn zhū fēi kāi yī shàn.", "nèi yàng xīn zhuāng,jìng lǐ fēn míng jiàn.", "méi yūn bàn shēn chún zhù qiǎn.", "duǒ yún guān zi piān yí miàn.", "bèi yǎn fú róng xūn shè jiān.", "lián yǐng shěn shěn,zhī yǒu shuāng fēi yàn.", "xīn shì xiàng rén yóu miǎn tiǎn.", "qiáng lái chuāng xià xún zhēn xiàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-439','蝶恋花',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["几许伤春春复暮。", "杨柳清阴，偏碍游丝度。", "天际小山桃叶步。", "白苹花满湔裙处。", "竟日微吟长短句。", "帘影灯昏，心寄胡琴语。", "数点雨声风约住。", "朦胧淡月云来去。"]'::jsonb,'["jǐ xǔ shāng chūn chūn fù mù.", "yáng liǔ qīng yīn,piān ài yóu sī dù.", "tiān jì xiǎo shān táo yè bù.", "bái píng huā mǎn jiān qún chù.", "jìng rì wēi yín cháng duǎn jù.", "lián yǐng dēng hūn,xīn jì hú qín yǔ.", "shù diǎn yǔ shēng fēng yuē zhù.", "méng lóng dàn yuè yún lái qù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-440','虞美人',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["粉娥齐敛千金笑。", "愁结眉峰小。", "渭城才唱浥轻尘。", "无奈两行红泪、湿香巾。", "伤心风月南城道。", "几纵朱轓到。", "明年载酒洛阳春。", "还念淮山楼上、倚阑人。"]'::jsonb,'["fěn é qí liǎn qiān jīn xiào.", "chóu jié méi fēng xiǎo.", "wèi chéng cái chàng yì qīng chén.", "wú nài liǎng xíng hóng lèi,shī xiāng jīn.", "shāng xīn fēng yuè nán chéng dào.", "jǐ zòng zhū fān dào.", "míng nián zài jiǔ luò yáng chūn.", "hái niàn huái shān lóu shàng,yǐ lán rén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-441','江城子',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["麝熏微度绣芙蓉。", "翠衾重。", "画堂空。", "前夜偷期，相见却匆匆。", "心事两知何处问，依约是，梦中逢。", "坐疑行听竹窗风。", "出帘栊。", "杳无踪。", "已过黄昏，缠动寺楼钟。", "暮雨不来春又去，花满地，月朦胧。"]'::jsonb,'["shè xūn wēi dù xiù fú róng.", "cuì qīn zhòng.", "huà táng kōng.", "qián yè tōu qī,xiāng jiàn què cōng cōng.", "xīn shì liǎng zhī hé chù wèn,yī yuē shì,mèng zhōng féng.", "zuò yí xíng tīng zhú chuāng fēng.", "chū lián lóng.", "yǎo wú zōng.", "yǐ guò huáng hūn,chán dòng sì lóu zhōng.", "mù yǔ bù lái chūn yòu qù,huā mǎn dì,yuè méng lóng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-442','浪淘沙',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["一叶忽惊秋。", "分付东流。", "殷勤为过白苹洲。", "洲上小楼帘半卷，应认归舟。", "回首恋朋游。", "迹去心留。", "歌尘萧散梦云收。", "惟有尊前曾见月，相伴人愁。"]'::jsonb,'["yī yè hū jīng qiū.", "fēn fù dōng liú.", "yīn qín wèi guò bái píng zhōu.", "zhōu shàng xiǎo lóu lián bàn juǎn,yīng rèn guī zhōu.", "huí shǒu liàn péng yóu.", "jì qù xīn liú.", "gē chén xiāo sàn mèng yún shōu.", "wéi yǒu zūn qián céng jiàn yuè,xiāng bàn rén chóu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-443','浪淘沙',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["把酒欲歌骊。", "浓醉何辞。", "玉京烟柳欲黄时。", "明日景阳门外路，相背春归。", "敛泪复牵衣。", "私语迟迟。", "可怜谁会两心期。", "惟有画帘斜月见，应共人知。"]'::jsonb,'["bǎ jiǔ yù gē lí.", "nóng zuì hé cí.", "yù jīng yān liǔ yù huáng shí.", "míng rì jǐng yáng mén wài lù,xiāng bèi chūn guī.", "liǎn lèi fù qiān yī.", "sī yǔ chí chí.", "kě lián shuí huì liǎng xīn qī.", "wéi yǒu huà lián xié yuè jiàn,yīng gòng rén zhī."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-444','浪淘沙',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["一十二都门。", "梦想能频。", "无言桃李几经春。", "艳粉鲜香开自落，还为何人。", "白纻别时新。", "苒苒征尘。", "镜中消瘦老于真。", "赖有天涯风月在，依旧相亲。"]'::jsonb,'["yī shí èr dōu mén.", "mèng xiǎng néng pín.", "wú yán táo lǐ jǐ jīng chūn.", "yàn fěn xiān xiāng kāi zì luò,hái wèi hé rén.", "bái zhù bié shí xīn.", "rǎn rǎn zhēng chén.", "jìng zhōng xiāo shòu lǎo yú zhēn.", "lài yǒu tiān yá fēng yuè zài,yī jiù xiāng qīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-445','浪淘沙',NULL,'贺铸',NULL,'宋','宋词',FALSE,'["潮涨湛芳桥。", "难渡兰桡。", "卷帘红袖莫相招。", "十二阑干今夜月，谁伴吹箫。", "烟草接亭皋。", "归思迢迢。", "兰成老去转无憀。", "偏恨秋风添鬓雪，不共魂销。"]'::jsonb,'["cháo zhǎng zhàn fāng qiáo.", "nán dù lán ráo.", "juàn lián hóng xiù mò xiāng zhāo.", "shí èr lán gān jīn yè yuè,shuí bàn chuī xiāo.", "yān cǎo jiē tíng gāo.", "guī sī tiáo tiáo.", "lán chéng lǎo qù zhuǎn wú liáo.", "piān hèn qiū fēng tiān bìn xuě,bù gòng hún xiāo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-446','苏幕遮',NULL,'张先',NULL,'宋','宋词',FALSE,'["柳飞绵，花实少。", "镂板音清，浅发江南调。", "斜日两竿留碧□。", "马足重重，又近青门道。", "去尘浓，人散了。", "回首旗亭，渐渐红裳小。", "莫讶安仁头白早。", "天若有情，天也终须老。"]'::jsonb,'["liǔ fēi mián,huā shí shǎo.", "lòu bǎn yīn qīng,qiǎn fā jiāng nán diào.", "xié rì liǎng gān liú bì □.", "mǎ zú chóng chóng,yòu jìn qīng mén dào.", "qù chén nóng,rén sàn le.", "huí shǒu qí tíng,jiàn jiàn hóng shang xiǎo.", "mò yà ān rén tóu bái zǎo.", "tiān ruò yǒu qíng,tiān yě zhōng xū lǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-447','定风波',NULL,'张先',NULL,'宋','宋词',FALSE,'["素藕抽条未放莲。", "晚蚕将茧不成眠。", "若比相思如乱絮。", "何异。", "两心俱被暗丝牵。", "暂觉欲归还是恨。", "莫问。", "有情谁信道无缘。", "有似中秋云外月。", "皎洁。", "不团圆待几时圆。"]'::jsonb,'["sù ǒu chōu tiáo wèi fàng lián.", "wǎn cán jiāng jiǎn bù chéng mián.", "ruò bǐ xiāng sī rú luàn xù.", "hé yì.", "liǎng xīn jù bèi àn sī qiān.", "zàn jué yù guī huán shì hèn.", "mò wèn.", "yǒu qíng shuí xìn dào wú yuán.", "yǒu shì zhōng qiū yún wài yuè.", "jiǎo jié.", "bù tuán yuán dài jǐ shí yuán."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-448','渔家傲',NULL,'张先',NULL,'宋','宋词',FALSE,'["巴子城头青草暮。", "巴山重叠相逢处。", "燕子占巢花脱树。", "杯且举。", "瞿塘水阔舟难渡。", "天外吴门清霅路。", "君家正在吴门住。", "赠我柳枝情几许。", "春满缕。", "为君将入江南去。"]'::jsonb,'["bā zi chéng tóu qīng cǎo mù.", "bā shān chóng dié xiāng féng chù.", "yàn zi zhàn cháo huā tuō shù.", "bēi qiě jǔ.", "qú táng shuǐ kuò zhōu nán dù.", "tiān wài wú mén qīng zhà lù.", "jūn jiā zhèng zài wú mén zhù.", "zèng wǒ liǔ zhī qíng jǐ xǔ.", "chūn mǎn lǚ.", "wèi jūn jiāng rù jiāng nán qù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-449','蝶恋花',NULL,'张先',NULL,'宋','宋词',FALSE,'["临水人家深宅院。", "阶下残花，门外斜阳岸。", "柳舞曲尘千万线。", "青楼百尺临天半。", "楼上东风春不浅。", "十二阑干，尽日珠帘卷。", "有个离人凝泪眼。", "淡烟芳草连云远。"]'::jsonb,'["lín shuǐ rén jiā shēn zhái yuàn.", "jiē xià cán huā,mén wài xié yáng àn.", "liǔ wǔ qǔ chén qiān wàn xiàn.", "qīng lóu bǎi chǐ lín tiān bàn.", "lóu shàng dōng fēng chūn bù qiǎn.", "shí èr lán gān,jǐn rì zhū lián juǎn.", "yǒu gè lí rén níng lèi yǎn.", "dàn yān fāng cǎo lián yún yuǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-450','蝶恋花',NULL,'张先',NULL,'宋','宋词',FALSE,'["槛菊愁烟兰泣露。", "罗幕轻寒，燕子双来去。", "明月不谙离恨苦。", "斜光到晓穿朱户。", "昨夜西风雕碧树。", "独上高楼，望尽天涯路。", "欲寄彩笺兼尺素。", "山长水阔知何处。"]'::jsonb,'["kǎn jú chóu yān lán qì lù.", "luó mù qīng hán,yàn zi shuāng lái qù.", "míng yuè bù ān lí hèn kǔ.", "xié guāng dào xiǎo chuān zhū hù.", "zuó yè xī fēng diāo bì shù.", "dú shàng gāo lóu,wàng jǐn tiān yá lù.", "yù jì cǎi jiān jiān chǐ sù.", "shān cháng shuǐ kuò zhī hé chù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-451','蝶恋花',NULL,'张先',NULL,'宋','宋词',FALSE,'["绿水波平花烂漫。", "照影红妆，步转垂杨岸。", "别后深情将为断。", "相逢添得人留恋。", "絮软丝轻无系绊。", "烟惹风迎，并入春心乱。", "和泪语娇声又颤。", "行行尽远犹回面。"]'::jsonb,'["lǜ shuǐ bō píng huā làn màn.", "zhào yǐng hóng zhuāng,bù zhuǎn chuí yáng àn.", "bié hòu shēn qíng jiāng wèi duàn.", "xiāng féng tiān dé rén liú liàn.", "xù ruǎn sī qīng wú xì bàn.", "yān rě fēng yíng,bìng rù chūn xīn luàn.", "hé lèi yǔ jiāo shēng yòu chàn.", "xíng xíng jǐn yuǎn yóu huí miàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-452','蝶恋花',NULL,'张先',NULL,'宋','宋词',FALSE,'["移得绿杨栽后院。", "学舞宫腰，二月青犹短。", "不比灞陵多送远。", "残丝乱絮东西岸。", "几叶小眉寒不展。", "莫唱阳关，真个肠先断。", "分付与春休细看。", "条条尽是离人怨。"]'::jsonb,'["yí dé lǜ yáng zāi hòu yuàn.", "xué wǔ gōng yāo,èr yuè qīng yóu duǎn.", "bù bǐ bà líng duō sòng yuǎn.", "cán sī luàn xù dōng xī àn.", "jǐ yè xiǎo méi hán bù zhǎn.", "mò chàng yáng guān,zhēn gè cháng xiān duàn.", "fēn fù yǔ chūn xiū xì kàn.", "tiáo tiáo jìn shì lí rén yuàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-453','天仙子',NULL,'张先',NULL,'宋','宋词',FALSE,'["水调数声持酒听。", "午醉醒来愁未醒。", "送春春去几时回，临晚镜。", "伤流景。", "往事后期空记省。", "沙上并禽池上暝。", "云破月来花弄影。", "重重帘幕密遮灯，风不定。", "人初静。", "明日落红应满径。"]'::jsonb,'["shuǐ diào shù shēng chí jiǔ tīng.", "wǔ zuì xǐng lái chóu wèi xǐng.", "sòng chūn chūn qù jǐ shí huí,lín wǎn jìng.", "shāng liú jǐng.", "wǎng shì hòu qī kōng jì shěng.", "shā shàng bìng qín chí shàng míng.", "yún pò yuè lái huā nòng yǐng.", "chóng chóng lián mù mì zhē dēng,fēng bù dìng.", "rén chū jìng.", "míng rì luò hóng yīng mǎn jìng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-454','天仙子',NULL,'张先',NULL,'宋','宋词',FALSE,'["持节来时初有雁。", "十万人家春已满。", "龙标名第凤池身，堂阜远。", "江桥晚。", "一见湖山看未遍。", "障扇欲收歌泪溅。", "亭下花空罗绮散。", "樯竿渐向望中疏，旗影转。", "鼙声断。", "惆怅不如船尾燕。"]'::jsonb,'["chí jié lái shí chū yǒu yàn.", "shí wàn rén jiā chūn yǐ mǎn.", "lóng biāo míng dì fèng chí shēn,táng fù yuǎn.", "jiāng qiáo wǎn.", "yī jiàn hú shān kàn wèi biàn.", "zhàng shàn yù shōu gē lèi jiàn.", "tíng xià huā kōng luó qǐ sàn.", "qiáng gān jiàn xiàng wàng zhōng shū,qí yǐng zhuǎn.", "pí shēng duàn.", "chóu chàng bù rú chuán wěi yàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-455','越调・天净沙秋思',NULL,'马致远',NULL,'元','元曲',FALSE,'["枯藤老树昏鸦，小桥流水人家，古道西风瘦马。", "夕阳西下，断肠人在天涯。"]'::jsonb,'["kū téng lǎo shù hūn yā,xiǎo qiáo liú shuǐ rén jiā,gǔ dào xī fēng shòu mǎ.", "xī yáng xī xià,duàn cháng rén zài tiān yá."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-456','南吕・四块玉别情',NULL,'关汉卿',NULL,'元','元曲',FALSE,'["自送别，心难舍，一点相思几时绝？凭阑袖拂杨花雪。", "溪又斜，山又遮，人去也！。"]'::jsonb,'["zì sòng bié,xīn nán shě,yì diǎn xiāng sī jǐ shí jué?píng lán xiù fú yáng huā xuě.", "xī yòu xié,shān yòu zhē,rén qù yě!."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-457','双调・雁儿落兼清江引',NULL,'张养浩',NULL,'元','元曲',FALSE,'["喜山林眼界高，嫌市井人烟闹。", "过中年便退官，再不想长安道。", "绰然一亭尘世表，不许俗人到。", "四面桑麻深，一带云山妙，这一塔儿快活直到老。"]'::jsonb,'["xǐ shān lín yǎn jiè gāo,xián shì jǐng rén yān nào.", "guò zhōng nián biàn tuì guān,zài bù xiǎng cháng ān dào.", "chuò rán yī tíng chén shì biǎo,bù xǔ sú rén dào.", "sì miàn sāng má shēn,yī dài yún shān miào,zhè yī tǎ ér kuài huó zhí dào lǎo."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-458','双调・得胜令四月一日喜雨',NULL,'张养浩',NULL,'元','元曲',FALSE,'["万象欲焦枯，一雨足沾濡。", "天地回生意，风云起壮图。", "农夫，舞破蓑衣绿。", "和余，欢喜的无是处！。"]'::jsonb,'["wàn xiàng yù jiāo kū,yī yǔ zú zhān rú.", "tiān dì huí shēng yì,fēng yún qǐ zhuàng tú.", "nóng fū,wǔ pò suō yī lǜ.", "hé yú,huān xǐ de wú shì chù!."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-459','正宫・塞鸿秋',NULL,'张养浩',NULL,'元','元曲',FALSE,'["春来时绰然亭香雪梨花会，夏来时绰然亭云锦荷花会，秋来时绰然亭霜露黄花会，冬天时绰然亭风月梅花会。", "春夏与秋冬，四季皆佳会，主人此意谁能会？。"]'::jsonb,'["chūn lái shí chuò rán tíng xiāng xuě lí huā huì,xià lái shí chuò rán tíng yún jǐn hé huā huì,qiū lái shí chuò rán tíng shuāng lù huáng huā huì,dōng tiān shí chuò rán tíng fēng yuè méi huā huì.", "chūn xià yǔ qiū dōng,sì jì jiē jiā huì,zhǔ rén cǐ yì shuí néng huì?."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-460','越调・天净沙',NULL,'张养浩',NULL,'元','元曲',FALSE,'["昨朝杨柳依依，今朝雨雪霏霏，社燕秋鸿忒疾。", "若不是浊醪有味，怎消磨这日月东西。", "年时尚觉平安，今年陡恁衰残，更着十年试看。", "烟消云散，一杯谁共歌欢？休言咱是谁非，只宜似醉如痴，便得功名待怎的？无穷无地，那驼儿用你精细？。"]'::jsonb,'["zuó cháo yáng liǔ yī yī,jīn zhāo yǔ xuě fēi fēi,shè yàn qiū hóng tè jí.", "ruò bú shì zhuó láo yǒu wèi,zěn xiāo mó zhè rì yuè dōng xī.", "nián shí shàng jué píng ān,jīn nián dǒu nèn shuāi cán,gèng zhe shí nián shì kàn.", "yān xiāo yún sàn,yī bēi shuí gòng gē huān?xiū yán zán shì shuí fēi,zhǐ yí sì zuì rú chī,biàn dé gōng míng dài zěn de?wú qióng wú dì,nà tuó ér yòng nǐ jīng xì?."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-461','中吕・红绣鞋赠美妓',NULL,'张养浩',NULL,'元','元曲',FALSE,'["手掌儿血喷粉哨，指甲儿玉碾琼雕，子见他怀擎玛瑙泛香醪。", "眼睛儿冷丢溜，话头儿热剔选，把一个李谪仙险醉倒。", "荼コ院风香雪霁，海棠轩绿绕红围，他便似碧桃花映粉墙西。", "梨花云春淡荡，杨柳雾晓凄迷，把一个陶学土险爱死。", "套数。"]'::jsonb,'["shǒu zhǎng ér xuè pēn fěn shào,zhǐ jiǎ ér yù niǎn qióng diāo,zi jiàn tā huái qíng mǎ nǎo fàn xiāng láo.", "yǎn jīng ér lěng diū liū,huà tóu ér rè tī xuǎn,bǎ yí gè lǐ zhé xiān xiǎn zuì dào.", "tú コ yuàn fēng xiāng xuě jì,hǎi táng xuān lǜ rào hóng wéi,tā biàn shì bì táo huā yìng fěn qiáng xī.", "lí huā yún chūn dàn dàng,yáng liǔ wù xiǎo qī mí,bǎ yí gè táo xué tǔ xiǎn ài sǐ.", "tào shù."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-462','南吕・四块玉闲居',NULL,'张可久',NULL,'元','元曲',FALSE,'["胜事添，殿尘减，玉洞仙书带云缄，金华羽士登门探。", "酒一坛，药几篮，经半龛。", "春情酒易阑，愁难解，杏脸香销玉妆台，柳腰宽褪罗裙带。", "春已归，花又开，人未来。", "乐闲远是非，寻潇洒，地暖江南燕宜家，人闲水北春无价。", "一品茶，五色瓜，四季花。"]'::jsonb,'["shèng shì tiān,diàn chén jiǎn,yù dòng xiān shū dài yún jiān,jīn huá yǔ shì dēng mén tàn.", "jiǔ yī tán,yào jǐ lán,jīng bàn kān.", "chūn qíng jiǔ yì lán,chóu nán jiě,xìng liǎn xiāng xiāo yù zhuāng tái,liǔ yāo kuān tuì luó qún dài.", "chūn yǐ guī,huā yòu kāi,rén wèi lái.", "lè xián yuǎn shì fēi,xún xiāo sǎ,dì nuǎn jiāng nán yàn yí jiā,rén xián shuǐ běi chūn wú jià.", "yī pǐn chá,wǔ sè guā,sì jì huā."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-463','双调・清江引独酌',NULL,'张可久',NULL,'元','元曲',FALSE,'["玉笛一声天地愁，便觉梅花瘦。", "寒流清浅时，明月黄昏后，独醉一樽桑落酒。", "夜景醺醺绮罗欢笑彻，檀板歌声歇。", "宝鼎串香绝，银烛灯花谢，玳筵前酒阑人散也。", "情描金翠钿侵鬓贴，满口儿喷兰麝。", "檀板撒红牙，皓齿歌白雪，定不定百般娇又怯。"]'::jsonb,'["yù dí yī shēng tiān dì chóu,biàn jué méi huā shòu.", "hán liú qīng qiǎn shí,míng yuè huáng hūn hòu,dú zuì yī zūn sāng luò jiǔ.", "yè jǐng xūn xūn qǐ luó huān xiào chè,tán bǎn gē shēng xiē.", "bǎo dǐng chuàn xiāng jué,yín zhú dēng huā xiè,dài yán qián jiǔ lán rén sàn yě.", "qíng miáo jīn cuì diàn qīn bìn tiē,mǎn kǒu ér pēn lán shè.", "tán bǎn sā hóng yá,hào chǐ gē bái xuě,dìng bù dìng bǎi bān jiāo yòu qiè."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-464','越调・小桃红湖亭秋夜',NULL,'张可久',NULL,'元','元曲',FALSE,'["锦鸳偷占藕花汀，花影涵秋镜。", "人倚阑干叹孤另，掩围屏，伤心眼见秋成病。", "月明吊影，风清遣兴，玉手寄银筝。"]'::jsonb,'["jǐn yuān tōu zhàn ǒu huā tīng,huā yǐng hán qiū jìng.", "rén yǐ lán gān tàn gū lìng,yǎn wéi píng,shāng xīn yǎn jiàn qiū chéng bìng.", "yuè míng diào yǐng,fēng qīng qiǎn xīng,yù shǒu jì yín zhēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-465','双调・沉醉东风湖上晚眺',NULL,'张可久',NULL,'元','元曲',FALSE,'["林君复先生故居，苏子瞻学士西湖。", "六月天，孤山路，载笙歌画船无数。", "万顷玻璃浸玉壶，夕阳外荷花带雨。", "晚春席上客坐松根看水，鹤来庭下观棋。", "小砚香，残红坠，竹珊珊野亭交翠。", "相伴闲云出岫迟，题诗在呼猿洞里。"]'::jsonb,'["lín jūn fù xiān shēng gù jū,sū zǐ zhān xué shì xī hú.", "liù yuè tiān,gū shān lù,zài shēng gē huà chuán wú shù.", "wàn qǐng bō lí jìn yù hú,xī yáng wài hé huā dài yǔ.", "wǎn chūn xí shàng kè zuò sōng gēn kàn shuǐ,hè lái tíng xià guān qí.", "xiǎo yàn xiāng,cán hóng zhuì,zhú shān shān yě tíng jiāo cuì.", "xiāng bàn xián yún chū xiù chí,tí shī zài hū yuán dòng lǐ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-466','双调・水仙子维扬遇雪',NULL,'张可久',NULL,'元','元曲',FALSE,'["芦汀渐渐蟹行沙，梅月昏昏鹤到家，梨云冉冉蝶初化。", "透朱帘敲翠瓦，莫吹箫不必烹茶。", "玉蓑衣人堪画，金盘露酒旋打，预赏琼花。", "道院即事炉中真贡长黄芽，亭上仙桃绽碧花，吟边苦茗延清话。", "玄玄仙子家，小舟横浅水平沙。", "芳草眠驯兔，绿杨啼乳鸦，门掩青霞。"]'::jsonb,'["lú tīng jiàn jiàn xiè xíng shā,méi yuè hūn hūn hè dào jiā,lí yún rǎn rǎn dié chū huà.", "tòu zhū lián qiāo cuì wǎ,mò chuī xiāo bù bì pēng chá.", "yù suō yī rén kān huà,jīn pán lù jiǔ xuán dǎ,yù shǎng qióng huā.", "dào yuàn jí shì lú zhōng zhēn gòng zhǎng huáng yá,tíng shàng xiān táo zhàn bì huā,yín biān kǔ míng yán qīng huà.", "xuán xuán xiān zi jiā,xiǎo zhōu héng qiǎn shuǐ píng shā.", "fāng cǎo mián xùn tù,lǜ yáng tí rǔ yā,mén yǎn qīng xiá."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-467','双调・殿前欢春游',NULL,'张可久',NULL,'元','元曲',FALSE,'["上花台，落红沾满绿罗鞋。", "谁家庭院秋千外，兰麝裙钗。", "我闲将笑口开，也待了芳春债，何处把新诗卖。", "无情蝶怨，不饮莺猜。", "湖上夜游湖，翠屏飞上玉蟾蜍。", "粉墙犹记题诗处，树影扶疏。", "写新诗作画图，雪老西泠渡，花谢孤山路。", "林逋领鹤，潘苑骑驴。"]'::jsonb,'["shàng huā tái,luò hóng zhān mǎn lǜ luó xié.", "shuí jiā tíng yuàn qiū qiān wài,lán shè qún chāi.", "wǒ xián jiāng xiào kǒu kāi,yě dài le fāng chūn zhài,hé chù bǎ xīn shī mài.", "wú qíng dié yuàn,bù yǐn yīng cāi.", "hú shàng yè yóu hú,cuì píng fēi shàng yù chán chú.", "fěn qiáng yóu jì tí shī chù,shù yǐng fú shū.", "xiě xīn shī zuò huà tú,xuě lǎo xī líng dù,huā xiè gū shān lù.", "lín bū lǐng hè,pān yuàn qí lǘ."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-468','越调・小桃红湖上和刘时中二首',NULL,'张可久',NULL,'元','元曲',FALSE,'["一声娇燕绿杨枝，满眼寻芳事。", "塔影雷峰水边寺，夕阳时，画船无数围花市。", "三弦玉指，双钩草字，题赠粉团儿。", "棹歌惊起锦鸳鸯，开宴新亭上。", "诗有新题酒无量，醉何妨？长吟笑倚阑干望。", "西湖夜凉，吴姬低唱，画舫宿荷香。"]'::jsonb,'["yī shēng jiāo yàn lǜ yáng zhī,mǎn yǎn xún fāng shì.", "tǎ yǐng léi fēng shuǐ biān sì,xī yáng shí,huà chuán wú shù wéi huā shì.", "sān xián yù zhǐ,shuāng gōu cǎo zì,tí zèng fěn tuán ér.", "zhào gē jīng qǐ jǐn yuān yāng,kāi yàn xīn tíng shàng.", "shī yǒu xīn tí jiǔ wú liàng,zuì hé fáng?cháng yín xiào yǐ lán gān wàng.", "xī hú yè liáng,wú jī dī chàng,huà fǎng sù hé xiāng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-469','双调・庆东原春日',NULL,'张可久',NULL,'元','元曲',FALSE,'["莺啼昼，人倚楼，酒痕淹透香罗柚。", "蔷薇水蘸手，荔枝浆爽口，琼花露扶头。", "有意送春归，无奈伤春瘦。"]'::jsonb,'["yīng tí zhòu,rén yǐ lóu,jiǔ hén yān tòu xiāng luó yòu.", "qiáng wēi shuǐ zhàn shǒu,lì zhī jiāng shuǎng kǒu,qióng huā lù fú tóu.", "yǒu yì sòng chūn guī,wú nài shāng chūn shòu."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-470','双调・庆东原青田九楼山舟中作',NULL,'乔吉',NULL,'元','元曲',FALSE,'["渺渺山头路，鳞鳞山上田，绕篷窗六曲屏风面。", "似丹青辋川，是神仙洞天，隔云树人烟，试看玉溪边，恐有桃花片。"]'::jsonb,'["miǎo miǎo shān tóu lù,lín lín shān shàng tián,rào péng chuāng liù qū píng fēng miàn.", "shì dān qīng wǎng chuān,shì shén xiān dòng tiān,gé yún shù rén yān,shì kàn yù xī biān,kǒng yǒu táo huā piàn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-471','中吕・普天乐湘阳道中',NULL,'卢挚',NULL,'元','元曲',FALSE,'["岳阳来，湘阳路。", "望炊烟田舍，掩映沟渠。", "山远近，云来去。", "溪上招提烟中树，看时见三两樵渔。", "凭谁画出，行人得句，不用前驱。"]'::jsonb,'["yuè yáng lái,xiāng yáng lù.", "wàng chuī yān tián shè,yǎn yìng gōu qú.", "shān yuǎn jìn,yún lái qù.", "xī shàng zhāo tí yān zhōng shù,kàn shí jiàn sān liǎng qiáo yú.", "píng shuí huà chū,xíng rén dé jù,bù yòng qián qū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-472','越调・小桃红',NULL,'卢挚',NULL,'元','元曲',FALSE,'["寿筵添上小桃红，妆点壶天供，茜蕊冰痕半浮动。", "彩云中，生香唤醒罗浮梦。", "银杯绿蚁，琼枝清唱，金胜醉鳌峰。"]'::jsonb,'["shòu yán tiān shàng xiǎo táo hóng,zhuāng diǎn hú tiān gōng,qiàn ruǐ bīng hén bàn fú dòng.", "cǎi yún zhōng,shēng xiāng huàn xǐng luó fú mèng.", "yín bēi lǜ yǐ,qióng zhī qīng chàng,jīn shèng zuì áo fēng."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-473','越调・小桃红花篮区髻',NULL,'徐再思',NULL,'元','元曲',FALSE,'["东风攒簇一筐春，吹在秋蝉鬓，玉露凝香宝钗润。", "绿无尘，同心双挽蜂蝶阵。", "群芳顶上，连环枝下，分断楚山云。"]'::jsonb,'["dōng fēng zǎn cù yī kuāng chūn,chuī zài qiū chán bìn,yù lù níng xiāng bǎo chāi rùn.", "lǜ wú chén,tóng xīn shuāng wǎn fēng dié zhèn.", "qún fāng dǐng shàng,lián huán zhī xià,fēn duàn chǔ shān yún."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-474','正宫・醉太平失题',NULL,'贯云石',NULL,'元','元曲',FALSE,'["长街上告人，破窑里安身，挨的是一年春尽一年春，谁承望眷姻？红鸾来照孤辰运，白身合有姻缘分，绣球落处便成亲，因此上忍著疼撞门。"]'::jsonb,'["cháng jiē shàng gào rén,pò yáo lǐ ān shēn,āi de shì yī nián chūn jǐn yī nián chūn,shuí chéng wàng juàn yīn?hóng luán lái zhào gū chén yùn,bái shēn hé yǒu yīn yuán fēn,xiù qiú luò chù biàn chéng qīn,yīn cǐ shàng rěn zhù téng zhuàng mén."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-475','中吕・阳春曲金莲',NULL,'贯云石',NULL,'元','元曲',FALSE,'["金莲早自些娘大，着意收拾越逞过。", "如今相识眼皮儿薄，休显豁，越遮护着越情多。"]'::jsonb,'["jīn lián zǎo zì xiē niáng dà,zhuó yì shōu shí yuè chěng guò.", "rú jīn xiāng shí yǎn pí ér báo,xiū xiǎn huò,yuè zhē hù zhe yuè qíng duō."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-476','中吕・醉高歌过红绣鞋',NULL,'贯云石',NULL,'元','元曲',FALSE,'["看别人鞍马上胡颜，叹自己如尘世污眼。", "英雄谁识男儿汉，岂肯向人行诉难？阳气盛冰消北岸，暮云遮日落西山，四时天气尚轮还。", "秦甘罗疾发禄，姜吕望晚登坛，迟和疾时运里趱。"]'::jsonb,'["kàn bié rén ān mǎ shàng hú yán,tàn zì jǐ rú chén shì wū yǎn.", "yīng xióng shuí shí nán ér hàn,qǐ kěn xiàng rén xíng sù nán?yáng qì shèng bīng xiāo běi àn,mù yún zhē rì luò xī shān,sì shí tiān qì shàng lún hái.", "qín gān luó jí fā lù,jiāng lǚ wàng wǎn dēng tán,chí hé jí shí yùn lǐ zǎn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-477','中吕・醉高歌过喜春来题情',NULL,'贯云石',NULL,'元','元曲',FALSE,'["自然体态温柔，可意庞儿奈羞。", "看时节偷眼将人溜，送与人些风流证候。", "蜂媒蝶使空迤逗，燕子莺儿不自由。", "恰便似一枝红杏出墙头，不能够折入手，空教人风雨替花羞。"]'::jsonb,'["zì rán tǐ tài wēn róu,kě yì páng ér nài xiū.", "kàn shí jié tōu yǎn jiāng rén liū,sòng yǔ rén xiē fēng liú zhèng hòu.", "fēng méi dié shǐ kōng yí dòu,yàn zi yīng ér bù zì yóu.", "qià biàn shì yī zhī hóng xìng chū qiáng tóu,bù néng gòu zhé rù shǒu,kōng jiào rén fēng yǔ tì huā xiū."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-478','正宫・塞鸿秋浔阳即景',NULL,'周德清',NULL,'元','元曲',FALSE,'["长江万里白如练，淮山数点青如淀。", "江帆几片疾如箭，山泉千尺飞如电。", "晚云都变露，新月初学扇，塞鸿一字来如线。", "灞桥雪拥驴难跨，剡溪水冻船难驾；秦楼美酝添高价，陶家风味都闲话。", "羊羔饮兴佳，金帐歌声罢，醉魂不到蓝关下。"]'::jsonb,'["cháng jiāng wàn lǐ bái rú liàn,huái shān shù diǎn qīng rú diàn.", "jiāng fān jǐ piàn jí rú jiàn,shān quán qiān chǐ fēi rú diàn.", "wǎn yún dōu biàn lù,xīn yuè chū xué shàn,sāi hóng yī zì lái rú xiàn.", "bà qiáo xuě yōng lǘ nán kuà,shàn xī shuǐ dòng chuán nán jià;qín lóu měi yùn tiān gāo jià,táo jiā fēng wèi dōu xián huà.", "yáng gāo yǐn xīng jiā,jīn zhàng gē shēng bà,zuì hún bú dào lán guān xià."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-479','越调・天净沙嘲歌者茶茶',NULL,'周德清',NULL,'元','元曲',FALSE,'["根窠生长灵芽，旗枪搠立烟花，不许冯魁串瓦。", "休抬高价，小舟来贩茶茶。", "舟阻女儿港庐山面已难寻，孤山鞋不曾沉，掩面留鞋意深。", "不知因甚，女儿港到如今。"]'::jsonb,'["gēn kē shēng zhǎng líng yá,qí qiāng shuò lì yān huā,bù xǔ féng kuí chuàn wǎ.", "xiū tái gāo jià,xiǎo zhōu lái fàn chá chá.", "zhōu zǔ nǚ ér gǎng lú shān miàn yǐ nán xún,gū shān xié bù céng chén,yǎn miàn liú xié yì shēn.", "bù zhī yīn shèn,nǚ ér gǎng dào rú jīn."]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('base-480','山坡羊・潼关怀古',NULL,'张养浩',NULL,'元','元曲',FALSE,'["峰峦如聚，波涛如怒，山河表里潼关路。", "望西都，意踌躇。", "伤心秦汉经行处，宫阙万间都做了土。", "兴，百姓苦；亡，百姓苦！"]'::jsonb,'["fēng luán rú jù,bō tāo rú nù,shān hé biǎo lǐ tóng guān lù.", "wàng xī dōu,yì chóu chú.", "shāng xīn qín hàn jīng xíng chù,gōng què wàn jiān dōu zuò le tǔ.", "xīng,bǎi xìng kǔ;wáng,bǎi xìng kǔ!"]'::jsonb,TRUE,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)
